INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C8','sci',4,1,'u2',2,'손에 칠한 물의 행방 — 붓으로 손에 칠한 물이 점점 줄어 보이지 않게 됨 = 수증기가 되어 공기 중으로(액체에서 기체로) · 없어진 것이 아님',ARRAY['[4과10-01] 물이 세 가지 상태로 변할 수 있음을 알고, 우리 주변에서 예를 찾을 수 있다(지도서 성취기준 · W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
