INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C22','sci',4,1,'u2',4,'관찰 방법과 안전 — 높이를 색이 다른 유성펜으로 표시해 높이 변화로 견줌(정확한 수치 비교 X) · 무게는 저울 · 차가운 비커는 면장갑 · 유리 기구 조심',ARRAY['[4과10-02] 물이 얼 때, 얼음이 녹을 때, 물이 증발할 때와 끓을 때, 수증기가 응결할 때의 변화를 관찰할 수 있다(지도서 성취기준 · W7 확인)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C23','sci',4,1,'u2',5,'증발 — 액체인 물이 표면에서 기체인 수증기로 변해 공기 중으로 날아가는 현상 · 햇빛 드는 곳 비커의 물 높이가 며칠에 걸쳐 조금씩 낮아짐',ARRAY['[4과10-02] 물이 얼 때, 얼음이 녹을 때, 물이 증발할 때와 끓을 때, 수증기가 응결할 때의 변화를 관찰할 수 있다(지도서 성취기준 · W7 확인)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C24','sci',4,1,'u2',5,'끓음 — 물의 표면뿐만 아니라 물속에서도 물이 수증기로 변하는 현상 · 처음엔 변화가 거의 없다가 작은 기포 → 물 전체에서 크고 작은 기포가 계속 생기고 터지며 표면이 출렁 · 끓은 뒤 높이가 낮아짐',ARRAY['[4과10-02] 물이 얼 때, 얼음이 녹을 때, 물이 증발할 때와 끓을 때, 수증기가 응결할 때의 변화를 관찰할 수 있다(지도서 성취기준 · W7 확인)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C25','sci',4,1,'u2',5,'증발과 끓음의 공통점 — 둘 다 액체인 물이 기체인 수증기로 변해 물의 양이 줄어듦 · 일어나는 곳(표면 / 표면과 물속)과 빠르기는 다름',ARRAY['[4과10-02] 물이 얼 때, 얼음이 녹을 때, 물이 증발할 때와 끓을 때, 수증기가 응결할 때의 변화를 관찰할 수 있다(지도서 성취기준 · W7 확인)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C26','sci',4,1,'u2',5,'수증기는 주위에 있음 — 수증기는 물의 기체 상태로 눈에 보이지 않을 뿐 주위에 있음 — 사라져 없어진 것이 아님',ARRAY['[4과10-02] 물이 얼 때, 얼음이 녹을 때, 물이 증발할 때와 끓을 때, 수증기가 응결할 때의 변화를 관찰할 수 있다(지도서 성취기준 · W7 확인)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C27','sci',4,1,'u2',5,'증발의 예와 이용 — 젖은 빨래·인형이 마름·오징어·곶감 말리기(햇빛·바람)·염전 소금·머리 말리개 · 호수·운동장에 고인 물이 줄어듦',ARRAY['[4과10-02] 물이 얼 때, 얼음이 녹을 때, 물이 증발할 때와 끓을 때, 수증기가 응결할 때의 변화를 관찰할 수 있다(지도서 성취기준 · W7 확인)']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C28','sci',4,1,'u2',5,'끓음의 예와 안전 — 달걀 삶기·만두 찌기·차 마실 물 끓이기 · 주전자의 물을 계속 가열하면 물이 계속 줄어듦 · 보안경·면장갑, 가열 중 가까이 가지 않기, 끈 뒤에도 뜨거움',ARRAY['[4과10-02] 물이 얼 때, 얼음이 녹을 때, 물이 증발할 때와 끓을 때, 수증기가 응결할 때의 변화를 관찰할 수 있다(지도서 성취기준 · W7 확인)']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C29','sci',4,1,'u2',6,'얼음이 든 비커의 바깥면 관찰 — 주스만 넣은 비커와 얼음과 주스를 넣은 비커를 견줌 · 얼음을 넣은 비커 바깥면에만 물방울이 맺히고 커지면 흘러내려 접시에 고임',ARRAY['[4과10-02] 물이 얼 때, 얼음이 녹을 때, 물이 증발할 때와 끓을 때, 수증기가 응결할 때의 변화를 관찰할 수 있다(지도서 성취기준 · W7 확인)']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C30','sci',4,1,'u2',6,'물방울은 어디에서 왔나 — 바깥면을 닦은 휴지는 젖었지만 주스 색이 없음 · 물방울이 맺히면 무게가 늘고(423.1 g → 425.1 g) 닦으면 처음 무게 · 공기 중 수증기가 차가운 바깥면에 닿아 물로 변한 것',ARRAY['[4과10-02] 물이 얼 때, 얼음이 녹을 때, 물이 증발할 때와 끓을 때, 수증기가 응결할 때의 변화를 관찰할 수 있다(지도서 성취기준 · W7 확인)']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C31','sci',4,1,'u2',6,'응결 — 기체인 수증기가 액체인 물로 상태가 변하는 현상',ARRAY['[4과10-02] 물이 얼 때, 얼음이 녹을 때, 물이 증발할 때와 끓을 때, 수증기가 응결할 때의 변화를 관찰할 수 있다(지도서 성취기준 · W7 확인)']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C32','sci',4,1,'u2',6,'응결의 예 — 거미줄·풀잎의 이슬·따뜻한 차를 마실 때 안경이 흐려짐·욕실 거울·겨울 유리창 안쪽·냉동실에서 꺼낸 물병 · 냄비 뚜껑 안쪽 물방울(상대적으로 차가운 뚜껑)',ARRAY['[4과10-02] 물이 얼 때, 얼음이 녹을 때, 물이 증발할 때와 끓을 때, 수증기가 응결할 때의 변화를 관찰할 수 있다(지도서 성취기준 · W7 확인)']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C33','sci',4,1,'u2',6,'얼음·물·수증기 사이 네 방향 정리 — 물이 얾 → 얼음 · 얼음이 녹음 → 물 · 증발·끓음 → 수증기 · 응결 → 물 · 증발과 응결은 반대 방향',ARRAY['[4과10-02] 물이 얼 때, 얼음이 녹을 때, 물이 증발할 때와 끓을 때, 수증기가 응결할 때의 변화를 관찰할 수 있다(지도서 성취기준 · W7 확인)']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C34','sci',4,1,'u2',7,'물의 중요성과 물 부족의 원인 — 우리 몸을 이루고 동물·식물이 살아가고 농사·가축·공장에 필요 · 물 부족 원인 = 인구 증가·가뭄·폭염·산업 발달·환경 오염',ARRAY['[4과10-03] 물의 상태 변화를 이용하여 물을 얻을 수 있는 장치를 설계하고 만들 수 있다(지도서 성취기준 · W7 확인)']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C35','sci',4,1,'u2',7,'와카워터 — 공기 중의 수증기가 응결하는 것을 이용해 물을 모으는 장치 · 물이 부족한 곳·낮과 밤의 기온 차가 큰 곳 · 환경 오염 없이 물을 얻음',ARRAY['[4과10-03] 물의 상태 변화를 이용하여 물을 얻을 수 있는 장치를 설계하고 만들 수 있다(지도서 성취기준 · W7 확인)']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C36','sci',4,1,'u2',7,'물의 상태 변화를 이용한 여러 장치 — 워터콘·솔라볼(흙탕물·바닷물이 햇빛에 증발 → 응결 → 깨끗한 물) · 그물망 포집기(공기 중 물방울) · 빗물 저금통은 상태 변화를 이용하지 않음',ARRAY['[4과10-03] 물의 상태 변화를 이용하여 물을 얻을 수 있는 장치를 설계하고 만들 수 있다(지도서 성취기준 · W7 확인)']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
