INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C38','sci',4,1,'u2',7,'장치 속 상태 변화 — 큰 그릇의 물이 증발 → 비닐 안쪽에서 응결 → 물방울이 빗면을 따라 흘러 작은 그릇에 떨어짐 · 색소·흙·소금은 남고 물만 이동해 모인 물은 깨끗하고 색이 없음',ARRAY['[4과10-03] 물의 상태 변화를 이용하여 물을 얻을 수 있는 장치를 설계하고 만들 수 있다(지도서 성취기준 · W7 확인)']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C39','sci',4,1,'u2',7,'설계와 평가 — 어떤 상태 변화를 이용할지·쉽게 구할 수 있는 재료·간단하고 알아보기 쉬운 설계도 · 잘 만들었는지보다 상태 변화를 이용해 설계했는지에 중점',ARRAY['[4과10-03] 물의 상태 변화를 이용하여 물을 얻을 수 있는 장치를 설계하고 만들 수 있다(지도서 성취기준 · W7 확인)']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C40','sci',4,1,'u2',7,'쓸 수 있는 물은 충분하지 않음 — 지구 전체 물의 양은 변하지 않지만 인구 증가·산업 발달 등으로 쓸 수 있는 물은 점점 줄어듦 · 쓴 물을 다시 쓰려면 오랜 시간과 많은 비용',ARRAY['[4과10-03] 물의 상태 변화를 이용하여 물을 얻을 수 있는 장치를 설계하고 만들 수 있다(지도서 성취기준 · W7 확인)']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
