INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C44','sci',4,1,'u2',8,'작은 실천이 모여 큰 변화 — 개인의 작은 실천이 모여 큰 변화 · 물 부족 문제 해결·미래 세대의 깨끗한 환경 · 지금 나부터',ARRAY['[4과10-03] 물의 상태 변화를 이용하여 물을 얻을 수 있는 장치를 설계하고 만들 수 있다(지도서 성취기준 · W7 확인)']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u2-C45','sci',4,1,'u2',8,'생태 전환 교육 기념일 — 세계 물의 날 3월 22일 · 지구의 날 4월 22일(지구 환경 보호) · 생물 다양성의 날 5월 22일 · 세계 환경의 날 6월 5일 · 푸른 하늘의 날 9월 7일(대기, 우리나라 제안)',ARRAY['[4과10-03] 물의 상태 변화를 이용하여 물을 얻을 수 있는 장치를 설계하고 만들 수 있다(지도서 성취기준 · W7 확인)']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X01','sci',4,'u2',ARRAY['SC4-1-u2-C1']::text[],'얼음처럼 단단한 것은 물이 아니라고 여긴다','얼음도 물이에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X02','sci',4,'u2',ARRAY['SC4-1-u2-C2','SC4-1-u2-C3']::text[],'물은 액체 상태로만 있다고 여긴다','세 가지 상태') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X03','sci',4,'u2',ARRAY['SC4-1-u2-C3']::text[],'눈에 보이지 않으면 물이 없다고 여긴다','안 보여도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X04','sci',4,'u2',ARRAY['SC4-1-u2-C1','SC4-1-u2-C2']::text[],'고체와 액체 상태를 뒤바꿔 판단한다','단단한가, 흐르나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X05','sci',4,'u2',ARRAY['SC4-1-u2-C4']::text[],'남극·높은 산 위의 물 상태나 생물 몸속의 물을 엉뚱하게 안다','아주 추운 곳은 고체') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X06','sci',4,'u2',ARRAY['SC4-1-u2-C5']::text[],'얼음·물·수증기와 고체·액체·기체의 짝을 뒤바꾼다','얼음 고체 · 물 액체 · 수증기 기체') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X07','sci',4,'u2',ARRAY['SC4-1-u2-C6']::text[],'얼음과 물의 특징을 뒤바꾼다(얼음이 흐름·물이 일정한 모양)','단단한 얼음 · 흐르는 물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X08','sci',4,'u2',ARRAY['SC4-1-u2-C8','SC4-1-u2-C26']::text[],'물이 수증기로 변하면 사라져 없어진다고 여긴다','보이지 않을 뿐 주위에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X09','sci',4,'u2',ARRAY['SC4-1-u2-C7']::text[],'얼음이 녹을 때 얼음과 물의 양이 변하는 모습을 거꾸로 안다','얼음 작아지고 물 많아짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X10','sci',4,'u2',ARRAY['SC4-1-u2-C9']::text[],'옮겨 담거나 모양만 바뀌어도 상태 변화라고 여긴다','다른 상태로 변해야') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X11','sci',4,'u2',ARRAY['SC4-1-u2-C9']::text[],'물의 상태 변화는 한 방향으로만 일어나 되돌아갈 수 없다고 여긴다','얼음↔물 · 물↔수증기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X12','sci',4,'u2',ARRAY['SC4-1-u2-C10']::text[],'물이 액체로만 있어도 생활이 달라지지 않는다고 여긴다','얼음도 없고 마르지도 않아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X13','sci',4,'u2',ARRAY['SC4-1-u2-C10','SC4-1-u2-C22']::text[],'얼음을 오래 만지거나 맛보는 등 실험 안전을 지키지 않는다','맛보지 않기 · 면장갑') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X14','sci',4,'u2',ARRAY['SC4-1-u2-C11']::text[],'얼음과 물 사이 상태 변화의 방향을 뒤바꾼다','녹으면 고체→액체') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X15','sci',4,'u2',ARRAY['SC4-1-u2-C12']::text[],'물이 수증기로 변하는 예를 다른 방향의 변화로 여긴다','마르면 물→수증기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X16','sci',4,'u2',ARRAY['SC4-1-u2-C13']::text[],'이슬·차가운 물체의 물방울을 하늘이나 물체 속에서 나온 물로 여긴다','공기 중 수증기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X17','sci',4,'u2',ARRAY['SC4-1-u2-C11','SC4-1-u2-C12','SC4-1-u2-C13']::text[],'물의 상태 변화는 실험실에서만 볼 수 있다고 여긴다','우리 주변 곳곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X18','sci',4,'u2',ARRAY['SC4-1-u2-C14']::text[],'녹아 생긴 물은 그대로 남고 더 변하지 않는다고 여긴다','다시 수증기로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X19','sci',4,'u2',ARRAY['SC4-1-u2-C15']::text[],'조사할 때 출처를 확인하지 않고 아무 정보나 믿는다','출처 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X20','sci',4,'u2',ARRAY['SC4-1-u2-C16']::text[],'물이 얼면 부피가 줄어들거나 그대로라고 여긴다','얼면 높아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X21','sci',4,'u2',ARRAY['SC4-1-u2-C17','SC4-1-u2-C19']::text[],'물이 얼어 부피가 늘어나면 무게도 늘어난다고 여긴다','무게는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X22','sci',4,'u2',ARRAY['SC4-1-u2-C18']::text[],'얼음이 녹으면 무게가 줄어든다고 여긴다','녹아도 무게는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X23','sci',4,'u2',ARRAY['SC4-1-u2-C18']::text[],'얼음이 녹으면 부피가 늘어난다고 여긴다','녹으면 낮아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X24','sci',4,'u2',ARRAY['SC4-1-u2-C19']::text[],'부피가 크면 언제나 더 무겁다고 여긴다','스펀지와 쇠 덩어리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X25','sci',4,'u2',ARRAY['SC4-1-u2-C20','SC4-1-u2-C21']::text[],'생활 속 부피 변화의 까닭을 엉뚱하게 안다(추워서 약해짐·새어 나감)','부피가 변해서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X26','sci',4,'u2',ARRAY['SC4-1-u2-C22']::text[],'높이를 표시하지 않고 눈대중이나 엉뚱한 방법으로 부피 변화를 본다','높이를 표시해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X27','sci',4,'u2',ARRAY['SC4-1-u2-C23']::text[],'증발은 물이 끓을 만큼 뜨거울 때만 일어난다고 여긴다','햇빛 아래에서도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X28','sci',4,'u2',ARRAY['SC4-1-u2-C23','SC4-1-u2-C24']::text[],'증발·끓음 뒤 물의 높이가 그대로이거나 높아진다고 여긴다','높이가 낮아져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X29','sci',4,'u2',ARRAY['SC4-1-u2-C24']::text[],'끓을 때 물 표면에서만 변하거나 기포가 생기지 않는다고 여긴다','물속에서도 기포') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X30','sci',4,'u2',ARRAY['SC4-1-u2-C25']::text[],'증발과 끓음은 전혀 다른 상태 변화라고 여긴다(물이 얼음이 됨 등)','둘 다 물→수증기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X31','sci',4,'u2',ARRAY['SC4-1-u2-C23','SC4-1-u2-C24']::text[],'증발과 끓음의 이름이나 일어나는 곳을 뒤바꾼다','표면 = 증발 · 물속도 = 끓음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X32','sci',4,'u2',ARRAY['SC4-1-u2-C27','SC4-1-u2-C28']::text[],'증발을 이용한 예와 끓음을 이용한 예를 뒤바꾼다','말리기 = 증발 · 끓이기 = 끓음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X33','sci',4,'u2',ARRAY['SC4-1-u2-C28']::text[],'가열 기구를 끈 뒤 바로 만지는 등 가열 안전을 지키지 않는다','끈 뒤에도 뜨거워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X34','sci',4,'u2',ARRAY['SC4-1-u2-C30']::text[],'차가운 그릇 바깥면의 물방울이 그릇 속에서 새어 나왔다고 여긴다','색이 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X35','sci',4,'u2',ARRAY['SC4-1-u2-C29']::text[],'얼음을 넣지 않은 비커에도 똑같이 물방울이 맺힌다고 여긴다','차가운 쪽만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X36','sci',4,'u2',ARRAY['SC4-1-u2-C31','SC4-1-u2-C33']::text[],'응결과 증발의 방향이나 이름을 뒤바꾼다','응결 = 수증기→물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X37','sci',4,'u2',ARRAY['SC4-1-u2-C32']::text[],'응결의 예를 엉뚱하게 고른다(빨래가 마름·얼음이 녹음)','수증기가 물로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X38','sci',4,'u2',ARRAY['SC4-1-u2-C30']::text[],'물방울이 맺힌 비커의 무게 변화를 거꾸로 안다','물방울만큼 늘어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X39','sci',4,'u2',ARRAY['SC4-1-u2-C32']::text[],'응결이 차가운 면 없이 또는 뜨거운 면에서 일어난다고 여긴다','차가운 면에 닿아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X40','sci',4,'u2',ARRAY['SC4-1-u2-C40','SC4-1-u2-C42']::text[],'지구에 물이 많으니 쓸 수 있는 물도 충분하다고 여긴다','쓸 수 있는 물은 적어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X41','sci',4,'u2',ARRAY['SC4-1-u2-C35','SC4-1-u2-C36']::text[],'장치가 이용한 상태 변화를 잘못 안다(얼음을 녹임·끓임)','증발과 응결') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u2-X42','sci',4,'u2',ARRAY['SC4-1-u2-C36']::text[],'상태 변화를 이용하지 않는 장치도 같은 원리라고 여긴다','상태가 변하나요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
