INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L01_basic#3','sci',4,1,'u2','L01','g4_1_sci_u2_L01_basic','lesson_basic','SC4-1-u2-C3',1,'ox','auto','끓는 주전자 주변에는 눈에 보이지 않는 물이 있어요.',ARRAY['SC4-1-u2-X03']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C3","difficulty":1,"kind":"ox","stem":"끓는 주전자 주변에는 눈에 보이지 않는 물이 있어요.","answer":"O","reason_options":[{"t":"기체 상태의 물은 눈에 보이지 않기 때문에","correct":true},{"t":"눈에 보이는 것만 물이기 때문에","mis":"SC4-1-u2-X03"}],"mis":"SC4-1-u2-X03","explanation":["주전자 주변을 떠올려요.","보이지 않아도 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
