INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L01_basic#5','sci',4,1,'u2','L01','g4_1_sci_u2_L01_basic','lesson_basic','SC4-1-u2-C3',2,'mc','auto','기체 상태의 물에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X04','SC4-1-u2-X03']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C3","difficulty":2,"kind":"mc","stem":"기체 상태의 물에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"눈에 보이지 않지만 공기 중에 있다","correct":true},{"t":"손으로 잡을 수 있다","mis":"SC4-1-u2-X04"},{"t":"흘러서 그릇 모양이 된다","mis":"SC4-1-u2-X04"},{"t":"보이지 않으니 물이 아니다","mis":"SC4-1-u2-X03"}],"explanation":["기체를 떠올려요.","보이지 않아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L01_basic#6','sci',4,1,'u2','L01','g4_1_sci_u2_L01_basic','lesson_basic','SC4-1-u2-C2',2,'match','auto','그림 속 물과 그 상태를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-1-u2-C2","difficulty":2,"kind":"match","stem":"그림 속 물과 그 상태를 알맞게 이으세요.","pairs":[{"l":"얼음 틀 속 얼음","r":"고체"},{"l":"오리가 헤엄치는 호수의 물","r":"액체"},{"l":"공기 중에 있는 보이지 않는 물","r":"기체"}],"mis":"SC4-1-u2-X04","explanation":["단단한가요?","흐르나요? 보이나요?","하나씩 이어요."],"asset":{"type":"passage","lines":["㉠ 음료수 컵 속에 떠 있는 얼음","㉡ 화분에 주는 물","㉢ 끓는 주전자 주변의 보이지 않는 물","㉣ 오리가 헤엄치는 호수의 물","㉤ 자전거를 탈 때 흐르는 땀","㉥ 얼음 틀 속 얼음"],"title":"그림에서 찾은 물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
