INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L01_basic#10','sci',4,1,'u2','L01','g4_1_sci_u2_L01_basic','lesson_basic','SC4-1-u2-C4',3,'mc','auto','지구본에서 물을 찾아 상태를 말한 것 가운데 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X05','SC4-1-u2-X02']::text[],false,'{"seq":10,"concept":"SC4-1-u2-C4","difficulty":3,"kind":"mc","stem":"지구본에서 물을 찾아 상태를 말한 것 가운데 알맞은 것은 무엇인가요?","options":[{"t":"바다와 강의 물은 액체, 높은 산 위의 물은 고체","correct":true},{"t":"바다와 강의 물은 고체, 높은 산 위의 물은 액체","mis":"SC4-1-u2-X05"},{"t":"바다와 강의 물은 기체, 남극의 물은 액체","mis":"SC4-1-u2-X05"},{"t":"지구본에서는 액체 상태의 물만 찾을 수 있다","mis":"SC4-1-u2-X02"}],"explanation":["바다는 흘러요.","높은 산 위는 추워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
