INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L01_challenge#2','sci',4,1,'u2','L01','g4_1_sci_u2_L01_challenge','lesson_challenge','SC4-1-u2-C1',2,'mc','auto','얼음 틀 속 얼음과 음료수 속 얼음의 같은 점은 무엇인가요?',ARRAY['SC4-1-u2-X04','SC4-1-u2-X01','SC4-1-u2-X03']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C1","difficulty":2,"kind":"mc","stem":"얼음 틀 속 얼음과 음료수 속 얼음의 같은 점은 무엇인가요?","options":[{"t":"둘 다 고체 상태의 물이다","correct":true},{"t":"둘 다 액체 상태의 물이다","mis":"SC4-1-u2-X04"},{"t":"둘 다 물이 아니다","mis":"SC4-1-u2-X01"},{"t":"둘 다 눈에 보이지 않는다","mis":"SC4-1-u2-X03"}],"explanation":["둘 다 단단해요.","모양이 일정해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L01_challenge#3','sci',4,1,'u2','L01','g4_1_sci_u2_L01_challenge','lesson_challenge','SC4-1-u2-C2',3,'error','auto','그림 속 물을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u2-X02','SC4-1-u2-X01','SC4-1-u2-X03']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C2","difficulty":3,"kind":"error","stem":"그림 속 물을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「물은 컵이나 호수처럼 액체 상태로만 있어.」","correct":true,"mis_target":"SC4-1-u2-X02"},{"t":"친구 나 — 「음료수 속 얼음도 물이야.」","mis":"SC4-1-u2-X01"},{"t":"친구 다 — 「주전자 주변에는 보이지 않는 물도 있어.」","mis":"SC4-1-u2-X03"}],"explanation":["세 가지 상태를 떠올려요.","얼음도, 보이지 않는 물도 있어요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 음료수 컵 속에 떠 있는 얼음","㉡ 화분에 주는 물","㉢ 끓는 주전자 주변의 보이지 않는 물","㉣ 오리가 헤엄치는 호수의 물","㉤ 자전거를 탈 때 흐르는 땀","㉥ 얼음 틀 속 얼음"],"title":"그림에서 찾은 물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L01_challenge#4','sci',4,1,'u2','L01','g4_1_sci_u2_L01_challenge','lesson_challenge','SC4-1-u2-C2',3,'mc','auto','「그림에서 찾은 물」에서 액체 상태의 물끼리 묶은 것은 무엇인가요?',ARRAY['SC4-1-u2-X04','SC4-1-u2-X03']::text[],false,'{"seq":4,"concept":"SC4-1-u2-C2","difficulty":3,"kind":"mc","stem":"「그림에서 찾은 물」에서 액체 상태의 물끼리 묶은 것은 무엇인가요?","options":[{"t":"㉡, ㉣, ㉤","correct":true},{"t":"㉠, ㉡, ㉥","mis":"SC4-1-u2-X04"},{"t":"㉢, ㉣, ㉤","mis":"SC4-1-u2-X03"},{"t":"㉠, ㉢, ㉥","mis":"SC4-1-u2-X04"}],"explanation":["흐르는 물을 찾아요.","화분 물·호수·땀이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["㉠ 음료수 컵 속에 떠 있는 얼음","㉡ 화분에 주는 물","㉢ 끓는 주전자 주변의 보이지 않는 물","㉣ 오리가 헤엄치는 호수의 물","㉤ 자전거를 탈 때 흐르는 땀","㉥ 얼음 틀 속 얼음"],"title":"그림에서 찾은 물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L01_challenge#5','sci',4,1,'u2','L01','g4_1_sci_u2_L01_challenge','lesson_challenge','SC4-1-u2-C3',3,'ox','auto','우리 주변 공기 중에도 물이 있어요.',ARRAY['SC4-1-u2-X03']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C3","difficulty":3,"kind":"ox","stem":"우리 주변 공기 중에도 물이 있어요.","answer":"O","reason_options":[{"t":"기체 상태의 물이 눈에 보이지 않게 공기 중에 있기 때문에","correct":true},{"t":"공기 중에는 물이 하나도 없기 때문에","mis":"SC4-1-u2-X03"}],"mis":"SC4-1-u2-X03","explanation":["보이지 않는 물을 떠올려요.","공기 중에 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L01_challenge#6','sci',4,1,'u2','L01','g4_1_sci_u2_L01_challenge','lesson_challenge','SC4-1-u2-C4',3,'mc','auto','우리 몸속에 있는 물은 주로 어떤 상태일까요?',ARRAY['SC4-1-u2-X05']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C4","difficulty":3,"kind":"mc","stem":"우리 몸속에 있는 물은 주로 어떤 상태일까요?","options":[{"t":"액체","correct":true},{"t":"고체","mis":"SC4-1-u2-X05"},{"t":"기체","mis":"SC4-1-u2-X05"},{"t":"몸속에는 물이 없다","mis":"SC4-1-u2-X05"}],"explanation":["땀과 침을 떠올려요.","흘러요.","액체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L01_challenge#7','sci',4,1,'u2','L01','g4_1_sci_u2_L01_challenge','lesson_challenge','SC4-1-u2-C1',3,'mc','auto','물의 상태를 바르게 판단하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X04','SC4-1-u2-X03']::text[],false,'{"seq":7,"concept":"SC4-1-u2-C1","difficulty":3,"kind":"mc","stem":"물의 상태를 바르게 판단하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"단단하고 모양이 일정하면 고체, 흐르면 액체로 본다","correct":true},{"t":"차가우면 모두 액체로 본다","mis":"SC4-1-u2-X04"},{"t":"눈에 보이지 않으면 물이 없다고 본다","mis":"SC4-1-u2-X03"},{"t":"그릇에 담겨 있으면 모두 고체로 본다","mis":"SC4-1-u2-X04"}],"explanation":["생김새를 봐요.","단단한가, 흐르나요?","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L01_challenge#8','sci',4,1,'u2','L01','g4_1_sci_u2_L01_challenge','lesson_challenge','SC4-1-u2-C4',4,'mc','auto','친구가 「높은 산 꼭대기의 하얀 눈은 물이 아니야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X01','SC4-1-u2-X05']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C4","difficulty":4,"kind":"mc","stem":"친구가 「높은 산 꼭대기의 하얀 눈은 물이 아니야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「높은 산 위의 눈도 고체 상태의 물이야.」","correct":true},{"t":"「맞아, 하얀 것은 물이 아니야.」","mis":"SC4-1-u2-X01"},{"t":"「산 위의 물은 모두 액체야.」","mis":"SC4-1-u2-X05"},{"t":"「산 위에는 물이 하나도 없어.」","mis":"SC4-1-u2-X05"}],"explanation":["눈을 떠올려요.","단단하고 차가워요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L01_challenge#9','sci',4,1,'u2','L01','g4_1_sci_u2_L01_challenge','lesson_challenge','SC4-1-u2-C3',4,'mc','auto','친구가 「끓는 주전자 주변에는 아무것도 보이지 않으니 물이 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X03','SC4-1-u2-X04','SC4-1-u2-X02']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C3","difficulty":4,"kind":"mc","stem":"친구가 「끓는 주전자 주변에는 아무것도 보이지 않으니 물이 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「기체 상태의 물은 눈에 보이지 않을 뿐 주변에 있어.」","correct":true},{"t":"「맞아, 보이는 것만 물이야.」","mis":"SC4-1-u2-X03"},{"t":"「주전자 주변의 물은 고체야.」","mis":"SC4-1-u2-X04"},{"t":"「물은 액체로만 있으니 주변에 없어.」","mis":"SC4-1-u2-X02"}],"explanation":["기체 상태의 물이에요.","보이지 않아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L01_challenge#10','sci',4,1,'u2','L01','g4_1_sci_u2_L01_challenge','lesson_challenge','SC4-1-u2-C4',4,'essay','teacher','우리 주변에서 고체, 액체, 기체 상태의 물을 하나씩 찾아 쓰고, 물에 대해 더 알고 싶은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u2-C4","difficulty":4,"kind":"essay","stem":"우리 주변에서 고체, 액체, 기체 상태의 물을 하나씩 찾아 쓰고, 물에 대해 더 알고 싶은 점을 쓰세요.","answer_guide":{"answer":"예: 고체 상태의 물은 얼음과자 속 얼음, 액체 상태의 물은 어항의 물, 기체 상태의 물은 끓는 주전자 주변의 보이지 않는 물이다. 얼음이 왜 물이 되는지 더 알고 싶다.","scoring_points":["세 가지 상태의 물을 하나씩 바르게 찾았는가","기체 상태의 물은 보이지 않음을 알았는가","물에 대한 궁금한 점을 썼는가"]},"explanation":["주변을 둘러봐요.","하나씩 찾아요.","궁금한 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_basic#1','sci',4,1,'u2','L02','g4_1_sci_u2_L02_basic','lesson_basic','SC4-1-u2-C5',1,'mc','auto','물의 기체 상태를 무엇이라고 하나요?',ARRAY['SC4-1-u2-X06']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C5","difficulty":1,"kind":"mc","stem":"물의 기체 상태를 무엇이라고 하나요?","options":[{"t":"수증기","correct":true},{"t":"얼음","mis":"SC4-1-u2-X06"},{"t":"물","mis":"SC4-1-u2-X06"},{"t":"물방울","mis":"SC4-1-u2-X06"}],"explanation":["보이지 않는 물이에요.","이름이 있어요.","수증기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_basic#2','sci',4,1,'u2','L02','g4_1_sci_u2_L02_basic','lesson_basic','SC4-1-u2-C5',1,'match','auto','물의 상태와 그 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SC4-1-u2-C5","difficulty":1,"kind":"match","stem":"물의 상태와 그 이름을 알맞게 이으세요.","pairs":[{"l":"고체","r":"얼음"},{"l":"액체","r":"물"},{"l":"기체","r":"수증기"}],"mis":"SC4-1-u2-X06","explanation":["단단한 것은 얼음이에요.","보이지 않는 것은 수증기예요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_basic#3','sci',4,1,'u2','L02','g4_1_sci_u2_L02_basic','lesson_basic','SC4-1-u2-C6',1,'ox','auto','얼음은 손으로 잡을 수 있고 모양이 일정해요.',ARRAY['SC4-1-u2-X07']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C6","difficulty":1,"kind":"ox","stem":"얼음은 손으로 잡을 수 있고 모양이 일정해요.","answer":"O","reason_options":[{"t":"얼음은 단단한 고체이기 때문에","correct":true},{"t":"얼음은 흐르는 액체이기 때문에","mis":"SC4-1-u2-X07"}],"mis":"SC4-1-u2-X07","explanation":["얼음을 만져 봐요.","단단해요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 페트리 접시의 얼음은 투명하고 차갑고 단단했다.","② 시간이 지나자 얼음이 점점 작아졌다.","③ 접시에 물이 생기고 점점 많아졌다.","④ 장갑 낀 손에 붓으로 칠한 물이 점점 줄어들었다.","⑤ 조금 뒤 손에 칠한 물이 보이지 않았다."],"title":"물의 상태 변화 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_basic#4','sci',4,1,'u2','L02','g4_1_sci_u2_L02_basic','lesson_basic','SC4-1-u2-C9',1,'sa','auto','「얼음은 녹아 물로 변하고, 물은 눈에 보이지 않는 수증기로 변해요. 이처럼 물이 서로 다른 상태로 변하는 것을 물의 무엇이라고 하나요?」 네 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u2-C9","difficulty":1,"kind":"sa","stem":"「얼음은 녹아 물로 변하고, 물은 눈에 보이지 않는 수증기로 변해요. 이처럼 물이 서로 다른 상태로 변하는 것을 물의 무엇이라고 하나요?」 네 글자로 쓰세요.","answer":["상태 변화","상태변화"],"explanation":["상태가 바뀌어요.","「상태 ○○」예요.","상태 변화예요."],"mis":"SC4-1-u2-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_basic#5','sci',4,1,'u2','L02','g4_1_sci_u2_L02_basic','lesson_basic','SC4-1-u2-C7',2,'mc','auto','페트리 접시의 얼음을 시간이 지난 뒤 관찰하면 어떻게 되나요?',ARRAY['SC4-1-u2-X09','SC4-1-u2-X11']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C7","difficulty":2,"kind":"mc","stem":"페트리 접시의 얼음을 시간이 지난 뒤 관찰하면 어떻게 되나요?","options":[{"t":"얼음은 작아지고 접시의 물은 많아진다","correct":true},{"t":"얼음은 커지고 물은 줄어든다","mis":"SC4-1-u2-X09"},{"t":"얼음이 물이 아닌 다른 것으로 바뀐다","mis":"SC4-1-u2-X09"},{"t":"아무 변화도 없다","mis":"SC4-1-u2-X11"}],"explanation":["②와 ③을 읽어요.","작아지고 많아져요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 페트리 접시의 얼음은 투명하고 차갑고 단단했다.","② 시간이 지나자 얼음이 점점 작아졌다.","③ 접시에 물이 생기고 점점 많아졌다.","④ 장갑 낀 손에 붓으로 칠한 물이 점점 줄어들었다.","⑤ 조금 뒤 손에 칠한 물이 보이지 않았다."],"title":"물의 상태 변화 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_basic#6','sci',4,1,'u2','L02','g4_1_sci_u2_L02_basic','lesson_basic','SC4-1-u2-C8',2,'ox','auto','손에 칠한 물이 보이지 않게 된 것은 물이 아주 없어졌기 때문이에요.',ARRAY['SC4-1-u2-X08']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C8","difficulty":2,"kind":"ox","stem":"손에 칠한 물이 보이지 않게 된 것은 물이 아주 없어졌기 때문이에요.","answer":"X","reason_options":[{"t":"물이 수증기로 변해 공기 중으로 갔기 때문에","correct":true},{"t":"눈에 보이지 않는 것은 없는 것이기 때문에","mis":"SC4-1-u2-X08"}],"mis":"SC4-1-u2-X08","explanation":["⑤를 읽어요.","수증기는 보이지 않아요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 페트리 접시의 얼음은 투명하고 차갑고 단단했다.","② 시간이 지나자 얼음이 점점 작아졌다.","③ 접시에 물이 생기고 점점 많아졌다.","④ 장갑 낀 손에 붓으로 칠한 물이 점점 줄어들었다.","⑤ 조금 뒤 손에 칠한 물이 보이지 않았다."],"title":"물의 상태 변화 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_basic#7','sci',4,1,'u2','L02','g4_1_sci_u2_L02_basic','lesson_basic','SC4-1-u2-C6',2,'mc','auto','물의 특징으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X07','SC4-1-u2-X06']::text[],false,'{"seq":7,"concept":"SC4-1-u2-C6","difficulty":2,"kind":"mc","stem":"물의 특징으로 알맞은 것은 무엇인가요?","options":[{"t":"흐르고 담는 그릇에 따라 모양이 바뀐다","correct":true},{"t":"단단해서 손으로 잡을 수 있다","mis":"SC4-1-u2-X07"},{"t":"모양이 늘 일정하다","mis":"SC4-1-u2-X07"},{"t":"눈에 보이지 않는다","mis":"SC4-1-u2-X06"}],"explanation":["컵에 담긴 물을 떠올려요.","흘러요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_basic#8','sci',4,1,'u2','L02','g4_1_sci_u2_L02_basic','lesson_basic','SC4-1-u2-C9',2,'mc','auto','물의 상태 변화가 아닌 것은 무엇인가요?',ARRAY['SC4-1-u2-X10']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C9","difficulty":2,"kind":"mc","stem":"물의 상태 변화가 아닌 것은 무엇인가요?","options":[{"t":"컵의 물을 다른 모양의 컵에 옮겨 담는 것","correct":true},{"t":"얼음이 녹아 물이 되는 것","mis":"SC4-1-u2-X10"},{"t":"물이 얼어 얼음이 되는 것","mis":"SC4-1-u2-X10"},{"t":"손에 묻은 물이 수증기가 되는 것","mis":"SC4-1-u2-X10"}],"explanation":["상태가 바뀌나요?","옮겨 담으면 그대로 물이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
