INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_basic#10','sci',4,1,'u2','L02','g4_1_sci_u2_L02_basic','lesson_basic','SC4-1-u2-C10',3,'mc','auto','물이 액체 상태로만 있다면 어떤 일이 일어날까요?',ARRAY['SC4-1-u2-X12','SC4-1-u2-X08']::text[],false,'{"seq":10,"concept":"SC4-1-u2-C10","difficulty":3,"kind":"mc","stem":"물이 액체 상태로만 있다면 어떤 일이 일어날까요?","options":[{"t":"겨울에도 얼음이 얼지 않고, 손에 묻은 물도 마르지 않는다","correct":true},{"t":"지금과 달라지는 것이 하나도 없다","mis":"SC4-1-u2-X12"},{"t":"얼음과자를 더 쉽게 만들 수 있다","mis":"SC4-1-u2-X12"},{"t":"물이 모두 사라진다","mis":"SC4-1-u2-X08"}],"explanation":["얼음이 될 수 없어요.","수증기도 될 수 없어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_challenge#1','sci',4,1,'u2','L02','g4_1_sci_u2_L02_challenge','lesson_challenge','SC4-1-u2-C9',2,'blank','auto','「물이 서로 다른 (      )(으)로 변하는 것을 물의 상태 변화라고 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u2-X10']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C9","difficulty":2,"kind":"blank","stem":"「물이 서로 다른 (      )(으)로 변하는 것을 물의 상태 변화라고 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"상태","correct":true},{"t":"그릇","mis":"SC4-1-u2-X10"},{"t":"색깔","mis":"SC4-1-u2-X10"},{"t":"이름","mis":"SC4-1-u2-X10"}],"explanation":["얼음·물·수증기예요.","고체·액체·기체예요.","상태예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_challenge#2','sci',4,1,'u2','L02','g4_1_sci_u2_L02_challenge','lesson_challenge','SC4-1-u2-C5',2,'mc','auto','얼음, 물, 수증기 가운데 눈에 보이지 않는 것은 무엇인가요?',ARRAY['SC4-1-u2-X06','SC4-1-u2-X03']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C5","difficulty":2,"kind":"mc","stem":"얼음, 물, 수증기 가운데 눈에 보이지 않는 것은 무엇인가요?","options":[{"t":"수증기","correct":true},{"t":"얼음","mis":"SC4-1-u2-X06"},{"t":"물","mis":"SC4-1-u2-X06"},{"t":"셋 다 잘 보인다","mis":"SC4-1-u2-X03"}],"explanation":["기체를 떠올려요.","보이지 않아요.","수증기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_challenge#3','sci',4,1,'u2','L02','g4_1_sci_u2_L02_challenge','lesson_challenge','SC4-1-u2-C7',3,'mc','auto','「물의 상태 변화 관찰」 ①~③에서 접시의 얼음은 어떤 상태 변화를 했나요?',ARRAY['SC4-1-u2-X06','SC4-1-u2-X09']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C7","difficulty":3,"kind":"mc","stem":"「물의 상태 변화 관찰」 ①~③에서 접시의 얼음은 어떤 상태 변화를 했나요?","options":[{"t":"고체에서 액체로","correct":true},{"t":"액체에서 고체로","mis":"SC4-1-u2-X06"},{"t":"액체에서 기체로","mis":"SC4-1-u2-X06"},{"t":"상태가 변하지 않았다","mis":"SC4-1-u2-X09"}],"explanation":["얼음이 물이 됐어요.","얼음은 고체예요.","고체에서 액체로예요."],"asset":{"type":"passage","lines":["① 페트리 접시의 얼음은 투명하고 차갑고 단단했다.","② 시간이 지나자 얼음이 점점 작아졌다.","③ 접시에 물이 생기고 점점 많아졌다.","④ 장갑 낀 손에 붓으로 칠한 물이 점점 줄어들었다.","⑤ 조금 뒤 손에 칠한 물이 보이지 않았다."],"title":"물의 상태 변화 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_challenge#4','sci',4,1,'u2','L02','g4_1_sci_u2_L02_challenge','lesson_challenge','SC4-1-u2-C9',3,'error','auto','물의 상태 변화를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u2-X11','SC4-1-u2-X10']::text[],false,'{"seq":4,"concept":"SC4-1-u2-C9","difficulty":3,"kind":"error","stem":"물의 상태 변화를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「얼음이 물이 되면 다시는 얼음이 될 수 없어.」","correct":true,"mis_target":"SC4-1-u2-X11"},{"t":"친구 가 — 「물은 얼음이 되기도 하고 수증기가 되기도 해.」","mis":"SC4-1-u2-X10"},{"t":"친구 다 — 「수증기도 다시 물이 될 수 있어.」","mis":"SC4-1-u2-X11"}],"explanation":["네 방향을 떠올려요.","되돌아갈 수 있어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_challenge#5','sci',4,1,'u2','L02','g4_1_sci_u2_L02_challenge','lesson_challenge','SC4-1-u2-C9',3,'ox','auto','수증기는 다시 물로 변할 수 있어요.',ARRAY['SC4-1-u2-X11']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C9","difficulty":3,"kind":"ox","stem":"수증기는 다시 물로 변할 수 있어요.","answer":"O","reason_options":[{"t":"물과 수증기 사이의 상태 변화는 서로 반대 방향으로도 일어나기 때문에","correct":true},{"t":"물의 상태 변화는 한 방향으로만 일어나기 때문에","mis":"SC4-1-u2-X11"}],"mis":"SC4-1-u2-X11","explanation":["네 방향을 떠올려요.","수증기 → 물도 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_challenge#6','sci',4,1,'u2','L02','g4_1_sci_u2_L02_challenge','lesson_challenge','SC4-1-u2-C8',3,'mc','auto','장갑 낀 손에 칠한 물이 어디로 갔는지 가장 알맞게 추리한 것은 무엇인가요?',ARRAY['SC4-1-u2-X08','SC4-1-u2-X06']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C8","difficulty":3,"kind":"mc","stem":"장갑 낀 손에 칠한 물이 어디로 갔는지 가장 알맞게 추리한 것은 무엇인가요?","options":[{"t":"수증기가 되어 공기 중으로 날아갔다","correct":true},{"t":"물이 아주 사라져 없어졌다","mis":"SC4-1-u2-X08"},{"t":"얼음이 되어 손에 붙어 있다","mis":"SC4-1-u2-X06"},{"t":"장갑이 물을 모두 먹어 버렸다","mis":"SC4-1-u2-X08"}],"explanation":["보이지 않게 됐어요.","수증기는 보이지 않아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_challenge#7','sci',4,1,'u2','L02','g4_1_sci_u2_L02_challenge','lesson_challenge','SC4-1-u2-C10',3,'mc','auto','얼음을 관찰할 때 지켜야 할 것으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X13']::text[],false,'{"seq":7,"concept":"SC4-1-u2-C10","difficulty":3,"kind":"mc","stem":"얼음을 관찰할 때 지켜야 할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"얼음을 오래 만지지 않고, 얼음과 물을 맛보지 않는다","correct":true},{"t":"얼음을 입에 넣어 맛을 본다","mis":"SC4-1-u2-X13"},{"t":"얼음을 손에 오래 쥐고 있는다","mis":"SC4-1-u2-X13"},{"t":"유리 접시를 세게 내려놓는다","mis":"SC4-1-u2-X13"}],"explanation":["안전을 떠올려요.","맛보지 않아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_challenge#8','sci',4,1,'u2','L02','g4_1_sci_u2_L02_challenge','lesson_challenge','SC4-1-u2-C6',4,'mc','auto','친구가 「얼음과 물은 서로 다른 물질이야. 생김새가 다르잖아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X01','SC4-1-u2-X07','SC4-1-u2-X06']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C6","difficulty":4,"kind":"mc","stem":"친구가 「얼음과 물은 서로 다른 물질이야. 생김새가 다르잖아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「얼음은 고체, 물은 액체일 뿐 둘 다 같은 물이야.」","correct":true},{"t":"「맞아, 얼음은 물이 아니야.」","mis":"SC4-1-u2-X01"},{"t":"「얼음은 흐르고 물은 단단해.」","mis":"SC4-1-u2-X07"},{"t":"「얼음은 기체 상태의 물이야.」","mis":"SC4-1-u2-X06"}],"explanation":["얼음이 녹으면 물이에요.","상태만 달라요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_challenge#9','sci',4,1,'u2','L02','g4_1_sci_u2_L02_challenge','lesson_challenge','SC4-1-u2-C9',4,'mc','auto','물의 상태 변화를 모두 고른 것은 무엇인가요? ㉠ 얼음이 녹아 물이 됨 ㉡ 물을 큰 그릇에 옮겨 담음 ㉢ 물이 수증기가 됨 ㉣ 수증기가 물이 됨',ARRAY['SC4-1-u2-X10','SC4-1-u2-X11']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C9","difficulty":4,"kind":"mc","stem":"물의 상태 변화를 모두 고른 것은 무엇인가요? ㉠ 얼음이 녹아 물이 됨 ㉡ 물을 큰 그릇에 옮겨 담음 ㉢ 물이 수증기가 됨 ㉣ 수증기가 물이 됨","options":[{"t":"㉠, ㉢, ㉣","correct":true},{"t":"㉠, ㉡, ㉢","mis":"SC4-1-u2-X10"},{"t":"㉡, ㉣","mis":"SC4-1-u2-X10"},{"t":"㉠만","mis":"SC4-1-u2-X11"}],"explanation":["상태가 바뀌는 것을 골라요.","옮겨 담기는 아니에요.","㉠, ㉢, ㉣이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L02_challenge#10','sci',4,1,'u2','L02','g4_1_sci_u2_L02_challenge','lesson_challenge','SC4-1-u2-C8',4,'essay','teacher','「물의 상태 변화 관찰」을 보고 접시의 얼음과 손에 칠한 물이 각각 어떻게 상태가 변했는지 쓰고, 손에 칠한 물이 어디로 갔는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u2-C8","difficulty":4,"kind":"essay","stem":"「물의 상태 변화 관찰」을 보고 접시의 얼음과 손에 칠한 물이 각각 어떻게 상태가 변했는지 쓰고, 손에 칠한 물이 어디로 갔는지 쓰세요.","answer_guide":{"answer":"예: 접시의 얼음은 녹아 물이 되었으므로 고체에서 액체로 변했다. 손에 칠한 물은 수증기가 되었으므로 액체에서 기체로 변했다. 손에 칠한 물은 없어진 것이 아니라 눈에 보이지 않는 수증기가 되어 공기 중으로 갔다.","scoring_points":["얼음의 상태 변화를 바르게 썼는가","손에 칠한 물의 상태 변화를 바르게 썼는가","수증기가 되어 공기 중으로 갔다고 썼는가"]},"explanation":["①~⑤를 읽어요.","두 가지를 써요.","어디로 갔는지 써요."],"asset":{"type":"passage","lines":["① 페트리 접시의 얼음은 투명하고 차갑고 단단했다.","② 시간이 지나자 얼음이 점점 작아졌다.","③ 접시에 물이 생기고 점점 많아졌다.","④ 장갑 낀 손에 붓으로 칠한 물이 점점 줄어들었다.","⑤ 조금 뒤 손에 칠한 물이 보이지 않았다."],"title":"물의 상태 변화 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_basic#1','sci',4,1,'u2','L03','g4_1_sci_u2_L03_basic','lesson_basic','SC4-1-u2-C11',1,'mc','auto','고드름이 녹는 것은 어떤 상태 변화인가요?',ARRAY['SC4-1-u2-X14','SC4-1-u2-X15']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C11","difficulty":1,"kind":"mc","stem":"고드름이 녹는 것은 어떤 상태 변화인가요?","options":[{"t":"고체에서 액체로","correct":true},{"t":"액체에서 고체로","mis":"SC4-1-u2-X14"},{"t":"액체에서 기체로","mis":"SC4-1-u2-X15"},{"t":"기체에서 액체로","mis":"SC4-1-u2-X14"}],"explanation":["고드름은 얼음이에요.","녹아 물이 돼요.","고체에서 액체로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_basic#2','sci',4,1,'u2','L03','g4_1_sci_u2_L03_basic','lesson_basic','SC4-1-u2-C12',1,'mc','auto','젖은 빨래가 마르는 것은 어떤 상태 변화인가요?',ARRAY['SC4-1-u2-X15']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C12","difficulty":1,"kind":"mc","stem":"젖은 빨래가 마르는 것은 어떤 상태 변화인가요?","options":[{"t":"액체에서 기체로","correct":true},{"t":"기체에서 액체로","mis":"SC4-1-u2-X15"},{"t":"고체에서 액체로","mis":"SC4-1-u2-X15"},{"t":"액체에서 고체로","mis":"SC4-1-u2-X15"}],"explanation":["빨래의 물이 어디로 갈까요?","수증기가 돼요.","액체에서 기체로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_basic#3','sci',4,1,'u2','L03','g4_1_sci_u2_L03_basic','lesson_basic','SC4-1-u2-C11',1,'ox','auto','추운 겨울 강물이 어는 것은 액체인 물이 고체인 얼음으로 변하는 것이에요.',ARRAY['SC4-1-u2-X14']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C11","difficulty":1,"kind":"ox","stem":"추운 겨울 강물이 어는 것은 액체인 물이 고체인 얼음으로 변하는 것이에요.","answer":"O","reason_options":[{"t":"흐르던 물이 단단한 얼음이 되기 때문에","correct":true},{"t":"강물이 얼면 얼음이 녹아 물이 되기 때문에","mis":"SC4-1-u2-X14"}],"mis":"SC4-1-u2-X14","explanation":["강물이 얼어요.","물이 얼음이 돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_basic#4','sci',4,1,'u2','L03','g4_1_sci_u2_L03_basic','lesson_basic','SC4-1-u2-C13',1,'sa','auto','이른 아침 풀잎에 맺힌 이슬은 공기 중의 무엇이 물로 변해 생긴 것인가요?','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u2-C13","difficulty":1,"kind":"sa","stem":"이른 아침 풀잎에 맺힌 이슬은 공기 중의 무엇이 물로 변해 생긴 것인가요?","answer":["수증기"],"explanation":["공기 중에 보이지 않는 물이 있어요.","기체 상태의 물이에요.","수증기예요."],"mis":"SC4-1-u2-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_basic#5','sci',4,1,'u2','L03','g4_1_sci_u2_L03_basic','lesson_basic','SC4-1-u2-C12',2,'match','auto','생활 속 예와 상태 변화를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-1-u2-C12","difficulty":2,"kind":"match","stem":"생활 속 예와 상태 변화를 알맞게 이으세요.","pairs":[{"l":"스팀다리미로 다림질하기","r":"물 → 수증기"},{"l":"얼음 틀에 물을 넣어 얼리기","r":"물 → 얼음"},{"l":"냉동실에서 꺼낸 얼음과자가 녹기","r":"얼음 → 물"}],"mis":"SC4-1-u2-X15","explanation":["무엇이 무엇으로 변하나요?","하나씩 따져요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_basic#6','sci',4,1,'u2','L03','g4_1_sci_u2_L03_basic','lesson_basic','SC4-1-u2-C13',2,'mc','auto','차가운 음료수 캔 표면에 맺힌 물방울은 어떻게 생긴 것인가요?',ARRAY['SC4-1-u2-X16','SC4-1-u2-X15']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C13","difficulty":2,"kind":"mc","stem":"차가운 음료수 캔 표면에 맺힌 물방울은 어떻게 생긴 것인가요?","options":[{"t":"공기 중의 수증기가 물로 변해 생겼다","correct":true},{"t":"캔 속 음료수가 새어 나왔다","mis":"SC4-1-u2-X16"},{"t":"물이 수증기로 변해 생겼다","mis":"SC4-1-u2-X15"},{"t":"하늘에서 떨어진 빗물이다","mis":"SC4-1-u2-X16"}],"explanation":["공기 중을 떠올려요.","수증기가 물이 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_basic#7','sci',4,1,'u2','L03','g4_1_sci_u2_L03_basic','lesson_basic','SC4-1-u2-C14',2,'mc','auto','고드름이 녹아 생긴 물은 시간이 지나면 어떻게 될까요?',ARRAY['SC4-1-u2-X08','SC4-1-u2-X18','SC4-1-u2-X14']::text[],false,'{"seq":7,"concept":"SC4-1-u2-C14","difficulty":2,"kind":"mc","stem":"고드름이 녹아 생긴 물은 시간이 지나면 어떻게 될까요?","options":[{"t":"수증기로 변해 공기 중으로 날아간다","correct":true},{"t":"아주 사라져 없어진다","mis":"SC4-1-u2-X08"},{"t":"언제까지나 그대로 남아 있다","mis":"SC4-1-u2-X18"},{"t":"흙 속에서 다시 고드름이 된다","mis":"SC4-1-u2-X14"}],"explanation":["물이 마르면 어디로 갈까요?","수증기가 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_basic#8','sci',4,1,'u2','L03','g4_1_sci_u2_L03_basic','lesson_basic','SC4-1-u2-C11',2,'ox','auto','스케이트장의 얼음판은 액체인 물을 얼려 만든 것이에요.',ARRAY['SC4-1-u2-X14']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C11","difficulty":2,"kind":"ox","stem":"스케이트장의 얼음판은 액체인 물을 얼려 만든 것이에요.","answer":"O","reason_options":[{"t":"액체인 물이 고체인 얼음으로 변한 것이기 때문에","correct":true},{"t":"얼음판은 얼음을 녹여 만든 것이기 때문에","mis":"SC4-1-u2-X14"}],"mis":"SC4-1-u2-X14","explanation":["물을 부어 얼려요.","물이 얼음이 돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_basic#9','sci',4,1,'u2','L03','g4_1_sci_u2_L03_basic','lesson_basic','SC4-1-u2-C12',2,'mc','auto','교실에서 볼 수 있는, 물이 수증기로 변하는 예는 무엇인가요?',ARRAY['SC4-1-u2-X15','SC4-1-u2-X18','SC4-1-u2-X17']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C12","difficulty":2,"kind":"mc","stem":"교실에서 볼 수 있는, 물이 수증기로 변하는 예는 무엇인가요?","options":[{"t":"교실 어항의 물이 조금씩 줄어든다","correct":true},{"t":"얼음 틀의 물이 언다","mis":"SC4-1-u2-X15"},{"t":"녹은 얼음물이 줄지 않고 그대로 있다","mis":"SC4-1-u2-X18"},{"t":"물의 상태 변화는 교실에서 볼 수 없다","mis":"SC4-1-u2-X17"}],"explanation":["어항을 떠올려요.","물이 줄어들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_basic#10','sci',4,1,'u2','L03','g4_1_sci_u2_L03_basic','lesson_basic','SC4-1-u2-C15',3,'mc','auto','스마트 기기로 생활 속 물의 상태 변화를 조사할 때 가장 알맞은 태도는 무엇인가요?',ARRAY['SC4-1-u2-X19','SC4-1-u2-X17']::text[],false,'{"seq":10,"concept":"SC4-1-u2-C15","difficulty":3,"kind":"mc","stem":"스마트 기기로 생활 속 물의 상태 변화를 조사할 때 가장 알맞은 태도는 무엇인가요?","options":[{"t":"정보의 출처를 확인하고 옳은 정보인지 살핀다","correct":true},{"t":"가장 먼저 나온 정보를 그대로 옮긴다","mis":"SC4-1-u2-X19"},{"t":"출처는 몰라도 재미있는 정보만 고른다","mis":"SC4-1-u2-X19"},{"t":"조사는 하지 않고 실험실에서만 찾는다","mis":"SC4-1-u2-X17"}],"explanation":["어디서 나온 정보인가요?","출처를 확인해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_challenge#1','sci',4,1,'u2','L03','g4_1_sci_u2_L03_challenge','lesson_challenge','SC4-1-u2-C13',2,'blank','auto','「호수의 물이 마르는 것과 풀잎에 이슬이 맺히는 것은 물과 (      ) 사이의 상태 변화예요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u2-X14','SC4-1-u2-X16']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C13","difficulty":2,"kind":"blank","stem":"「호수의 물이 마르는 것과 풀잎에 이슬이 맺히는 것은 물과 (      ) 사이의 상태 변화예요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"수증기","correct":true},{"t":"얼음","mis":"SC4-1-u2-X14"},{"t":"흙","mis":"SC4-1-u2-X16"},{"t":"바람","mis":"SC4-1-u2-X16"}],"explanation":["마르면 수증기가 돼요.","이슬은 수증기에서 와요.","수증기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_challenge#2','sci',4,1,'u2','L03','g4_1_sci_u2_L03_challenge','lesson_challenge','SC4-1-u2-C11',2,'mc','auto','고체에서 액체로 변하는 예끼리 묶은 것은 무엇인가요?',ARRAY['SC4-1-u2-X14','SC4-1-u2-X15','SC4-1-u2-X16']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C11","difficulty":2,"kind":"mc","stem":"고체에서 액체로 변하는 예끼리 묶은 것은 무엇인가요?","options":[{"t":"고드름이 녹음, 봄에 계곡 얼음이 녹음","correct":true},{"t":"강물이 얾, 얼음 틀의 물이 얾","mis":"SC4-1-u2-X14"},{"t":"빨래가 마름, 고드름이 녹음","mis":"SC4-1-u2-X15"},{"t":"이슬이 맺힘, 계곡 얼음이 녹음","mis":"SC4-1-u2-X16"}],"explanation":["녹는 것을 찾아요.","둘 다 녹아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_challenge#3','sci',4,1,'u2','L03','g4_1_sci_u2_L03_challenge','lesson_challenge','SC4-1-u2-C12',3,'mc','auto','「생활 속 물의 상태 변화」에서 물이 수증기로 변하는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC4-1-u2-X14','SC4-1-u2-X16']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C12","difficulty":3,"kind":"mc","stem":"「생활 속 물의 상태 변화」에서 물이 수증기로 변하는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"㉢, ㉤","correct":true},{"t":"㉠, ㉥","mis":"SC4-1-u2-X14"},{"t":"㉡, ㉣","mis":"SC4-1-u2-X16"},{"t":"㉣, ㉤","mis":"SC4-1-u2-X16"}],"explanation":["마르거나 줄어드는 것을 찾아요.","온천과 빨래예요.","㉢, ㉤이에요."],"asset":{"type":"passage","lines":["㉠ 따뜻한 날 처마 끝 고드름이 녹는다.","㉡ 추운 겨울 강물이 언다.","㉢ 온천의 뜨거운 물이 수증기로 변한다.","㉣ 이른 아침 풀잎에 이슬이 맺힌다.","㉤ 젖은 빨래가 마른다.","㉥ 얼음 틀에 물을 넣어 얼린다."],"title":"생활 속 물의 상태 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_challenge#4','sci',4,1,'u2','L03','g4_1_sci_u2_L03_challenge','lesson_challenge','SC4-1-u2-C13',3,'error','auto','생활 속 물의 상태 변화를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u2-X16','SC4-1-u2-X15','SC4-1-u2-X14']::text[],false,'{"seq":4,"concept":"SC4-1-u2-C13","difficulty":3,"kind":"error","stem":"생활 속 물의 상태 변화를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「겨울 유리창 안쪽의 물방울은 유리 속에서 스며 나온 거야.」","correct":true,"mis_target":"SC4-1-u2-X16"},{"t":"친구 가 — 「수채 물감 그림이 마르는 건 물이 수증기로 변해서야.」","mis":"SC4-1-u2-X15"},{"t":"친구 나 — 「봄에 계곡 얼음이 녹는 건 고체가 액체로 변하는 거야.」","mis":"SC4-1-u2-X14"}],"explanation":["유리창 물방울을 떠올려요.","공기 중 수증기에서 와요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_challenge#5','sci',4,1,'u2','L03','g4_1_sci_u2_L03_challenge','lesson_challenge','SC4-1-u2-C12',3,'ox','auto','염전에서 소금을 얻을 때에도 물의 상태 변화가 일어나요.',ARRAY['SC4-1-u2-X17']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C12","difficulty":3,"kind":"ox","stem":"염전에서 소금을 얻을 때에도 물의 상태 변화가 일어나요.","answer":"O","reason_options":[{"t":"바닷물의 물이 수증기로 변해 날아가고 소금이 남기 때문에","correct":true},{"t":"물의 상태 변화는 실험실에서만 일어나기 때문에","mis":"SC4-1-u2-X17"}],"mis":"SC4-1-u2-X17","explanation":["바닷물을 말려요.","물이 수증기가 돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_challenge#6','sci',4,1,'u2','L03','g4_1_sci_u2_L03_challenge','lesson_challenge','SC4-1-u2-C14',3,'mc','auto','고드름이 녹아 생긴 물이 다 마를 때까지 일어난 상태 변화를 차례대로 쓴 것은 무엇인가요?',ARRAY['SC4-1-u2-X14','SC4-1-u2-X16','SC4-1-u2-X18']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C14","difficulty":3,"kind":"mc","stem":"고드름이 녹아 생긴 물이 다 마를 때까지 일어난 상태 변화를 차례대로 쓴 것은 무엇인가요?","options":[{"t":"고체 → 액체 → 기체","correct":true},{"t":"액체 → 고체 → 기체","mis":"SC4-1-u2-X14"},{"t":"기체 → 액체 → 고체","mis":"SC4-1-u2-X16"},{"t":"고체 → 액체에서 끝난다","mis":"SC4-1-u2-X18"}],"explanation":["고드름은 고체예요.","녹고, 마르고요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_challenge#7','sci',4,1,'u2','L03','g4_1_sci_u2_L03_challenge','lesson_challenge','SC4-1-u2-C15',3,'mc','auto','교실에서 찾은 물의 상태 변화와 그 방향을 바르게 짝 지은 것은 무엇인가요?',ARRAY['SC4-1-u2-X15','SC4-1-u2-X16','SC4-1-u2-X17']::text[],false,'{"seq":7,"concept":"SC4-1-u2-C15","difficulty":3,"kind":"mc","stem":"교실에서 찾은 물의 상태 변화와 그 방향을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"화분의 흙이 마름 — 물이 수증기로","correct":true},{"t":"화분의 흙이 마름 — 수증기가 물로","mis":"SC4-1-u2-X15"},{"t":"추운 날 유리창 안쪽 물방울 — 물이 수증기로","mis":"SC4-1-u2-X16"},{"t":"교실에서는 상태 변화를 찾을 수 없다","mis":"SC4-1-u2-X17"}],"explanation":["흙이 마르면 물은 어디로?","수증기가 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_challenge#8','sci',4,1,'u2','L03','g4_1_sci_u2_L03_challenge','lesson_challenge','SC4-1-u2-C11',4,'mc','auto','친구가 「겨울 강물이 어는 것과 봄에 고드름이 녹는 것은 같은 방향의 상태 변화야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X14','SC4-1-u2-X15','SC4-1-u2-X17']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C11","difficulty":4,"kind":"mc","stem":"친구가 「겨울 강물이 어는 것과 봄에 고드름이 녹는 것은 같은 방향의 상태 변화야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「강물이 어는 것은 액체에서 고체로, 고드름이 녹는 것은 고체에서 액체로 변하는 거라 방향이 반대야.」","correct":true},{"t":"「맞아, 둘 다 고체에서 액체로 변해.」","mis":"SC4-1-u2-X14"},{"t":"「둘 다 액체에서 기체로 변해.」","mis":"SC4-1-u2-X15"},{"t":"「둘 다 상태 변화가 아니야.」","mis":"SC4-1-u2-X17"}],"explanation":["어는 것과 녹는 것이에요.","반대예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_challenge#9','sci',4,1,'u2','L03','g4_1_sci_u2_L03_challenge','lesson_challenge','SC4-1-u2-C13',4,'mc','auto','아침에 거미줄에 맺힌 이슬이 한낮에 사라졌어요. 이 과정을 가장 알맞게 설명한 것은 무엇인가요?',ARRAY['SC4-1-u2-X16','SC4-1-u2-X18','SC4-1-u2-X14']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C13","difficulty":4,"kind":"mc","stem":"아침에 거미줄에 맺힌 이슬이 한낮에 사라졌어요. 이 과정을 가장 알맞게 설명한 것은 무엇인가요?","options":[{"t":"공기 중 수증기가 물이 되어 맺혔다가, 그 물이 다시 수증기로 변해 공기 중으로 날아갔다","correct":true},{"t":"하늘에서 떨어진 물이 거미줄에 붙었다가 아주 없어졌다","mis":"SC4-1-u2-X16"},{"t":"거미줄에서 나온 물이 그대로 남아 있다","mis":"SC4-1-u2-X18"},{"t":"물이 얼음이 되었다가 녹았다","mis":"SC4-1-u2-X14"}],"explanation":["이슬은 어디서 왔나요?","어디로 갔나요?","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L03_challenge#10','sci',4,1,'u2','L03','g4_1_sci_u2_L03_challenge','lesson_challenge','SC4-1-u2-C12',4,'essay','teacher','「생활 속 물의 상태 변화」 ㉠~㉥을 고체와 액체 사이의 변화와 액체와 기체 사이의 변화로 나누고, 그렇게 나눈 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u2-C12","difficulty":4,"kind":"essay","stem":"「생활 속 물의 상태 변화」 ㉠~㉥을 고체와 액체 사이의 변화와 액체와 기체 사이의 변화로 나누고, 그렇게 나눈 까닭을 쓰세요.","answer_guide":{"answer":"예: 고체와 액체 사이의 변화는 ㉠, ㉡, ㉥이고, 액체와 기체 사이의 변화는 ㉢, ㉣, ㉤이다. ㉠·㉡·㉥은 얼음과 물 사이에서, ㉢·㉣·㉤은 물과 수증기 사이에서 상태가 변하기 때문이다.","scoring_points":["고체와 액체 사이를 바르게 나누었는가","액체와 기체 사이를 바르게 나누었는가","얼음·물·수증기를 들어 까닭을 썼는가"]},"explanation":["얼음이 나오나요?","수증기가 나오나요?","둘로 나눠요."],"asset":{"type":"passage","lines":["㉠ 따뜻한 날 처마 끝 고드름이 녹는다.","㉡ 추운 겨울 강물이 언다.","㉢ 온천의 뜨거운 물이 수증기로 변한다.","㉣ 이른 아침 풀잎에 이슬이 맺힌다.","㉤ 젖은 빨래가 마른다.","㉥ 얼음 틀에 물을 넣어 얼린다."],"title":"생활 속 물의 상태 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_basic#1','sci',4,1,'u2','L04','g4_1_sci_u2_L04_basic','lesson_basic','SC4-1-u2-C16',1,'mc','auto','시험관 속 물이 얼어 얼음이 되면 높이는 어떻게 되나요?',ARRAY['SC4-1-u2-X20','SC4-1-u2-X26']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C16","difficulty":1,"kind":"mc","stem":"시험관 속 물이 얼어 얼음이 되면 높이는 어떻게 되나요?","options":[{"t":"처음 물의 높이보다 높아진다","correct":true},{"t":"처음 물의 높이보다 낮아진다","mis":"SC4-1-u2-X20"},{"t":"처음 물의 높이와 같다","mis":"SC4-1-u2-X20"},{"t":"높이를 견줄 수 없다","mis":"SC4-1-u2-X26"}],"explanation":["파란색 선을 봐요.","검은색 선보다 높아요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 시험관 물의 높이를 검은색으로 표시했다. 무게 31.8 g","② 물이 완전히 얼자 얼음 높이를 파란색으로 표시했다. 무게 31.8 g","③ 얼음이 완전히 녹자 물 높이를 빨간색으로 표시했다. 무게 31.8 g","● 파란색 선은 검은색 선보다 높았다.","● 빨간색 선은 파란색 선보다 낮았다."],"title":"시험관 물 얼리고 녹이기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_basic#2','sci',4,1,'u2','L04','g4_1_sci_u2_L04_basic','lesson_basic','SC4-1-u2-C17',1,'ox','auto','물이 얼어 얼음이 되어도 무게는 변하지 않아요.',ARRAY['SC4-1-u2-X21']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C17","difficulty":1,"kind":"ox","stem":"물이 얼어 얼음이 되어도 무게는 변하지 않아요.","answer":"O","reason_options":[{"t":"①과 ②의 무게가 31.8 g으로 같기 때문에","correct":true},{"t":"부피가 늘어난 만큼 무게도 늘어나기 때문에","mis":"SC4-1-u2-X21"}],"mis":"SC4-1-u2-X21","explanation":["①과 ②의 무게를 봐요.","같아요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 시험관 물의 높이를 검은색으로 표시했다. 무게 31.8 g","② 물이 완전히 얼자 얼음 높이를 파란색으로 표시했다. 무게 31.8 g","③ 얼음이 완전히 녹자 물 높이를 빨간색으로 표시했다. 무게 31.8 g","● 파란색 선은 검은색 선보다 높았다.","● 빨간색 선은 파란색 선보다 낮았다."],"title":"시험관 물 얼리고 녹이기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_basic#3','sci',4,1,'u2','L04','g4_1_sci_u2_L04_basic','lesson_basic','SC4-1-u2-C18',1,'mc','auto','얼음이 녹아 물이 되면 부피는 어떻게 되나요?',ARRAY['SC4-1-u2-X23']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C18","difficulty":1,"kind":"mc","stem":"얼음이 녹아 물이 되면 부피는 어떻게 되나요?","options":[{"t":"줄어든다","correct":true},{"t":"늘어난다","mis":"SC4-1-u2-X23"},{"t":"변하지 않는다","mis":"SC4-1-u2-X23"},{"t":"처음보다 두 배로 늘어난다","mis":"SC4-1-u2-X23"}],"explanation":["빨간색 선을 봐요.","낮아졌어요.","줄어들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_basic#4','sci',4,1,'u2','L04','g4_1_sci_u2_L04_basic','lesson_basic','SC4-1-u2-C22',1,'sa','auto','물이 얼 때 부피 변화를 알아보려고 시험관에 표시한 것을 견주어요. 무엇을 견주나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u2-C22","difficulty":1,"kind":"sa","stem":"물이 얼 때 부피 변화를 알아보려고 시험관에 표시한 것을 견주어요. 무엇을 견주나요? 두 글자로 쓰세요.","answer":["높이"],"explanation":["유성펜으로 표시했어요.","선의 위치예요.","높이예요."],"mis":"SC4-1-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_basic#5','sci',4,1,'u2','L04','g4_1_sci_u2_L04_basic','lesson_basic','SC4-1-u2-C20',2,'mc','auto','물을 가득 넣은 페트병을 냉동실에 넣어 두었더니 페트병이 부풀었어요. 그 까닭은 무엇인가요?',ARRAY['SC4-1-u2-X21','SC4-1-u2-X20','SC4-1-u2-X25']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C20","difficulty":2,"kind":"mc","stem":"물을 가득 넣은 페트병을 냉동실에 넣어 두었더니 페트병이 부풀었어요. 그 까닭은 무엇인가요?","options":[{"t":"물이 얼어 얼음이 되면서 부피가 늘어났기 때문에","correct":true},{"t":"물이 얼면서 무게가 늘어났기 때문에","mis":"SC4-1-u2-X21"},{"t":"물이 얼면서 부피가 줄어들었기 때문에","mis":"SC4-1-u2-X20"},{"t":"차가워서 페트병이 저절로 커졌기 때문에","mis":"SC4-1-u2-X25"}],"explanation":["얼면 부피가 어떻게 되나요?","늘어나요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_basic#6','sci',4,1,'u2','L04','g4_1_sci_u2_L04_basic','lesson_basic','SC4-1-u2-C21',2,'mc','auto','튜브형 얼음과자가 녹았더니 튜브 안에 빈 공간이 생겼어요. 그 까닭은 무엇인가요?',ARRAY['SC4-1-u2-X22','SC4-1-u2-X23','SC4-1-u2-X25']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C21","difficulty":2,"kind":"mc","stem":"튜브형 얼음과자가 녹았더니 튜브 안에 빈 공간이 생겼어요. 그 까닭은 무엇인가요?","options":[{"t":"얼음이 녹아 물이 되면서 부피가 줄어들었기 때문에","correct":true},{"t":"얼음이 녹으면서 무게가 줄어들었기 때문에","mis":"SC4-1-u2-X22"},{"t":"얼음이 녹으면서 부피가 늘어났기 때문에","mis":"SC4-1-u2-X23"},{"t":"녹은 물이 튜브 밖으로 빠져나갔기 때문에","mis":"SC4-1-u2-X25"}],"explanation":["녹으면 부피가 어떻게 되나요?","줄어들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_basic#7','sci',4,1,'u2','L04','g4_1_sci_u2_L04_basic','lesson_basic','SC4-1-u2-C18',2,'match','auto','물이 얼 때와 얼음이 녹을 때의 변화를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC4-1-u2-C18","difficulty":2,"kind":"match","stem":"물이 얼 때와 얼음이 녹을 때의 변화를 알맞게 이으세요.","pairs":[{"l":"물이 얼 때 부피","r":"늘어나요"},{"l":"물이 얼 때 무게","r":"변하지 않아요"},{"l":"얼음이 녹을 때 부피","r":"줄어들어요"}],"mis":"SC4-1-u2-X21","explanation":["높이를 떠올려요.","무게는 같았어요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_basic#8','sci',4,1,'u2','L04','g4_1_sci_u2_L04_basic','lesson_basic','SC4-1-u2-C19',2,'ox','auto','부피가 큰 물체는 언제나 부피가 작은 물체보다 무거워요.',ARRAY['SC4-1-u2-X24']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C19","difficulty":2,"kind":"ox","stem":"부피가 큰 물체는 언제나 부피가 작은 물체보다 무거워요.","answer":"X","reason_options":[{"t":"스펀지는 쇠 덩어리보다 부피가 커도 더 가볍기 때문에","correct":true},{"t":"부피가 크면 무게도 반드시 크기 때문에","mis":"SC4-1-u2-X24"}],"mis":"SC4-1-u2-X24","explanation":["스펀지와 쇠 덩어리를 떠올려요.","부피와 무게는 따로예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_basic#9','sci',4,1,'u2','L04','g4_1_sci_u2_L04_basic','lesson_basic','SC4-1-u2-C22',2,'mc','auto','물이 얼 때의 부피 변화를 관찰하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X26','SC4-1-u2-X13']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C22","difficulty":2,"kind":"mc","stem":"물이 얼 때의 부피 변화를 관찰하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"얼기 전과 언 뒤의 높이를 유성펜으로 표시해 견준다","correct":true},{"t":"표시하지 않고 눈대중으로 기억한다","mis":"SC4-1-u2-X26"},{"t":"시험관을 흔들어 소리로 알아본다","mis":"SC4-1-u2-X26"},{"t":"얼음을 꺼내 손으로 오래 만져 본다","mis":"SC4-1-u2-X13"}],"explanation":["높이를 표시해요.","선을 견줘요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_basic#10','sci',4,1,'u2','L04','g4_1_sci_u2_L04_basic','lesson_basic','SC4-1-u2-C18',3,'mc','auto','「시험관 물 얼리고 녹이기」 ②와 ③을 견준 것으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X23','SC4-1-u2-X22','SC4-1-u2-X20']::text[],false,'{"seq":10,"concept":"SC4-1-u2-C18","difficulty":3,"kind":"mc","stem":"「시험관 물 얼리고 녹이기」 ②와 ③을 견준 것으로 알맞은 것은 무엇인가요?","options":[{"t":"③의 높이는 ②보다 낮고, 무게는 ②와 같다","correct":true},{"t":"③의 높이는 ②보다 높고, 무게도 더 무겁다","mis":"SC4-1-u2-X23"},{"t":"③의 높이는 ②보다 낮고, 무게도 더 가볍다","mis":"SC4-1-u2-X22"},{"t":"③과 ②는 높이와 무게가 모두 같다","mis":"SC4-1-u2-X20"}],"explanation":["빨간색 선을 봐요.","무게도 봐요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 시험관 물의 높이를 검은색으로 표시했다. 무게 31.8 g","② 물이 완전히 얼자 얼음 높이를 파란색으로 표시했다. 무게 31.8 g","③ 얼음이 완전히 녹자 물 높이를 빨간색으로 표시했다. 무게 31.8 g","● 파란색 선은 검은색 선보다 높았다.","● 빨간색 선은 파란색 선보다 낮았다."],"title":"시험관 물 얼리고 녹이기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_challenge#1','sci',4,1,'u2','L04','g4_1_sci_u2_L04_challenge','lesson_challenge','SC4-1-u2-C18',2,'blank','auto','「물이 얼거나 얼음이 녹을 때 (      )은/는 변하고, 무게는 변하지 않아요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u2-X21','SC4-1-u2-X25','SC4-1-u2-X22']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C18","difficulty":2,"kind":"blank","stem":"「물이 얼거나 얼음이 녹을 때 (      )은/는 변하고, 무게는 변하지 않아요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"부피","correct":true},{"t":"무게","mis":"SC4-1-u2-X21"},{"t":"색깔","mis":"SC4-1-u2-X25"},{"t":"물의 양","mis":"SC4-1-u2-X22"}],"explanation":["높이가 바뀌었어요.","높이는 부피를 보여 줘요.","부피예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_challenge#2','sci',4,1,'u2','L04','g4_1_sci_u2_L04_challenge','lesson_challenge','SC4-1-u2-C16',2,'mc','auto','얼음 틀에 물을 가득 채워 얼리지 않는 까닭은 무엇인가요?',ARRAY['SC4-1-u2-X21','SC4-1-u2-X20','SC4-1-u2-X25']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C16","difficulty":2,"kind":"mc","stem":"얼음 틀에 물을 가득 채워 얼리지 않는 까닭은 무엇인가요?","options":[{"t":"물이 얼면 부피가 늘어나 얼음이 볼록하게 튀어나오기 때문에","correct":true},{"t":"물이 얼면 무게가 늘어나 얼음 틀이 무거워지기 때문에","mis":"SC4-1-u2-X21"},{"t":"물이 얼면 부피가 줄어들어 얼음이 작아지기 때문에","mis":"SC4-1-u2-X20"},{"t":"가득 채우면 물이 얼지 않기 때문에","mis":"SC4-1-u2-X25"}],"explanation":["얼면 부피가 늘어요.","넘칠 수 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_challenge#3','sci',4,1,'u2','L04','g4_1_sci_u2_L04_challenge','lesson_challenge','SC4-1-u2-C20',3,'mc','auto','음료수가 가득 든 유리병을 냉동실에 넣어 두었더니 유리병이 깨졌어요. 그 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X25','SC4-1-u2-X21','SC4-1-u2-X20']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C20","difficulty":3,"kind":"mc","stem":"음료수가 가득 든 유리병을 냉동실에 넣어 두었더니 유리병이 깨졌어요. 그 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"음료수 속 물이 얼면서 부피가 늘어났기 때문에","correct":true},{"t":"차가워서 유리가 약해졌기 때문에","mis":"SC4-1-u2-X25"},{"t":"음료수가 얼면서 무게가 늘어났기 때문에","mis":"SC4-1-u2-X21"},{"t":"음료수가 얼면서 부피가 줄어들었기 때문에","mis":"SC4-1-u2-X20"}],"explanation":["얼면 부피가 늘어요.","병을 밀어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_challenge#4','sci',4,1,'u2','L04','g4_1_sci_u2_L04_challenge','lesson_challenge','SC4-1-u2-C17',3,'error','auto','시험관 실험을 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u2-X21','SC4-1-u2-X20']::text[],false,'{"seq":4,"concept":"SC4-1-u2-C17","difficulty":3,"kind":"error","stem":"시험관 실험을 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「얼음이 물보다 높이가 높으니까 더 무거울 거야.」","correct":true,"mis_target":"SC4-1-u2-X21"},{"t":"친구 가 — 「물이 얼었더니 높이가 높아졌어.」","mis":"SC4-1-u2-X20"},{"t":"친구 다 — 「얼기 전과 언 뒤의 무게가 같았어.」","mis":"SC4-1-u2-X21"}],"explanation":["무게를 봐요.","높이가 높아도 무게는 같아요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 시험관 물의 높이를 검은색으로 표시했다. 무게 31.8 g","② 물이 완전히 얼자 얼음 높이를 파란색으로 표시했다. 무게 31.8 g","③ 얼음이 완전히 녹자 물 높이를 빨간색으로 표시했다. 무게 31.8 g","● 파란색 선은 검은색 선보다 높았다.","● 빨간색 선은 파란색 선보다 낮았다."],"title":"시험관 물 얼리고 녹이기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_challenge#5','sci',4,1,'u2','L04','g4_1_sci_u2_L04_challenge','lesson_challenge','SC4-1-u2-C21',3,'ox','auto','얼려서 부푼 페트병을 꺼내 두면 얼음이 녹으면서 페트병의 부피가 줄어들어요.',ARRAY['SC4-1-u2-X23']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C21","difficulty":3,"kind":"ox","stem":"얼려서 부푼 페트병을 꺼내 두면 얼음이 녹으면서 페트병의 부피가 줄어들어요.","answer":"O","reason_options":[{"t":"얼음이 녹아 물이 되면 부피가 줄어들기 때문에","correct":true},{"t":"얼음이 녹으면 부피가 늘어나기 때문에","mis":"SC4-1-u2-X23"}],"mis":"SC4-1-u2-X23","explanation":["녹으면 부피가 줄어요.","페트병도 줄어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_challenge#6','sci',4,1,'u2','L04','g4_1_sci_u2_L04_challenge','lesson_challenge','SC4-1-u2-C19',3,'mc','auto','스펀지와 쇠 덩어리를 견주어 알 수 있는 것은 무엇인가요?',ARRAY['SC4-1-u2-X24','SC4-1-u2-X26']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C19","difficulty":3,"kind":"mc","stem":"스펀지와 쇠 덩어리를 견주어 알 수 있는 것은 무엇인가요?","options":[{"t":"부피가 크다고 해서 더 무거운 것은 아니다","correct":true},{"t":"부피가 크면 언제나 더 무겁다","mis":"SC4-1-u2-X24"},{"t":"부피가 작으면 무게가 없다","mis":"SC4-1-u2-X24"},{"t":"무게는 눈으로 보면 정확히 알 수 있다","mis":"SC4-1-u2-X26"}],"explanation":["스펀지는 커요.","쇠 덩어리는 무거워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_challenge#7','sci',4,1,'u2','L04','g4_1_sci_u2_L04_challenge','lesson_challenge','SC4-1-u2-C22',3,'mc','auto','시험관 속 물을 얼리고 녹이는 실험에서 지켜야 할 것으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X13']::text[],false,'{"seq":7,"concept":"SC4-1-u2-C22","difficulty":3,"kind":"mc","stem":"시험관 속 물을 얼리고 녹이는 실험에서 지켜야 할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"차가운 비커를 다룰 때 면장갑을 끼고, 유리 기구가 깨지지 않게 조심한다","correct":true},{"t":"얼음을 맛보며 차가운 정도를 알아본다","mis":"SC4-1-u2-X13"},{"t":"맨손으로 차가운 비커를 오래 잡는다","mis":"SC4-1-u2-X13"},{"t":"깨진 유리는 맨손으로 바로 줍는다","mis":"SC4-1-u2-X13"}],"explanation":["아주 차가워요.","유리도 조심해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_challenge#8','sci',4,1,'u2','L04','g4_1_sci_u2_L04_challenge','lesson_challenge','SC4-1-u2-C20',4,'mc','auto','추운 겨울에 수도 계량기가 터지는 까닭을 친구가 「물이 얼면 무거워져서 그래.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X21','SC4-1-u2-X20','SC4-1-u2-X25']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C20","difficulty":4,"kind":"mc","stem":"추운 겨울에 수도 계량기가 터지는 까닭을 친구가 「물이 얼면 무거워져서 그래.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「무게는 그대로야. 수돗물이 얼어 부피가 늘어나서 터지는 거야.」","correct":true},{"t":"「맞아, 얼음은 물보다 무거워.」","mis":"SC4-1-u2-X21"},{"t":"「물이 얼면 부피가 줄어들어서 터져.」","mis":"SC4-1-u2-X20"},{"t":"「추우면 계량기가 약해져서 저절로 터져.」","mis":"SC4-1-u2-X25"}],"explanation":["무게는 그대로예요.","부피가 늘어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_challenge#9','sci',4,1,'u2','L04','g4_1_sci_u2_L04_challenge','lesson_challenge','SC4-1-u2-C18',4,'mc','auto','물 한 컵을 얼린 얼음이 녹아 다시 물이 되었어요. 처음 물과 녹은 물을 견준 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X22','SC4-1-u2-X23','SC4-1-u2-X21']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C18","difficulty":4,"kind":"mc","stem":"물 한 컵을 얼린 얼음이 녹아 다시 물이 되었어요. 처음 물과 녹은 물을 견준 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"무게는 같고, 얼었다 녹는 동안 부피는 늘었다가 다시 줄었다","correct":true},{"t":"녹은 물이 처음 물보다 가볍다","mis":"SC4-1-u2-X22"},{"t":"녹은 물이 처음 물보다 부피가 크다","mis":"SC4-1-u2-X23"},{"t":"얼었다 녹는 동안 부피와 무게가 모두 늘었다","mis":"SC4-1-u2-X21"}],"explanation":["무게는 그대로예요.","부피는 늘었다 줄어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L04_challenge#10','sci',4,1,'u2','L04','g4_1_sci_u2_L04_challenge','lesson_challenge','SC4-1-u2-C16',4,'essay','teacher','「시험관 물 얼리고 녹이기」를 보고 물이 얼 때와 얼음이 녹을 때 부피와 무게가 어떻게 변하는지 쓰고, 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u2-C16","difficulty":4,"kind":"essay","stem":"「시험관 물 얼리고 녹이기」를 보고 물이 얼 때와 얼음이 녹을 때 부피와 무게가 어떻게 변하는지 쓰고, 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 물이 얼 때 부피는 늘어나고 무게는 변하지 않는다. 얼음이 녹을 때 부피는 줄어들고 무게는 변하지 않는다. 얼음의 높이가 처음 물보다 높았고 녹은 물의 높이는 얼음보다 낮았으며, 세 번 잰 무게가 모두 31.8 g으로 같았기 때문이다.","scoring_points":["얼 때 부피 늘고 무게 그대로를 썼는가","녹을 때 부피 줄고 무게 그대로를 썼는가","높이와 무게를 근거로 썼는가"]},"explanation":["선의 높이를 봐요.","무게를 봐요.","까닭을 써요."],"asset":{"type":"passage","lines":["① 시험관 물의 높이를 검은색으로 표시했다. 무게 31.8 g","② 물이 완전히 얼자 얼음 높이를 파란색으로 표시했다. 무게 31.8 g","③ 얼음이 완전히 녹자 물 높이를 빨간색으로 표시했다. 무게 31.8 g","● 파란색 선은 검은색 선보다 높았다.","● 빨간색 선은 파란색 선보다 낮았다."],"title":"시험관 물 얼리고 녹이기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_basic#1','sci',4,1,'u2','L05','g4_1_sci_u2_L05_basic','lesson_basic','SC4-1-u2-C23',1,'mc','auto','액체인 물이 표면에서 기체인 수증기로 변해 공기 중으로 날아가는 현상을 무엇이라고 하나요?',ARRAY['SC4-1-u2-X31','SC4-1-u2-X06','SC4-1-u2-X30']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C23","difficulty":1,"kind":"mc","stem":"액체인 물이 표면에서 기체인 수증기로 변해 공기 중으로 날아가는 현상을 무엇이라고 하나요?","options":[{"t":"증발","correct":true},{"t":"끓음","mis":"SC4-1-u2-X31"},{"t":"얼음","mis":"SC4-1-u2-X06"},{"t":"녹음","mis":"SC4-1-u2-X30"}],"explanation":["표면에서 일어나요.","천천히 일어나요.","증발이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_basic#2','sci',4,1,'u2','L05','g4_1_sci_u2_L05_basic','lesson_basic','SC4-1-u2-C24',1,'mc','auto','물이 끓을 때 볼 수 있는 모습은 무엇인가요?',ARRAY['SC4-1-u2-X28','SC4-1-u2-X29','SC4-1-u2-X30']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C24","difficulty":1,"kind":"mc","stem":"물이 끓을 때 볼 수 있는 모습은 무엇인가요?","options":[{"t":"물 전체에서 크고 작은 기포가 계속 생긴다","correct":true},{"t":"물의 높이가 점점 높아진다","mis":"SC4-1-u2-X28"},{"t":"물 표면에서만 조용히 변하고 기포는 생기지 않는다","mis":"SC4-1-u2-X29"},{"t":"물이 얼음으로 변한다","mis":"SC4-1-u2-X30"}],"explanation":["[나]를 떠올려요.","기포가 생겨요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_basic#3','sci',4,1,'u2','L05','g4_1_sci_u2_L05_basic','lesson_basic','SC4-1-u2-C25',1,'ox','auto','증발과 끓음은 모두 액체인 물이 기체인 수증기로 변하는 현상이에요.',ARRAY['SC4-1-u2-X30']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C25","difficulty":1,"kind":"ox","stem":"증발과 끓음은 모두 액체인 물이 기체인 수증기로 변하는 현상이에요.","answer":"O","reason_options":[{"t":"두 비커 모두 물이 수증기가 되어 높이가 낮아졌기 때문에","correct":true},{"t":"증발은 물이 수증기로, 끓음은 물이 얼음으로 변하기 때문에","mis":"SC4-1-u2-X30"}],"mis":"SC4-1-u2-X30","explanation":["두 비커를 견줘요.","둘 다 물이 줄었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["[가] 비커를 햇빛이 잘 드는 곳에 두었다.","처음 → 2일 뒤 → 4일 뒤 물의 높이가 조금씩 낮아졌다.","[나] 비커를 핫플레이트로 가열했다.","작은 기포가 조금씩 생기다가 물 전체에서 기포가 계속 생겼다.","기포가 터지며 물 표면이 출렁였다.","끓기 시작하고 2분 뒤 물의 높이가 처음보다 낮아졌다."],"title":"두 비커의 물 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_basic#4','sci',4,1,'u2','L05','g4_1_sci_u2_L05_basic','lesson_basic','SC4-1-u2-C24',1,'sa','auto','물의 표면뿐만 아니라 물속에서도 물이 수증기로 변하는 현상을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u2-C24","difficulty":1,"kind":"sa","stem":"물의 표면뿐만 아니라 물속에서도 물이 수증기로 변하는 현상을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["끓음"],"explanation":["기포가 생겨요.","물속에서도요.","끓음이에요."],"mis":"SC4-1-u2-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_basic#5','sci',4,1,'u2','L05','g4_1_sci_u2_L05_basic','lesson_basic','SC4-1-u2-C23',2,'mc','auto','「두 비커의 물 관찰」 [가]에서 물의 높이가 낮아진 까닭은 무엇인가요?',ARRAY['SC4-1-u2-X08','SC4-1-u2-X30','SC4-1-u2-X27']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C23","difficulty":2,"kind":"mc","stem":"「두 비커의 물 관찰」 [가]에서 물의 높이가 낮아진 까닭은 무엇인가요?","options":[{"t":"물이 증발해 수증기가 되어 공기 중으로 날아갔기 때문에","correct":true},{"t":"물이 아주 사라져 없어졌기 때문에","mis":"SC4-1-u2-X08"},{"t":"햇빛이 물을 얼음으로 바꾸었기 때문에","mis":"SC4-1-u2-X30"},{"t":"햇빛에 물이 끓었기 때문에","mis":"SC4-1-u2-X27"}],"explanation":["햇빛에 둔 비커예요.","천천히 수증기가 돼요.","첫 번째예요."],"asset":{"type":"passage","lines":["[가] 비커를 햇빛이 잘 드는 곳에 두었다.","처음 → 2일 뒤 → 4일 뒤 물의 높이가 조금씩 낮아졌다.","[나] 비커를 핫플레이트로 가열했다.","작은 기포가 조금씩 생기다가 물 전체에서 기포가 계속 생겼다.","기포가 터지며 물 표면이 출렁였다.","끓기 시작하고 2분 뒤 물의 높이가 처음보다 낮아졌다."],"title":"두 비커의 물 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_basic#6','sci',4,1,'u2','L05','g4_1_sci_u2_L05_basic','lesson_basic','SC4-1-u2-C25',2,'match','auto','증발과 끓음에 대해 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC4-1-u2-C25","difficulty":2,"kind":"match","stem":"증발과 끓음에 대해 알맞게 이으세요.","pairs":[{"l":"증발이 일어나는 곳","r":"물의 표면"},{"l":"끓음이 일어나는 곳","r":"물의 표면과 물속"},{"l":"증발과 끓음의 같은 점","r":"물이 수증기로 변함"}],"mis":"SC4-1-u2-X31","explanation":["기포를 떠올려요.","같은 점도 있어요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_basic#7','sci',4,1,'u2','L05','g4_1_sci_u2_L05_basic','lesson_basic','SC4-1-u2-C26',2,'ox','auto','물이 수증기로 변하면 눈에 보이지 않지만 주위에 있어요.',ARRAY['SC4-1-u2-X08']::text[],false,'{"seq":7,"concept":"SC4-1-u2-C26","difficulty":2,"kind":"ox","stem":"물이 수증기로 변하면 눈에 보이지 않지만 주위에 있어요.","answer":"O","reason_options":[{"t":"수증기는 물의 기체 상태로 눈에 보이지 않을 뿐이기 때문에","correct":true},{"t":"보이지 않으면 아주 없어진 것이기 때문에","mis":"SC4-1-u2-X08"}],"mis":"SC4-1-u2-X08","explanation":["수증기를 떠올려요.","보이지 않아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_basic#8','sci',4,1,'u2','L05','g4_1_sci_u2_L05_basic','lesson_basic','SC4-1-u2-C27',2,'mc','auto','증발을 이용한 예는 무엇인가요?',ARRAY['SC4-1-u2-X32']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C27","difficulty":2,"kind":"mc","stem":"증발을 이용한 예는 무엇인가요?","options":[{"t":"염전에서 바닷물을 말려 소금을 얻는다","correct":true},{"t":"물을 끓여 달걀을 삶는다","mis":"SC4-1-u2-X32"},{"t":"물을 얼려 얼음과자를 만든다","mis":"SC4-1-u2-X32"},{"t":"차를 마시려고 물을 끓인다","mis":"SC4-1-u2-X32"}],"explanation":["말리는 것을 찾아요.","바닷물을 말려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_basic#9','sci',4,1,'u2','L05','g4_1_sci_u2_L05_basic','lesson_basic','SC4-1-u2-C28',2,'mc','auto','주전자의 물을 계속 가열하면 물의 양은 어떻게 되나요?',ARRAY['SC4-1-u2-X28','SC4-1-u2-X08']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C28","difficulty":2,"kind":"mc","stem":"주전자의 물을 계속 가열하면 물의 양은 어떻게 되나요?","options":[{"t":"계속 줄어든다","correct":true},{"t":"계속 늘어난다","mis":"SC4-1-u2-X28"},{"t":"끓기만 할 뿐 그대로이다","mis":"SC4-1-u2-X28"},{"t":"줄어든 물은 아주 사라져 어디에도 없다","mis":"SC4-1-u2-X08"}],"explanation":["물이 수증기가 돼요.","날아가요.","줄어들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_basic#10','sci',4,1,'u2','L05','g4_1_sci_u2_L05_basic','lesson_basic','SC4-1-u2-C28',3,'mc','auto','핫플레이트로 물을 가열할 때 지켜야 할 것은 무엇인가요?',ARRAY['SC4-1-u2-X33']::text[],false,'{"seq":10,"concept":"SC4-1-u2-C28","difficulty":3,"kind":"mc","stem":"핫플레이트로 물을 가열할 때 지켜야 할 것은 무엇인가요?","options":[{"t":"보안경과 면장갑을 끼고, 전원을 끈 뒤에도 바로 만지지 않는다","correct":true},{"t":"끓는지 보려고 비커에 얼굴을 가까이 댄다","mis":"SC4-1-u2-X33"},{"t":"전원을 끄면 바로 핫플레이트를 맨손으로 옮긴다","mis":"SC4-1-u2-X33"},{"t":"물이 끓으면 손가락을 넣어 뜨거운 정도를 느껴 본다","mis":"SC4-1-u2-X33"}],"explanation":["아주 뜨거워요.","끈 뒤에도 뜨거워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_challenge#1','sci',4,1,'u2','L05','g4_1_sci_u2_L05_challenge','lesson_challenge','SC4-1-u2-C25',2,'blank','auto','「증발과 끓음은 모두 액체인 물이 기체인 (      )(으)로 변하는 현상이에요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u2-X30','SC4-1-u2-X29','SC4-1-u2-X08']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C25","difficulty":2,"kind":"blank","stem":"「증발과 끓음은 모두 액체인 물이 기체인 (      )(으)로 변하는 현상이에요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"수증기","correct":true},{"t":"얼음","mis":"SC4-1-u2-X30"},{"t":"기포","mis":"SC4-1-u2-X29"},{"t":"공기","mis":"SC4-1-u2-X08"}],"explanation":["물의 기체 상태예요.","보이지 않아요.","수증기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_challenge#2','sci',4,1,'u2','L05','g4_1_sci_u2_L05_challenge','lesson_challenge','SC4-1-u2-C27',2,'mc','auto','곶감을 만들 때 깎은 감을 햇빛이 잘 들고 바람이 잘 부는 곳에 두는 까닭은 무엇인가요?',ARRAY['SC4-1-u2-X32','SC4-1-u2-X30']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C27","difficulty":2,"kind":"mc","stem":"곶감을 만들 때 깎은 감을 햇빛이 잘 들고 바람이 잘 부는 곳에 두는 까닭은 무엇인가요?","options":[{"t":"감 속의 물이 잘 증발하게 하려고","correct":true},{"t":"감 속의 물을 끓게 하려고","mis":"SC4-1-u2-X32"},{"t":"감 속의 물을 얼리려고","mis":"SC4-1-u2-X32"},{"t":"감이 공기 중의 물을 더 먹게 하려고","mis":"SC4-1-u2-X30"}],"explanation":["곶감은 말린 감이에요.","물이 날아가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_challenge#3','sci',4,1,'u2','L05','g4_1_sci_u2_L05_challenge','lesson_challenge','SC4-1-u2-C25',3,'mc','auto','「두 비커의 물 관찰」 [가]와 [나]의 공통점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X27','SC4-1-u2-X31','SC4-1-u2-X28']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C25","difficulty":3,"kind":"mc","stem":"「두 비커의 물 관찰」 [가]와 [나]의 공통점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"두 비커 모두 물이 수증기로 변해 물의 높이가 낮아졌다","correct":true},{"t":"[가]는 높이가 그대로이고 [나]만 낮아졌다","mis":"SC4-1-u2-X27"},{"t":"두 비커 모두 기포가 계속 생겼다","mis":"SC4-1-u2-X31"},{"t":"두 비커 모두 물의 높이가 높아졌다","mis":"SC4-1-u2-X28"}],"explanation":["두 비커의 높이를 봐요.","둘 다 낮아졌어요.","첫 번째예요."],"asset":{"type":"passage","lines":["[가] 비커를 햇빛이 잘 드는 곳에 두었다.","처음 → 2일 뒤 → 4일 뒤 물의 높이가 조금씩 낮아졌다.","[나] 비커를 핫플레이트로 가열했다.","작은 기포가 조금씩 생기다가 물 전체에서 기포가 계속 생겼다.","기포가 터지며 물 표면이 출렁였다.","끓기 시작하고 2분 뒤 물의 높이가 처음보다 낮아졌다."],"title":"두 비커의 물 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_challenge#4','sci',4,1,'u2','L05','g4_1_sci_u2_L05_challenge','lesson_challenge','SC4-1-u2-C24',3,'error','auto','물이 끓는 모습을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u2-X29','SC4-1-u2-X28']::text[],false,'{"seq":4,"concept":"SC4-1-u2-C24","difficulty":3,"kind":"error","stem":"물이 끓는 모습을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「끓을 때는 물 표면에서만 물이 수증기로 변해.」","correct":true,"mis_target":"SC4-1-u2-X29"},{"t":"친구 나 — 「물속에서 생긴 기포가 올라와 터졌어.」","mis":"SC4-1-u2-X29"},{"t":"친구 다 — 「끓고 나니 물의 높이가 낮아졌어.」","mis":"SC4-1-u2-X28"}],"explanation":["기포를 떠올려요.","물속에서도 변해요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["[가] 비커를 햇빛이 잘 드는 곳에 두었다.","처음 → 2일 뒤 → 4일 뒤 물의 높이가 조금씩 낮아졌다.","[나] 비커를 핫플레이트로 가열했다.","작은 기포가 조금씩 생기다가 물 전체에서 기포가 계속 생겼다.","기포가 터지며 물 표면이 출렁였다.","끓기 시작하고 2분 뒤 물의 높이가 처음보다 낮아졌다."],"title":"두 비커의 물 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_challenge#5','sci',4,1,'u2','L05','g4_1_sci_u2_L05_challenge','lesson_challenge','SC4-1-u2-C23',3,'ox','auto','증발은 물이 끓을 만큼 뜨거울 때에만 일어나요.',ARRAY['SC4-1-u2-X27']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C23","difficulty":3,"kind":"ox","stem":"증발은 물이 끓을 만큼 뜨거울 때에만 일어나요.","answer":"X","reason_options":[{"t":"햇빛이 드는 곳에 둔 물도 며칠에 걸쳐 증발하기 때문에","correct":true},{"t":"물은 뜨거워야만 수증기로 변하기 때문에","mis":"SC4-1-u2-X27"}],"mis":"SC4-1-u2-X27","explanation":["[가]를 떠올려요.","끓지 않아도 줄었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["[가] 비커를 햇빛이 잘 드는 곳에 두었다.","처음 → 2일 뒤 → 4일 뒤 물의 높이가 조금씩 낮아졌다.","[나] 비커를 핫플레이트로 가열했다.","작은 기포가 조금씩 생기다가 물 전체에서 기포가 계속 생겼다.","기포가 터지며 물 표면이 출렁였다.","끓기 시작하고 2분 뒤 물의 높이가 처음보다 낮아졌다."],"title":"두 비커의 물 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_challenge#6','sci',4,1,'u2','L05','g4_1_sci_u2_L05_challenge','lesson_challenge','SC4-1-u2-C24',3,'mc','auto','물이 끓기 시작한 뒤 물속에서 계속 생기는 기포는 무엇인가요?',ARRAY['SC4-1-u2-X29','SC4-1-u2-X30','SC4-1-u2-X08']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C24","difficulty":3,"kind":"mc","stem":"물이 끓기 시작한 뒤 물속에서 계속 생기는 기포는 무엇인가요?","options":[{"t":"물이 수증기로 변한 것","correct":true},{"t":"물속에 있던 돌가루","mis":"SC4-1-u2-X29"},{"t":"비커 바닥에서 생긴 얼음 조각","mis":"SC4-1-u2-X30"},{"t":"물이 아주 사라지며 생긴 빈 곳","mis":"SC4-1-u2-X08"}],"explanation":["끓음을 떠올려요.","물속에서 수증기가 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_challenge#7','sci',4,1,'u2','L05','g4_1_sci_u2_L05_challenge','lesson_challenge','SC4-1-u2-C27',3,'mc','auto','운동장에 고인 물이 하루 뒤 사라졌어요. 이 물은 어떻게 되었나요?',ARRAY['SC4-1-u2-X32','SC4-1-u2-X08','SC4-1-u2-X30']::text[],false,'{"seq":7,"concept":"SC4-1-u2-C27","difficulty":3,"kind":"mc","stem":"운동장에 고인 물이 하루 뒤 사라졌어요. 이 물은 어떻게 되었나요?","options":[{"t":"증발해 수증기가 되어 공기 중에 있다","correct":true},{"t":"끓어서 기포가 되었다","mis":"SC4-1-u2-X32"},{"t":"아주 없어져 어디에도 없다","mis":"SC4-1-u2-X08"},{"t":"땅속에서 얼음이 되었다","mis":"SC4-1-u2-X30"}],"explanation":["끓이지 않았어요.","표면에서 수증기가 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_challenge#8','sci',4,1,'u2','L05','g4_1_sci_u2_L05_challenge','lesson_challenge','SC4-1-u2-C26',4,'mc','auto','친구가 「끓인 물의 높이가 낮아진 건 물이 아주 없어졌기 때문이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X08','SC4-1-u2-X30','SC4-1-u2-X28']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C26","difficulty":4,"kind":"mc","stem":"친구가 「끓인 물의 높이가 낮아진 건 물이 아주 없어졌기 때문이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「물이 수증기가 되어 공기 중으로 갔어. 눈에 보이지 않을 뿐이야.」","correct":true},{"t":"「맞아, 끓으면 물이 없어져.」","mis":"SC4-1-u2-X08"},{"t":"「물이 비커 속에서 얼음이 되어 숨었어.」","mis":"SC4-1-u2-X30"},{"t":"「물이 끓으면 높이가 높아져야 해.」","mis":"SC4-1-u2-X28"}],"explanation":["수증기를 떠올려요.","보이지 않을 뿐이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_challenge#9','sci',4,1,'u2','L05','g4_1_sci_u2_L05_challenge','lesson_challenge','SC4-1-u2-C25',4,'mc','auto','증발과 끓음을 견준 것 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X31','SC4-1-u2-X30','SC4-1-u2-X27']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C25","difficulty":4,"kind":"mc","stem":"증발과 끓음을 견준 것 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"일어나는 곳과 빠르기는 달라도 둘 다 물이 수증기로 변한다","correct":true},{"t":"증발은 물속에서, 끓음은 표면에서만 일어난다","mis":"SC4-1-u2-X31"},{"t":"증발은 물이 수증기로, 끓음은 물이 얼음으로 변한다","mis":"SC4-1-u2-X30"},{"t":"증발은 뜨거운 물에서만 일어난다","mis":"SC4-1-u2-X27"}],"explanation":["공통점이 중요해요.","둘 다 수증기가 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L05_challenge#10','sci',4,1,'u2','L05','g4_1_sci_u2_L05_challenge','lesson_challenge','SC4-1-u2-C25',4,'essay','teacher','「두 비커의 물 관찰」 [가]와 [나]에서 물의 높이가 낮아진 까닭을 쓰고, 증발과 끓음의 공통점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u2-C25","difficulty":4,"kind":"essay","stem":"「두 비커의 물 관찰」 [가]와 [나]에서 물의 높이가 낮아진 까닭을 쓰고, 증발과 끓음의 공통점을 쓰세요.","answer_guide":{"answer":"예: [가]는 물이 표면에서 수증기로 변해 공기 중으로 날아가는 증발이 일어나 높이가 낮아졌다. [나]는 물의 표면과 물속에서 물이 수증기로 변하는 끓음이 일어나 높이가 낮아졌다. 증발과 끓음은 모두 액체인 물이 기체인 수증기로 변하는 현상이다.","scoring_points":["[가]를 증발로 설명했는가","[나]를 끓음으로 설명했는가","공통점(물→수증기)을 썼는가"]},"explanation":["두 비커를 봐요.","까닭을 써요.","공통점을 써요."],"asset":{"type":"passage","lines":["[가] 비커를 햇빛이 잘 드는 곳에 두었다.","처음 → 2일 뒤 → 4일 뒤 물의 높이가 조금씩 낮아졌다.","[나] 비커를 핫플레이트로 가열했다.","작은 기포가 조금씩 생기다가 물 전체에서 기포가 계속 생겼다.","기포가 터지며 물 표면이 출렁였다.","끓기 시작하고 2분 뒤 물의 높이가 처음보다 낮아졌다."],"title":"두 비커의 물 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_basic#1','sci',4,1,'u2','L06','g4_1_sci_u2_L06_basic','lesson_basic','SC4-1-u2-C31',1,'mc','auto','기체인 수증기가 액체인 물로 상태가 변하는 현상을 무엇이라고 하나요?',ARRAY['SC4-1-u2-X36']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C31","difficulty":1,"kind":"mc","stem":"기체인 수증기가 액체인 물로 상태가 변하는 현상을 무엇이라고 하나요?","options":[{"t":"응결","correct":true},{"t":"증발","mis":"SC4-1-u2-X36"},{"t":"끓음","mis":"SC4-1-u2-X36"},{"t":"녹음","mis":"SC4-1-u2-X36"}],"explanation":["수증기가 물이 돼요.","증발과 반대예요.","응결이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_basic#2','sci',4,1,'u2','L06','g4_1_sci_u2_L06_basic','lesson_basic','SC4-1-u2-C29',1,'mc','auto','「얼음이 든 비커 바깥면 관찰」에서 물방울이 맺힌 비커는 어느 것인가요?',ARRAY['SC4-1-u2-X35']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C29","difficulty":1,"kind":"mc","stem":"「얼음이 든 비커 바깥면 관찰」에서 물방울이 맺힌 비커는 어느 것인가요?","options":[{"t":"얼음과 주스를 함께 넣은 [나]","correct":true},{"t":"주스만 넣은 [가]","mis":"SC4-1-u2-X35"},{"t":"[가]와 [나] 모두","mis":"SC4-1-u2-X35"},{"t":"두 비커 모두 맺히지 않았다","mis":"SC4-1-u2-X35"}],"explanation":["셋째 줄을 읽어요.","[나]에만 맺혔어요.","첫 번째예요."],"asset":{"type":"passage","lines":["[가] 비커에 주스만 넣었다.","[나] 비커에 얼음과 주스를 함께 넣었다. 무게 423.1 g","시간이 지나자 [나]의 바깥면에만 물방울이 맺혔다.","물방울이 맺힌 [나]의 무게 425.1 g","물방울을 모두 닦으니 [나]의 무게 423.1 g","닦은 휴지 — [가] 그대로, [나] 젖었지만 주스 색이 없음"],"title":"얼음이 든 비커 바깥면 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_basic#3','sci',4,1,'u2','L06','g4_1_sci_u2_L06_basic','lesson_basic','SC4-1-u2-C30',1,'ox','auto','얼음이 든 비커 바깥면의 물방울은 비커 속 주스가 새어 나온 것이에요.',ARRAY['SC4-1-u2-X34']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C30","difficulty":1,"kind":"ox","stem":"얼음이 든 비커 바깥면의 물방울은 비커 속 주스가 새어 나온 것이에요.","answer":"X","reason_options":[{"t":"물방울을 닦은 휴지에 주스 색이 묻지 않았기 때문에","correct":true},{"t":"물방울은 비커 속에서만 나올 수 있기 때문에","mis":"SC4-1-u2-X34"}],"mis":"SC4-1-u2-X34","explanation":["휴지를 봐요.","주스 색이 없어요.","그래서 X예요."],"asset":{"type":"passage","lines":["[가] 비커에 주스만 넣었다.","[나] 비커에 얼음과 주스를 함께 넣었다. 무게 423.1 g","시간이 지나자 [나]의 바깥면에만 물방울이 맺혔다.","물방울이 맺힌 [나]의 무게 425.1 g","물방울을 모두 닦으니 [나]의 무게 423.1 g","닦은 휴지 — [가] 그대로, [나] 젖었지만 주스 색이 없음"],"title":"얼음이 든 비커 바깥면 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_basic#4','sci',4,1,'u2','L06','g4_1_sci_u2_L06_basic','lesson_basic','SC4-1-u2-C30',1,'sa','auto','비커 바깥면의 물방울은 공기 중에 있는 무엇이 물로 변한 것인가요?','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u2-C30","difficulty":1,"kind":"sa","stem":"비커 바깥면의 물방울은 공기 중에 있는 무엇이 물로 변한 것인가요?","answer":["수증기"],"explanation":["공기 중의 물이에요.","기체 상태예요.","수증기예요."],"mis":"SC4-1-u2-X34"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_basic#5','sci',4,1,'u2','L06','g4_1_sci_u2_L06_basic','lesson_basic','SC4-1-u2-C30',2,'mc','auto','「얼음이 든 비커 바깥면 관찰」에서 물방울이 맺힌 뒤 [나]의 무게가 늘어난 까닭은 무엇인가요?',ARRAY['SC4-1-u2-X34','SC4-1-u2-X21','SC4-1-u2-X38']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C30","difficulty":2,"kind":"mc","stem":"「얼음이 든 비커 바깥면 관찰」에서 물방울이 맺힌 뒤 [나]의 무게가 늘어난 까닭은 무엇인가요?","options":[{"t":"공기 중의 수증기가 물방울이 되어 바깥면에 붙었기 때문에","correct":true},{"t":"비커 속 주스가 새어 나왔기 때문에","mis":"SC4-1-u2-X34"},{"t":"얼음이 녹으면서 무게가 늘었기 때문에","mis":"SC4-1-u2-X21"},{"t":"물방울은 무게가 없어 늘어난 것이 아니다","mis":"SC4-1-u2-X38"}],"explanation":["밖에서 물이 더해졌어요.","수증기가 물이 됐어요.","첫 번째예요."],"asset":{"type":"passage","lines":["[가] 비커에 주스만 넣었다.","[나] 비커에 얼음과 주스를 함께 넣었다. 무게 423.1 g","시간이 지나자 [나]의 바깥면에만 물방울이 맺혔다.","물방울이 맺힌 [나]의 무게 425.1 g","물방울을 모두 닦으니 [나]의 무게 423.1 g","닦은 휴지 — [가] 그대로, [나] 젖었지만 주스 색이 없음"],"title":"얼음이 든 비커 바깥면 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_basic#6','sci',4,1,'u2','L06','g4_1_sci_u2_L06_basic','lesson_basic','SC4-1-u2-C32',2,'mc','auto','수증기가 응결하는 예는 무엇인가요?',ARRAY['SC4-1-u2-X37']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C32","difficulty":2,"kind":"mc","stem":"수증기가 응결하는 예는 무엇인가요?","options":[{"t":"따뜻한 차를 마실 때 안경이 뿌옇게 흐려진다","correct":true},{"t":"젖은 빨래가 마른다","mis":"SC4-1-u2-X37"},{"t":"얼음과자가 녹는다","mis":"SC4-1-u2-X37"},{"t":"주전자의 물이 끓는다","mis":"SC4-1-u2-X37"}],"explanation":["수증기가 물이 되는 것을 찾아요.","안경에 물방울이 맺혀요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_basic#7','sci',4,1,'u2','L06','g4_1_sci_u2_L06_basic','lesson_basic','SC4-1-u2-C33',2,'match','auto','물의 상태 변화와 그 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC4-1-u2-C33","difficulty":2,"kind":"match","stem":"물의 상태 변화와 그 이름을 알맞게 이으세요.","pairs":[{"l":"물이 표면에서 수증기로 변함","r":"증발"},{"l":"수증기가 물로 변함","r":"응결"},{"l":"물속에서도 물이 수증기로 변함","r":"끓음"}],"mis":"SC4-1-u2-X36","explanation":["방향을 봐요.","어디서 일어나나요?","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_basic#8','sci',4,1,'u2','L06','g4_1_sci_u2_L06_basic','lesson_basic','SC4-1-u2-C32',2,'ox','auto','목욕할 때 욕실 거울이 뿌옇게 흐려지는 것은 응결 때문이에요.',ARRAY['SC4-1-u2-X34']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C32","difficulty":2,"kind":"ox","stem":"목욕할 때 욕실 거울이 뿌옇게 흐려지는 것은 응결 때문이에요.","answer":"O","reason_options":[{"t":"따뜻한 수증기가 차가운 거울에 닿아 물로 변하기 때문에","correct":true},{"t":"거울 속에 있던 물이 밖으로 나오기 때문에","mis":"SC4-1-u2-X34"}],"mis":"SC4-1-u2-X34","explanation":["거울은 차가워요.","수증기가 닿아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_basic#9','sci',4,1,'u2','L06','g4_1_sci_u2_L06_basic','lesson_basic','SC4-1-u2-C29',2,'mc','auto','얼음을 넣지 않은 [가] 비커를 함께 관찰한 까닭은 무엇일까요?',ARRAY['SC4-1-u2-X35','SC4-1-u2-X34','SC4-1-u2-X38']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C29","difficulty":2,"kind":"mc","stem":"얼음을 넣지 않은 [가] 비커를 함께 관찰한 까닭은 무엇일까요?","options":[{"t":"얼음을 넣은 비커와 견주어 차가운 비커에서만 물방울이 맺히는지 알아보려고","correct":true},{"t":"두 비커에 모두 물방울이 맺히는지 보려고","mis":"SC4-1-u2-X35"},{"t":"주스가 더 빨리 새어 나오는지 보려고","mis":"SC4-1-u2-X34"},{"t":"[가] 비커가 더 무겁기 때문에","mis":"SC4-1-u2-X38"}],"explanation":["두 비커를 견줘요.","얼음만 달라요.","첫 번째예요."],"asset":{"type":"passage","lines":["[가] 비커에 주스만 넣었다.","[나] 비커에 얼음과 주스를 함께 넣었다. 무게 423.1 g","시간이 지나자 [나]의 바깥면에만 물방울이 맺혔다.","물방울이 맺힌 [나]의 무게 425.1 g","물방울을 모두 닦으니 [나]의 무게 423.1 g","닦은 휴지 — [가] 그대로, [나] 젖었지만 주스 색이 없음"],"title":"얼음이 든 비커 바깥면 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_basic#10','sci',4,1,'u2','L06','g4_1_sci_u2_L06_basic','lesson_basic','SC4-1-u2-C32',3,'mc','auto','물을 끓이는 냄비 뚜껑 안쪽에 물방울이 맺히는 까닭은 무엇인가요?',ARRAY['SC4-1-u2-X34','SC4-1-u2-X36','SC4-1-u2-X39']::text[],false,'{"seq":10,"concept":"SC4-1-u2-C32","difficulty":3,"kind":"mc","stem":"물을 끓이는 냄비 뚜껑 안쪽에 물방울이 맺히는 까닭은 무엇인가요?","options":[{"t":"냄비 속 물이 수증기가 되고, 그 수증기가 상대적으로 차가운 뚜껑에 닿아 응결하기 때문에","correct":true},{"t":"뚜껑 속에 있던 물이 스며 나오기 때문에","mis":"SC4-1-u2-X34"},{"t":"뚜껑에서 물이 증발해 붙기 때문에","mis":"SC4-1-u2-X36"},{"t":"뜨거운 뚜껑이 수증기를 끌어모아 끓이기 때문에","mis":"SC4-1-u2-X39"}],"explanation":["물이 수증기가 돼요.","뚜껑은 덜 뜨거워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_challenge#1','sci',4,1,'u2','L06','g4_1_sci_u2_L06_challenge','lesson_challenge','SC4-1-u2-C31',2,'blank','auto','「공기 중의 수증기가 차가운 비커의 바깥면에 닿아 물로 변하는 것을 (      )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u2-X36','SC4-1-u2-X37']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C31","difficulty":2,"kind":"blank","stem":"「공기 중의 수증기가 차가운 비커의 바깥면에 닿아 물로 변하는 것을 (      )(이)라고 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"응결","correct":true},{"t":"증발","mis":"SC4-1-u2-X36"},{"t":"끓음","mis":"SC4-1-u2-X36"},{"t":"녹음","mis":"SC4-1-u2-X37"}],"explanation":["수증기가 물이 돼요.","오늘 배운 낱말이에요.","응결이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_challenge#2','sci',4,1,'u2','L06','g4_1_sci_u2_L06_challenge','lesson_challenge','SC4-1-u2-C33',2,'mc','auto','증발과 응결을 바르게 견준 것은 무엇인가요?',ARRAY['SC4-1-u2-X36','SC4-1-u2-X37']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C33","difficulty":2,"kind":"mc","stem":"증발과 응결을 바르게 견준 것은 무엇인가요?","options":[{"t":"증발은 물이 수증기로, 응결은 수증기가 물로 변하는 것이다","correct":true},{"t":"증발은 수증기가 물로, 응결은 물이 수증기로 변하는 것이다","mis":"SC4-1-u2-X36"},{"t":"증발과 응결은 모두 물이 얼음으로 변하는 것이다","mis":"SC4-1-u2-X36"},{"t":"응결은 얼음이 물로 변하는 것이다","mis":"SC4-1-u2-X37"}],"explanation":["방향을 따져요.","서로 반대예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_challenge#3','sci',4,1,'u2','L06','g4_1_sci_u2_L06_challenge','lesson_challenge','SC4-1-u2-C30',3,'mc','auto','물방울을 닦은 휴지가 젖었지만 주스 색이 묻지 않았어요. 이것으로 알 수 있는 것은 무엇인가요?',ARRAY['SC4-1-u2-X34']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C30","difficulty":3,"kind":"mc","stem":"물방울을 닦은 휴지가 젖었지만 주스 색이 묻지 않았어요. 이것으로 알 수 있는 것은 무엇인가요?","options":[{"t":"물방울은 비커 속 주스가 아니라 공기 중에서 온 것이다","correct":true},{"t":"주스가 새어 나오면서 색만 빠졌다","mis":"SC4-1-u2-X34"},{"t":"물방울은 휴지 속에서 생겼다","mis":"SC4-1-u2-X34"},{"t":"얼음이 녹아 비커를 뚫고 나왔다","mis":"SC4-1-u2-X34"}],"explanation":["색을 봐요.","주스가 아니에요.","첫 번째예요."],"asset":{"type":"passage","lines":["[가] 비커에 주스만 넣었다.","[나] 비커에 얼음과 주스를 함께 넣었다. 무게 423.1 g","시간이 지나자 [나]의 바깥면에만 물방울이 맺혔다.","물방울이 맺힌 [나]의 무게 425.1 g","물방울을 모두 닦으니 [나]의 무게 423.1 g","닦은 휴지 — [가] 그대로, [나] 젖었지만 주스 색이 없음"],"title":"얼음이 든 비커 바깥면 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_challenge#4','sci',4,1,'u2','L06','g4_1_sci_u2_L06_challenge','lesson_challenge','SC4-1-u2-C30',3,'error','auto','비커 실험을 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u2-X38','SC4-1-u2-X34']::text[],false,'{"seq":4,"concept":"SC4-1-u2-C30","difficulty":3,"kind":"error","stem":"비커 실험을 마치고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「물방울은 무게가 없으니 비커 무게는 그대로야.」","correct":true,"mis_target":"SC4-1-u2-X38"},{"t":"친구 가 — 「물방울이 맺히니 무게가 늘었어.」","mis":"SC4-1-u2-X38"},{"t":"친구 나 — 「물방울을 닦으니 처음 무게로 돌아왔어.」","mis":"SC4-1-u2-X34"}],"explanation":["무게를 봐요.","423.1 g → 425.1 g이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["[가] 비커에 주스만 넣었다.","[나] 비커에 얼음과 주스를 함께 넣었다. 무게 423.1 g","시간이 지나자 [나]의 바깥면에만 물방울이 맺혔다.","물방울이 맺힌 [나]의 무게 425.1 g","물방울을 모두 닦으니 [나]의 무게 423.1 g","닦은 휴지 — [가] 그대로, [나] 젖었지만 주스 색이 없음"],"title":"얼음이 든 비커 바깥면 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_challenge#5','sci',4,1,'u2','L06','g4_1_sci_u2_L06_challenge','lesson_challenge','SC4-1-u2-C32',3,'ox','auto','이른 아침 거미줄에 맺힌 이슬은 수증기가 응결한 것이에요.',ARRAY['SC4-1-u2-X37']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C32","difficulty":3,"kind":"ox","stem":"이른 아침 거미줄에 맺힌 이슬은 수증기가 응결한 것이에요.","answer":"O","reason_options":[{"t":"공기 중의 수증기가 차가운 거미줄에 닿아 물로 변했기 때문에","correct":true},{"t":"거미가 거미줄에 물을 뿌려 두었기 때문에","mis":"SC4-1-u2-X37"}],"mis":"SC4-1-u2-X37","explanation":["아침은 서늘해요.","수증기가 물이 돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_challenge#6','sci',4,1,'u2','L06','g4_1_sci_u2_L06_challenge','lesson_challenge','SC4-1-u2-C32',3,'mc','auto','응결과 관계있는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC4-1-u2-X37','SC4-1-u2-X36']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C32","difficulty":3,"kind":"mc","stem":"응결과 관계있는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"추운 겨울 유리창 안쪽의 물방울, 냉동실에서 꺼낸 물병 표면의 물방울","correct":true},{"t":"젖은 빨래가 마름, 어항의 물이 줄어듦","mis":"SC4-1-u2-X37"},{"t":"고드름이 녹음, 강물이 얾","mis":"SC4-1-u2-X37"},{"t":"유리창 안쪽 물방울, 젖은 빨래가 마름","mis":"SC4-1-u2-X36"}],"explanation":["수증기가 물이 되는 것을 찾아요.","둘 다 물방울이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_challenge#7','sci',4,1,'u2','L06','g4_1_sci_u2_L06_challenge','lesson_challenge','SC4-1-u2-C29',3,'mc','auto','얼음이 든 비커 바깥면에 물방울이 잘 맺히게 하려면 어떻게 하는 것이 좋을까요?',ARRAY['SC4-1-u2-X39','SC4-1-u2-X34']::text[],false,'{"seq":7,"concept":"SC4-1-u2-C29","difficulty":3,"kind":"mc","stem":"얼음이 든 비커 바깥면에 물방울이 잘 맺히게 하려면 어떻게 하는 것이 좋을까요?","options":[{"t":"얼음을 많이 넣어 비커를 아주 차갑게 한다","correct":true},{"t":"얼음을 빼고 따뜻한 주스만 넣는다","mis":"SC4-1-u2-X39"},{"t":"비커 바깥면을 따뜻하게 데운다","mis":"SC4-1-u2-X39"},{"t":"비커에 작은 구멍을 뚫는다","mis":"SC4-1-u2-X34"}],"explanation":["차가워야 해요.","얼음이 많을수록요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_challenge#8','sci',4,1,'u2','L06','g4_1_sci_u2_L06_challenge','lesson_challenge','SC4-1-u2-C30',4,'mc','auto','친구가 「차가운 컵 바깥에 맺힌 물방울은 컵 속 음료수가 컵 벽을 뚫고 나온 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X34','SC4-1-u2-X36','SC4-1-u2-X35']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C30","difficulty":4,"kind":"mc","stem":"친구가 「차가운 컵 바깥에 맺힌 물방울은 컵 속 음료수가 컵 벽을 뚫고 나온 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「물방울에 음료수 색이 없고, 얼음을 넣지 않은 컵에는 안 맺혀. 공기 중 수증기가 응결한 거야.」","correct":true},{"t":"「맞아, 컵 속 음료수가 새어 나온 거야.」","mis":"SC4-1-u2-X34"},{"t":"「컵 바깥의 물이 증발해 맺힌 거야.」","mis":"SC4-1-u2-X36"},{"t":"「얼음이 없어도 모든 컵에 똑같이 맺혀.」","mis":"SC4-1-u2-X35"}],"explanation":["색이 없어요.","차가운 컵에만요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_challenge#9','sci',4,1,'u2','L06','g4_1_sci_u2_L06_challenge','lesson_challenge','SC4-1-u2-C33',4,'mc','auto','얼음, 물, 수증기 사이의 상태 변화를 바르게 말한 것은 무엇인가요?',ARRAY['SC4-1-u2-X36','SC4-1-u2-X30']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C33","difficulty":4,"kind":"mc","stem":"얼음, 물, 수증기 사이의 상태 변화를 바르게 말한 것은 무엇인가요?","options":[{"t":"물이 얼면 얼음, 얼음이 녹으면 물, 물이 증발하거나 끓으면 수증기, 수증기가 응결하면 물이 된다","correct":true},{"t":"수증기가 증발하면 물이 된다","mis":"SC4-1-u2-X36"},{"t":"물이 응결하면 수증기가 된다","mis":"SC4-1-u2-X36"},{"t":"얼음이 끓으면 수증기가 바로 된다","mis":"SC4-1-u2-X30"}],"explanation":["네 방향을 떠올려요.","이름을 맞춰요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L06_challenge#10','sci',4,1,'u2','L06','g4_1_sci_u2_L06_challenge','lesson_challenge','SC4-1-u2-C30',4,'essay','teacher','「얼음이 든 비커 바깥면 관찰」에서 [나] 비커 바깥면에 맺힌 물방울이 어디에서 왔는지 쓰고, 그 증거 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u2-C30","difficulty":4,"kind":"essay","stem":"「얼음이 든 비커 바깥면 관찰」에서 [나] 비커 바깥면에 맺힌 물방울이 어디에서 왔는지 쓰고, 그 증거 두 가지를 쓰세요.","answer_guide":{"answer":"예: 물방울은 공기 중의 수증기가 차가운 비커 바깥면에 닿아 응결한 것이다. 증거 1 — 물방울을 닦은 휴지에 주스 색이 없었다. 증거 2 — 물방울이 맺히자 무게가 423.1 g에서 425.1 g으로 늘었고, 닦으니 처음 무게로 돌아왔다.","scoring_points":["공기 중 수증기가 응결했다고 썼는가","휴지 색 증거를 썼는가","무게 증거나 [가]와의 비교를 썼는가"]},"explanation":["어디에서 왔나요?","휴지를 봐요.","무게를 봐요."],"asset":{"type":"passage","lines":["[가] 비커에 주스만 넣었다.","[나] 비커에 얼음과 주스를 함께 넣었다. 무게 423.1 g","시간이 지나자 [나]의 바깥면에만 물방울이 맺혔다.","물방울이 맺힌 [나]의 무게 425.1 g","물방울을 모두 닦으니 [나]의 무게 423.1 g","닦은 휴지 — [가] 그대로, [나] 젖었지만 주스 색이 없음"],"title":"얼음이 든 비커 바깥면 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_basic#1','sci',4,1,'u2','L07','g4_1_sci_u2_L07_basic','lesson_basic','SC4-1-u2-C35',1,'mc','auto','와카워터는 물의 어떤 상태 변화를 이용해 물을 모으는 장치인가요?',ARRAY['SC4-1-u2-X41']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C35","difficulty":1,"kind":"mc","stem":"와카워터는 물의 어떤 상태 변화를 이용해 물을 모으는 장치인가요?","options":[{"t":"공기 중의 수증기가 물로 변하는 응결","correct":true},{"t":"얼음이 물로 녹는 변화","mis":"SC4-1-u2-X41"},{"t":"물이 끓는 변화","mis":"SC4-1-u2-X41"},{"t":"물이 얼음으로 어는 변화","mis":"SC4-1-u2-X41"}],"explanation":["공기 중에서 물을 모아요.","수증기가 물이 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_basic#2','sci',4,1,'u2','L07','g4_1_sci_u2_L07_basic','lesson_basic','SC4-1-u2-C34',1,'mc','auto','물이 우리에게 중요한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X46','SC4-1-u2-X40']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C34","difficulty":1,"kind":"mc","stem":"물이 우리에게 중요한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"우리 몸을 이루고, 동물과 식물이 살아가고 농사를 짓는 데 필요하기 때문에","correct":true},{"t":"물은 놀이에만 쓰이기 때문에","mis":"SC4-1-u2-X46"},{"t":"물은 사람에게만 필요하기 때문에","mis":"SC4-1-u2-X46"},{"t":"물은 어디에나 많아 걱정할 필요가 없기 때문에","mis":"SC4-1-u2-X40"}],"explanation":["몸과 생물을 떠올려요.","농사도요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_basic#3','sci',4,1,'u2','L07','g4_1_sci_u2_L07_basic','lesson_basic','SC4-1-u2-C38',1,'ox','auto','「물을 얻는 장치 만들기」에서 작은 그릇에 모인 물은 색소 색이 없어요.',ARRAY['SC4-1-u2-X43']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C38","difficulty":1,"kind":"ox","stem":"「물을 얻는 장치 만들기」에서 작은 그릇에 모인 물은 색소 색이 없어요.","answer":"O","reason_options":[{"t":"색소는 남고 물만 증발해 수증기가 되었다가 응결하기 때문에","correct":true},{"t":"색소도 물과 함께 수증기가 되어 작은 그릇에 모이기 때문에","mis":"SC4-1-u2-X43"}],"mis":"SC4-1-u2-X43","explanation":["무엇이 증발하나요?","물만 수증기가 돼요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 큰 그릇 가운데에 작은 그릇을 붙인다.","② 색소를 탄 물을 큰 그릇에만 넣는다. 작은 그릇은 비워 둔다.","③ 큰 그릇 입구를 비닐로 덮고 가운데를 움푹하게 누른다.","④ 고무줄로 비닐을 고정하고 비닐 가운데에 자갈을 올린다.","⑤ 햇빛이 강한 곳에 3일 두고 관찰한다."],"title":"물을 얻는 장치 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_basic#4','sci',4,1,'u2','L07','g4_1_sci_u2_L07_basic','lesson_basic','SC4-1-u2-C37',1,'sa','auto','「물을 얻는 장치 만들기」 ④에서 비닐 가운데에 올리는 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u2-C37","difficulty":1,"kind":"sa","stem":"「물을 얻는 장치 만들기」 ④에서 비닐 가운데에 올리는 것은 무엇인가요? 두 글자로 쓰세요.","answer":["자갈"],"explanation":["④를 읽어요.","작은 돌이에요.","자갈이에요."],"asset":{"type":"passage","lines":["① 큰 그릇 가운데에 작은 그릇을 붙인다.","② 색소를 탄 물을 큰 그릇에만 넣는다. 작은 그릇은 비워 둔다.","③ 큰 그릇 입구를 비닐로 덮고 가운데를 움푹하게 누른다.","④ 고무줄로 비닐을 고정하고 비닐 가운데에 자갈을 올린다.","⑤ 햇빛이 강한 곳에 3일 두고 관찰한다."],"title":"물을 얻는 장치 만들기"},"mis":"SC4-1-u2-X44"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_basic#5','sci',4,1,'u2','L07','g4_1_sci_u2_L07_basic','lesson_basic','SC4-1-u2-C38',2,'mc','auto','「물을 얻는 장치 만들기」에서 작은 그릇에 물이 모이는 차례로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X41','SC4-1-u2-X36']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C38","difficulty":2,"kind":"mc","stem":"「물을 얻는 장치 만들기」에서 작은 그릇에 물이 모이는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"큰 그릇의 물이 증발 → 비닐 안쪽에서 응결 → 물방울이 흘러 작은 그릇에 떨어짐","correct":true},{"t":"비닐이 녹아 → 작은 그릇에 떨어짐","mis":"SC4-1-u2-X41"},{"t":"큰 그릇의 물이 끓어 → 작은 그릇으로 넘쳐 들어감","mis":"SC4-1-u2-X41"},{"t":"비닐 안쪽에서 증발 → 큰 그릇에서 응결","mis":"SC4-1-u2-X36"}],"explanation":["햇빛이 물을 데워요.","비닐에 물방울이 맺혀요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 큰 그릇 가운데에 작은 그릇을 붙인다.","② 색소를 탄 물을 큰 그릇에만 넣는다. 작은 그릇은 비워 둔다.","③ 큰 그릇 입구를 비닐로 덮고 가운데를 움푹하게 누른다.","④ 고무줄로 비닐을 고정하고 비닐 가운데에 자갈을 올린다.","⑤ 햇빛이 강한 곳에 3일 두고 관찰한다."],"title":"물을 얻는 장치 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_basic#6','sci',4,1,'u2','L07','g4_1_sci_u2_L07_basic','lesson_basic','SC4-1-u2-C36',2,'mc','auto','워터콘에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X42','SC4-1-u2-X41','SC4-1-u2-X43']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C36","difficulty":2,"kind":"mc","stem":"워터콘에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"흙탕물이나 바닷물이 햇빛에 증발했다가 투명한 뚜껑에서 응결해 깨끗한 물을 얻는다","correct":true},{"t":"흙탕물을 그대로 걸러 마신다","mis":"SC4-1-u2-X42"},{"t":"물을 얼려 얼음을 얻는다","mis":"SC4-1-u2-X41"},{"t":"흙탕물이 그대로 증발해 흙도 함께 모인다","mis":"SC4-1-u2-X43"}],"explanation":["햇빛을 써요.","증발하고 응결해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_basic#7','sci',4,1,'u2','L07','g4_1_sci_u2_L07_basic','lesson_basic','SC4-1-u2-C37',2,'mc','auto','「물을 얻는 장치 만들기」 ③에서 비닐 가운데를 움푹하게 누르는 까닭은 무엇인가요?',ARRAY['SC4-1-u2-X45','SC4-1-u2-X41','SC4-1-u2-X44']::text[],false,'{"seq":7,"concept":"SC4-1-u2-C37","difficulty":2,"kind":"mc","stem":"「물을 얻는 장치 만들기」 ③에서 비닐 가운데를 움푹하게 누르는 까닭은 무엇인가요?","options":[{"t":"비닐에 맺힌 물방울이 빗면을 따라 가운데로 흘러 작은 그릇에 떨어지게 하려고","correct":true},{"t":"비닐이 팽팽하면 보기에 깔끔하지 않기 때문에","mis":"SC4-1-u2-X45"},{"t":"비닐이 녹아 물이 되게 하려고","mis":"SC4-1-u2-X41"},{"t":"색소 물이 작은 그릇으로 넘쳐 들어가게 하려고","mis":"SC4-1-u2-X44"}],"explanation":["물방울은 아래로 흘러요.","가운데가 가장 낮아요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 큰 그릇 가운데에 작은 그릇을 붙인다.","② 색소를 탄 물을 큰 그릇에만 넣는다. 작은 그릇은 비워 둔다.","③ 큰 그릇 입구를 비닐로 덮고 가운데를 움푹하게 누른다.","④ 고무줄로 비닐을 고정하고 비닐 가운데에 자갈을 올린다.","⑤ 햇빛이 강한 곳에 3일 두고 관찰한다."],"title":"물을 얻는 장치 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_basic#8','sci',4,1,'u2','L07','g4_1_sci_u2_L07_basic','lesson_basic','SC4-1-u2-C40',2,'ox','auto','지구에는 물이 많으니 우리가 쓸 수 있는 깨끗한 물도 넉넉해요.',ARRAY['SC4-1-u2-X40']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C40","difficulty":2,"kind":"ox","stem":"지구에는 물이 많으니 우리가 쓸 수 있는 깨끗한 물도 넉넉해요.","answer":"X","reason_options":[{"t":"인구 증가, 산업 발달 등으로 쓸 수 있는 물이 점점 줄어들고 있기 때문에","correct":true},{"t":"지구 전체에 물이 많으면 모두 마실 수 있기 때문에","mis":"SC4-1-u2-X40"}],"mis":"SC4-1-u2-X40","explanation":["쓸 수 있는 물을 떠올려요.","점점 줄어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_basic#9','sci',4,1,'u2','L07','g4_1_sci_u2_L07_basic','lesson_basic','SC4-1-u2-C39',2,'mc','auto','물을 얻는 장치를 설계할 때 가장 먼저 정할 것으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X45','SC4-1-u2-X42']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C39","difficulty":2,"kind":"mc","stem":"물을 얻는 장치를 설계할 때 가장 먼저 정할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"어떤 물의 상태 변화를 이용할지","correct":true},{"t":"가장 비싼 재료가 무엇인지","mis":"SC4-1-u2-X45"},{"t":"겉모습을 얼마나 화려하게 꾸밀지","mis":"SC4-1-u2-X45"},{"t":"물의 상태 변화와 상관없는 기계를 무엇으로 할지","mis":"SC4-1-u2-X42"}],"explanation":["증발일까, 응결일까요?","원리가 먼저예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_basic#10','sci',4,1,'u2','L07','g4_1_sci_u2_L07_basic','lesson_basic','SC4-1-u2-C34',3,'mc','auto','물 부족 현상의 원인으로 알맞지 않은 것은 무엇인가요?',ARRAY['SC4-1-u2-X46']::text[],false,'{"seq":10,"concept":"SC4-1-u2-C34","difficulty":3,"kind":"mc","stem":"물 부족 현상의 원인으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"얼음이 녹아 물이 되는 것","correct":true},{"t":"인구가 늘어나는 것","mis":"SC4-1-u2-X46"},{"t":"가뭄이나 폭염이 심해지는 것","mis":"SC4-1-u2-X46"},{"t":"물이 오염되는 것","mis":"SC4-1-u2-X46"}],"explanation":["원인을 떠올려요.","인구·가뭄·오염이에요.","얼음이 녹는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_challenge#1','sci',4,1,'u2','L07','g4_1_sci_u2_L07_challenge','lesson_challenge','SC4-1-u2-C36',2,'blank','auto','「그물망 포집기는 그물망으로 공기 중의 (      )을/를 모아 물을 얻어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u2-X42','SC4-1-u2-X41']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C36","difficulty":2,"kind":"blank","stem":"「그물망 포집기는 그물망으로 공기 중의 (      )을/를 모아 물을 얻어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"물방울","correct":true},{"t":"흙먼지","mis":"SC4-1-u2-X42"},{"t":"얼음 덩어리","mis":"SC4-1-u2-X41"},{"t":"빗물 저금통","mis":"SC4-1-u2-X42"}],"explanation":["공기 중의 물이에요.","그물에 맺혀요.","물방울이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_challenge#2','sci',4,1,'u2','L07','g4_1_sci_u2_L07_challenge','lesson_challenge','SC4-1-u2-C40',2,'mc','auto','쓴 물을 다시 깨끗하게 만들어 쓰기 어려운 까닭은 무엇인가요?',ARRAY['SC4-1-u2-X40','SC4-1-u2-X08']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C40","difficulty":2,"kind":"mc","stem":"쓴 물을 다시 깨끗하게 만들어 쓰기 어려운 까닭은 무엇인가요?","options":[{"t":"오랜 시간과 많은 비용이 들기 때문에","correct":true},{"t":"쓴 물은 바로 다시 깨끗해지기 때문에","mis":"SC4-1-u2-X40"},{"t":"물은 한 번 쓰면 사라져 없어지기 때문에","mis":"SC4-1-u2-X08"},{"t":"물은 많으니 다시 쓸 필요가 없기 때문에","mis":"SC4-1-u2-X40"}],"explanation":["깨끗하게 하려면?","시간과 돈이 들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_challenge#3','sci',4,1,'u2','L07','g4_1_sci_u2_L07_challenge','lesson_challenge','SC4-1-u2-C36',3,'mc','auto','물의 상태 변화를 이용해 물을 얻는 장치가 아닌 것은 무엇인가요?',ARRAY['SC4-1-u2-X42']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C36","difficulty":3,"kind":"mc","stem":"물의 상태 변화를 이용해 물을 얻는 장치가 아닌 것은 무엇인가요?","options":[{"t":"지붕의 빗물을 그대로 모아 두는 빗물 저금통","correct":true},{"t":"와카워터","mis":"SC4-1-u2-X42"},{"t":"워터콘","mis":"SC4-1-u2-X42"},{"t":"솔라볼","mis":"SC4-1-u2-X42"}],"explanation":["상태가 변하나요?","빗물은 그대로 모아요.","빗물 저금통이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_challenge#4','sci',4,1,'u2','L07','g4_1_sci_u2_L07_challenge','lesson_challenge','SC4-1-u2-C37',3,'error','auto','모둠 친구들이 장치를 만들며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u2-X44','SC4-1-u2-X41']::text[],false,'{"seq":4,"concept":"SC4-1-u2-C37","difficulty":3,"kind":"error","stem":"모둠 친구들이 장치를 만들며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「작은 그릇에도 색소 물을 가득 넣자.」","correct":true,"mis_target":"SC4-1-u2-X44"},{"t":"친구 가 — 「비닐 가운데에 자갈을 올리자.」","mis":"SC4-1-u2-X44"},{"t":"친구 다 — 「햇빛이 강한 곳에 두자.」","mis":"SC4-1-u2-X41"}],"explanation":["②를 읽어요.","작은 그릇은 비워요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 큰 그릇 가운데에 작은 그릇을 붙인다.","② 색소를 탄 물을 큰 그릇에만 넣는다. 작은 그릇은 비워 둔다.","③ 큰 그릇 입구를 비닐로 덮고 가운데를 움푹하게 누른다.","④ 고무줄로 비닐을 고정하고 비닐 가운데에 자갈을 올린다.","⑤ 햇빛이 강한 곳에 3일 두고 관찰한다."],"title":"물을 얻는 장치 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_challenge#5','sci',4,1,'u2','L07','g4_1_sci_u2_L07_challenge','lesson_challenge','SC4-1-u2-C35',3,'ox','auto','와카워터는 환경을 오염시키지 않고 물을 모을 수 있어요.',ARRAY['SC4-1-u2-X41']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C35","difficulty":3,"kind":"ox","stem":"와카워터는 환경을 오염시키지 않고 물을 모을 수 있어요.","answer":"O","reason_options":[{"t":"공기 중의 수증기가 응결하는 것을 이용하기 때문에","correct":true},{"t":"물을 끓여 모으기 때문에","mis":"SC4-1-u2-X41"}],"mis":"SC4-1-u2-X41","explanation":["공기 중의 수증기예요.","응결이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_challenge#6','sci',4,1,'u2','L07','g4_1_sci_u2_L07_challenge','lesson_challenge','SC4-1-u2-C38',3,'mc','auto','「물을 얻는 장치 만들기」에서 큰 그릇에 흙탕물을 넣으면 작은 그릇에 모이는 물은 어떨까요?',ARRAY['SC4-1-u2-X43','SC4-1-u2-X41']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C38","difficulty":3,"kind":"mc","stem":"「물을 얻는 장치 만들기」에서 큰 그릇에 흙탕물을 넣으면 작은 그릇에 모이는 물은 어떨까요?","options":[{"t":"흙은 남고 물만 증발했다가 응결하므로 깨끗한 물이 모인다","correct":true},{"t":"흙도 함께 증발해 흙탕물이 모인다","mis":"SC4-1-u2-X43"},{"t":"물이 하나도 모이지 않는다","mis":"SC4-1-u2-X41"},{"t":"비닐을 지나며 흙탕물이 그대로 모인다","mis":"SC4-1-u2-X43"}],"explanation":["무엇이 증발하나요?","물만이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 큰 그릇 가운데에 작은 그릇을 붙인다.","② 색소를 탄 물을 큰 그릇에만 넣는다. 작은 그릇은 비워 둔다.","③ 큰 그릇 입구를 비닐로 덮고 가운데를 움푹하게 누른다.","④ 고무줄로 비닐을 고정하고 비닐 가운데에 자갈을 올린다.","⑤ 햇빛이 강한 곳에 3일 두고 관찰한다."],"title":"물을 얻는 장치 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_challenge#7','sci',4,1,'u2','L07','g4_1_sci_u2_L07_challenge','lesson_challenge','SC4-1-u2-C39',3,'mc','auto','물을 얻는 장치를 평가할 때 가장 중요하게 볼 것은 무엇인가요?',ARRAY['SC4-1-u2-X45','SC4-1-u2-X42']::text[],false,'{"seq":7,"concept":"SC4-1-u2-C39","difficulty":3,"kind":"mc","stem":"물을 얻는 장치를 평가할 때 가장 중요하게 볼 것은 무엇인가요?","options":[{"t":"물의 상태 변화를 이용해 설계했는가","correct":true},{"t":"가장 비싼 재료를 썼는가","mis":"SC4-1-u2-X45"},{"t":"다른 모둠보다 크게 만들었는가","mis":"SC4-1-u2-X45"},{"t":"상태 변화 없이 물을 모았는가","mis":"SC4-1-u2-X42"}],"explanation":["원리를 봐요.","상태 변화를 이용했나요?","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_challenge#8','sci',4,1,'u2','L07','g4_1_sci_u2_L07_challenge','lesson_challenge','SC4-1-u2-C37',4,'mc','auto','친구가 장치를 만들며 「비닐은 팽팽하게 펴고 자갈은 빼는 게 더 깔끔해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X44','SC4-1-u2-X41','SC4-1-u2-X45']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C37","difficulty":4,"kind":"mc","stem":"친구가 장치를 만들며 「비닐은 팽팽하게 펴고 자갈은 빼는 게 더 깔끔해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「비닐 가운데가 움푹해야 물방울이 흘러 작은 그릇에 떨어져. 자갈을 올려 두자.」","correct":true},{"t":"「맞아, 팽팽하면 물이 더 많이 모여.」","mis":"SC4-1-u2-X44"},{"t":"「자갈이 있어야 비닐이 녹아 물이 돼.」","mis":"SC4-1-u2-X41"},{"t":"「겉모습이 깔끔한 게 가장 중요해.」","mis":"SC4-1-u2-X45"}],"explanation":["물방울은 낮은 곳으로 가요.","가운데가 낮아야 해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_challenge#9','sci',4,1,'u2','L07','g4_1_sci_u2_L07_challenge','lesson_challenge','SC4-1-u2-C40',4,'mc','auto','친구가 「우리나라에는 비가 오니까 물을 아낄 필요가 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X40','SC4-1-u2-X08','SC4-1-u2-X46']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C40","difficulty":4,"kind":"mc","stem":"친구가 「우리나라에는 비가 오니까 물을 아낄 필요가 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「가뭄·폭염과 오염 때문에 쓸 수 있는 깨끗한 물은 점점 줄어들고 있어.」","correct":true},{"t":"「맞아, 비가 오면 물은 늘 넉넉해.」","mis":"SC4-1-u2-X40"},{"t":"「물은 쓰면 사라져 없어지니 상관없어.」","mis":"SC4-1-u2-X08"},{"t":"「물은 사람에게만 필요해서 괜찮아.」","mis":"SC4-1-u2-X46"}],"explanation":["쓸 수 있는 물을 떠올려요.","점점 줄어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L07_challenge#10','sci',4,1,'u2','L07','g4_1_sci_u2_L07_challenge','lesson_challenge','SC4-1-u2-C38',4,'essay','teacher','「물을 얻는 장치 만들기」에서 깨끗한 물이 모이는 곳을 쓰고, 그곳에 물이 모이는 까닭을 증발과 응결을 넣어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u2-C38","difficulty":4,"kind":"essay","stem":"「물을 얻는 장치 만들기」에서 깨끗한 물이 모이는 곳을 쓰고, 그곳에 물이 모이는 까닭을 증발과 응결을 넣어 쓰세요.","answer_guide":{"answer":"예: 깨끗한 물은 가운데의 작은 그릇에 모인다. 햇빛을 받아 큰 그릇의 물이 증발해 수증기가 되고, 이 수증기가 비닐 안쪽에 닿아 응결해 물방울이 된다. 물방울이 움푹한 비닐을 따라 흘러 작은 그릇에 떨어진다. 색소는 증발하지 않아 모인 물은 색이 없다.","scoring_points":["작은 그릇이라고 썼는가","증발과 응결을 차례대로 썼는가","물방울이 흘러 떨어지는 까닭이나 색이 없는 까닭을 썼는가"]},"explanation":["어디에 모이나요?","증발 → 응결이에요.","까닭을 써요."],"asset":{"type":"passage","lines":["① 큰 그릇 가운데에 작은 그릇을 붙인다.","② 색소를 탄 물을 큰 그릇에만 넣는다. 작은 그릇은 비워 둔다.","③ 큰 그릇 입구를 비닐로 덮고 가운데를 움푹하게 누른다.","④ 고무줄로 비닐을 고정하고 비닐 가운데에 자갈을 올린다.","⑤ 햇빛이 강한 곳에 3일 두고 관찰한다."],"title":"물을 얻는 장치 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L08_basic#1','sci',4,1,'u2','L08','g4_1_sci_u2_L08_basic','lesson_basic','SC4-1-u2-C41',1,'mc','auto','세계 물의 날은 언제인가요?',ARRAY['SC4-1-u2-X50']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C41","difficulty":1,"kind":"mc","stem":"세계 물의 날은 언제인가요?","options":[{"t":"3월 22일","correct":true},{"t":"4월 22일","mis":"SC4-1-u2-X50"},{"t":"6월 5일","mis":"SC4-1-u2-X50"},{"t":"9월 7일","mis":"SC4-1-u2-X50"}],"explanation":["봄이에요.","3월이에요.","3월 22일이에요."],"asset":{"type":"passage","lines":["지구 표면의 대부분은 물로 덮여 있지만 쓸 수 있는 물은 매우 적다.","국제 연합은 매년 3월 22일을 세계 물의 날로 정했다.","이날 여러 나라에서 기념식, 전시회, 캠페인이 열린다.","개인의 작은 실천이 모여 큰 변화를 만들 수 있다."],"title":"세계 물의 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L08_basic#2','sci',4,1,'u2','L08','g4_1_sci_u2_L08_basic','lesson_basic','SC4-1-u2-C43',1,'mc','auto','물을 아끼는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X48']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C43","difficulty":1,"kind":"mc","stem":"물을 아끼는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"양치할 때 컵에 물을 받아 쓴다","correct":true},{"t":"양치하는 동안 물을 계속 틀어 둔다","mis":"SC4-1-u2-X48"},{"t":"물을 컵에 가득 따르고 남기면 버린다","mis":"SC4-1-u2-X48"},{"t":"물장난을 하며 손을 씻는다","mis":"SC4-1-u2-X48"}],"explanation":["양치를 떠올려요.","컵을 써요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L08_basic#3','sci',4,1,'u2','L08','g4_1_sci_u2_L08_basic','lesson_basic','SC4-1-u2-C42',1,'ox','auto','지구 표면의 대부분이 물이니 우리가 쓸 수 있는 물도 아주 많아요.',ARRAY['SC4-1-u2-X40']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C42","difficulty":1,"kind":"ox","stem":"지구 표면의 대부분이 물이니 우리가 쓸 수 있는 물도 아주 많아요.","answer":"X","reason_options":[{"t":"지구의 물 가운데 우리가 쓸 수 있는 물은 매우 적기 때문에","correct":true},{"t":"바닷물도 그대로 마시고 쓸 수 있기 때문에","mis":"SC4-1-u2-X40"}],"mis":"SC4-1-u2-X40","explanation":["첫 줄을 읽어요.","쓸 수 있는 물은 적어요.","그래서 X예요."],"asset":{"type":"passage","lines":["지구 표면의 대부분은 물로 덮여 있지만 쓸 수 있는 물은 매우 적다.","국제 연합은 매년 3월 22일을 세계 물의 날로 정했다.","이날 여러 나라에서 기념식, 전시회, 캠페인이 열린다.","개인의 작은 실천이 모여 큰 변화를 만들 수 있다."],"title":"세계 물의 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L08_basic#4','sci',4,1,'u2','L08','g4_1_sci_u2_L08_basic','lesson_basic','SC4-1-u2-C41',1,'sa','auto','물의 소중함을 알리려고 국제 연합이 정한 날의 이름을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u2-C41","difficulty":1,"kind":"sa","stem":"물의 소중함을 알리려고 국제 연합이 정한 날의 이름을 쓰세요.","answer":["세계 물의 날","세계물의날"],"explanation":["오늘 배운 날이에요.","「세계 ○의 날」이에요.","세계 물의 날이에요."],"mis":"SC4-1-u2-X47"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L08_basic#5','sci',4,1,'u2','L08','g4_1_sci_u2_L08_basic','lesson_basic','SC4-1-u2-C41',2,'mc','auto','국제 연합이 세계 물의 날을 정한 까닭은 무엇인가요?',ARRAY['SC4-1-u2-X47','SC4-1-u2-X40']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C41","difficulty":2,"kind":"mc","stem":"국제 연합이 세계 물의 날을 정한 까닭은 무엇인가요?","options":[{"t":"물의 소중함을 되새기고 물의 중요성을 알리려고","correct":true},{"t":"물을 마음껏 쓰는 날을 정하려고","mis":"SC4-1-u2-X47"},{"t":"물놀이 대회를 열려고","mis":"SC4-1-u2-X47"},{"t":"물이 넉넉하다는 것을 알리려고","mis":"SC4-1-u2-X40"}],"explanation":["물이 소중해요.","알리려고요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
