INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L08_challenge#1','sci',4,1,'u2','L08','g4_1_sci_u2_L08_challenge','lesson_challenge','SC4-1-u2-C44',2,'blank','auto','「개인의 작은 (      )이 모여 큰 변화를 만들 수 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u2-X49','SC4-1-u2-X48']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C44","difficulty":2,"kind":"blank","stem":"「개인의 작은 (      )이 모여 큰 변화를 만들 수 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"실천","correct":true},{"t":"걱정","mis":"SC4-1-u2-X49"},{"t":"낭비","mis":"SC4-1-u2-X48"},{"t":"물장난","mis":"SC4-1-u2-X48"}],"explanation":["넷째 줄을 읽어요.","직접 하는 거예요.","실천이에요."],"asset":{"type":"passage","lines":["지구 표면의 대부분은 물로 덮여 있지만 쓸 수 있는 물은 매우 적다.","국제 연합은 매년 3월 22일을 세계 물의 날로 정했다.","이날 여러 나라에서 기념식, 전시회, 캠페인이 열린다.","개인의 작은 실천이 모여 큰 변화를 만들 수 있다."],"title":"세계 물의 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L08_challenge#2','sci',4,1,'u2','L08','g4_1_sci_u2_L08_challenge','lesson_challenge','SC4-1-u2-C41',2,'mc','auto','세계 물의 날에 여러 나라에서 하는 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X47']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C41","difficulty":2,"kind":"mc","stem":"세계 물의 날에 여러 나라에서 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"물과 관련된 기념식, 전시회, 캠페인을 연다","correct":true},{"t":"물을 마음껏 쓰는 축제를 연다","mis":"SC4-1-u2-X47"},{"t":"하루 내내 물을 한 방울도 쓰지 않는다","mis":"SC4-1-u2-X47"},{"t":"물놀이 시합만 한다","mis":"SC4-1-u2-X47"}],"explanation":["셋째 줄을 읽어요.","알리는 행사예요.","첫 번째예요."],"asset":{"type":"passage","lines":["지구 표면의 대부분은 물로 덮여 있지만 쓸 수 있는 물은 매우 적다.","국제 연합은 매년 3월 22일을 세계 물의 날로 정했다.","이날 여러 나라에서 기념식, 전시회, 캠페인이 열린다.","개인의 작은 실천이 모여 큰 변화를 만들 수 있다."],"title":"세계 물의 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L08_challenge#3','sci',4,1,'u2','L08','g4_1_sci_u2_L08_challenge','lesson_challenge','SC4-1-u2-C43',3,'mc','auto','물을 마실 때 물을 아끼는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X48']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C43","difficulty":3,"kind":"mc","stem":"물을 마실 때 물을 아끼는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"마실 만큼만 컵에 따라 마신다","correct":true},{"t":"컵에 가득 따르고 남은 물은 버린다","mis":"SC4-1-u2-X48"},{"t":"마실 때마다 새 컵을 꺼내 물로 헹군다","mis":"SC4-1-u2-X48"},{"t":"수도꼭지를 틀어 놓고 손으로 받아 마신다","mis":"SC4-1-u2-X48"}],"explanation":["남기지 않아요.","마실 만큼만요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L08_challenge#4','sci',4,1,'u2','L08','g4_1_sci_u2_L08_challenge','lesson_challenge','SC4-1-u2-C44',3,'error','auto','세계 물의 날을 알아보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u2-X49','SC4-1-u2-X48']::text[],false,'{"seq":4,"concept":"SC4-1-u2-C44","difficulty":3,"kind":"error","stem":"세계 물의 날을 알아보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「물이 정말 모자라게 되면 그때부터 아끼면 돼.」","correct":true,"mis_target":"SC4-1-u2-X49"},{"t":"친구 가 — 「나부터 양치 컵을 쓸게.」","mis":"SC4-1-u2-X48"},{"t":"친구 나 — 「작은 실천이 모이면 큰 변화가 돼.」","mis":"SC4-1-u2-X49"}],"explanation":["언제부터 할까요?","지금부터예요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L08_challenge#5','sci',4,1,'u2','L08','g4_1_sci_u2_L08_challenge','lesson_challenge','SC4-1-u2-C45',3,'ox','auto','푸른 하늘의 날은 우리나라가 제안해 정해진 날이에요.',ARRAY['SC4-1-u2-X50']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C45","difficulty":3,"kind":"ox","stem":"푸른 하늘의 날은 우리나라가 제안해 정해진 날이에요.","answer":"O","reason_options":[{"t":"맑은 공기를 지키자는 뜻으로 우리나라가 제안했기 때문에","correct":true},{"t":"물의 소중함을 알리려고 정한 날이기 때문에","mis":"SC4-1-u2-X50"}],"mis":"SC4-1-u2-X50","explanation":["9월 7일이에요.","하늘과 공기의 날이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L08_challenge#6','sci',4,1,'u2','L08','g4_1_sci_u2_L08_challenge','lesson_challenge','SC4-1-u2-C45',3,'mc','auto','기념일과 그 뜻을 바르게 짝 지은 것은 무엇인가요?',ARRAY['SC4-1-u2-X50']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C45","difficulty":3,"kind":"mc","stem":"기념일과 그 뜻을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"지구의 날 — 지구의 환경을 보호하자는 뜻","correct":true},{"t":"세계 물의 날 — 하늘의 공기를 깨끗하게 하자는 뜻","mis":"SC4-1-u2-X50"},{"t":"푸른 하늘의 날 — 물의 소중함을 알리자는 뜻","mis":"SC4-1-u2-X50"},{"t":"세계 환경의 날 — 물을 마음껏 쓰자는 뜻","mis":"SC4-1-u2-X50"}],"explanation":["이름을 봐요.","지구를 보호해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L08_challenge#7','sci',4,1,'u2','L08','g4_1_sci_u2_L08_challenge','lesson_challenge','SC4-1-u2-C42',3,'mc','auto','「세계 물의 날」을 읽고 알 수 있는 것은 무엇인가요?',ARRAY['SC4-1-u2-X40','SC4-1-u2-X47','SC4-1-u2-X49']::text[],false,'{"seq":7,"concept":"SC4-1-u2-C42","difficulty":3,"kind":"mc","stem":"「세계 물의 날」을 읽고 알 수 있는 것은 무엇인가요?","options":[{"t":"지구에 물은 많지만 우리가 쓸 수 있는 물은 매우 적다","correct":true},{"t":"지구에 물이 많으니 아끼지 않아도 된다","mis":"SC4-1-u2-X40"},{"t":"세계 물의 날은 물놀이를 하는 날이다","mis":"SC4-1-u2-X47"},{"t":"물 절약은 큰 나라만 하면 된다","mis":"SC4-1-u2-X49"}],"explanation":["첫 줄을 읽어요.","쓸 수 있는 물은 적어요.","첫 번째예요."],"asset":{"type":"passage","lines":["지구 표면의 대부분은 물로 덮여 있지만 쓸 수 있는 물은 매우 적다.","국제 연합은 매년 3월 22일을 세계 물의 날로 정했다.","이날 여러 나라에서 기념식, 전시회, 캠페인이 열린다.","개인의 작은 실천이 모여 큰 변화를 만들 수 있다."],"title":"세계 물의 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L08_challenge#8','sci',4,1,'u2','L08','g4_1_sci_u2_L08_challenge','lesson_challenge','SC4-1-u2-C43',4,'mc','auto','물을 아끼는 행동끼리 바르게 모은 것은 무엇인가요? ㉠ 비누칠할 때 물 잠그기 ㉡ 양치할 때 물 틀어 두기 ㉢ 마실 만큼만 따르기 ㉣ 쓴 뒤 수도꼭지 꼭 잠그기',ARRAY['SC4-1-u2-X48']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C43","difficulty":4,"kind":"mc","stem":"물을 아끼는 행동끼리 바르게 모은 것은 무엇인가요? ㉠ 비누칠할 때 물 잠그기 ㉡ 양치할 때 물 틀어 두기 ㉢ 마실 만큼만 따르기 ㉣ 쓴 뒤 수도꼭지 꼭 잠그기","options":[{"t":"㉠, ㉢, ㉣","correct":true},{"t":"㉠, ㉡, ㉢","mis":"SC4-1-u2-X48"},{"t":"㉡, ㉣","mis":"SC4-1-u2-X48"},{"t":"㉡만","mis":"SC4-1-u2-X48"}],"explanation":["낭비하는 것을 빼요.","㉡은 낭비예요.","㉠, ㉢, ㉣이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L08_challenge#9','sci',4,1,'u2','L08','g4_1_sci_u2_L08_challenge','lesson_challenge','SC4-1-u2-C44',4,'mc','auto','친구가 「나 하나 물을 아낀다고 달라지는 건 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X49','SC4-1-u2-X40']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C44","difficulty":4,"kind":"mc","stem":"친구가 「나 하나 물을 아낀다고 달라지는 건 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「한 사람 한 사람의 작은 실천이 모이면 큰 변화가 될 수 있어.」","correct":true},{"t":"「맞아, 나라에서 알아서 해 줄 거야.」","mis":"SC4-1-u2-X49"},{"t":"「지구에 물이 많으니 괜찮아.」","mis":"SC4-1-u2-X40"},{"t":"「어른들만 아끼면 충분해.」","mis":"SC4-1-u2-X49"}],"explanation":["모두 모이면요.","큰 변화예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_L08_challenge#10','sci',4,1,'u2','L08','g4_1_sci_u2_L08_challenge','lesson_challenge','SC4-1-u2-C43',4,'essay','teacher','세계 물의 날을 정한 까닭을 쓰고, 내가 집이나 학교에서 실천할 수 있는 물 절약 방법 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u2-C43","difficulty":4,"kind":"essay","stem":"세계 물의 날을 정한 까닭을 쓰고, 내가 집이나 학교에서 실천할 수 있는 물 절약 방법 두 가지를 쓰세요.","answer_guide":{"answer":"예: 세계 물의 날은 물의 소중함을 되새기고 물의 중요성을 알리려고 정했다. 나는 양치할 때 컵에 물을 받아 쓰고, 손을 씻을 때 비누칠하는 동안 수도꼭지를 잠그겠다.","scoring_points":["정한 까닭을 썼는가","실천할 수 있는 방법 두 가지를 썼는가","내가 할 일로 구체적으로 썼는가"]},"explanation":["까닭을 떠올려요.","내가 할 일을 골라요.","두 가지를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#1','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C1',1,'mc','auto','은하반 일지 ①의 얼음 조각은 물의 어떤 상태인가요?',ARRAY['SC4-1-u2-X04','SC4-1-u2-X01']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C1","difficulty":1,"kind":"mc","stem":"은하반 일지 ①의 얼음 조각은 물의 어떤 상태인가요?","options":[{"t":"고체","correct":true},{"t":"액체","mis":"SC4-1-u2-X04"},{"t":"기체","mis":"SC4-1-u2-X04"},{"t":"물이 아니다","mis":"SC4-1-u2-X01"}],"explanation":["둘째 줄을 읽어요.","단단해요.","고체예요."],"asset":{"type":"passage","lines":["수족관 물, 얼음 조각, 끓는 냄비 주변을 살펴보았다.","얼음 조각은 단단해서 손으로 잡을 수 있었다.","냄비 주변의 물은 눈에 보이지 않았다.","친구 가 — 「눈에 안 보이니 냄비 주변엔 물이 없어.」"],"title":"은하반 일지 ① 물 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#2','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C7',1,'mc','auto','은하반 일지 ②에서 접시의 얼음은 어떤 상태 변화를 했나요?',ARRAY['SC4-1-u2-X06','SC4-1-u2-X09']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C7","difficulty":1,"kind":"mc","stem":"은하반 일지 ②에서 접시의 얼음은 어떤 상태 변화를 했나요?","options":[{"t":"고체에서 액체로","correct":true},{"t":"액체에서 고체로","mis":"SC4-1-u2-X06"},{"t":"액체에서 기체로","mis":"SC4-1-u2-X06"},{"t":"상태가 변하지 않았다","mis":"SC4-1-u2-X09"}],"explanation":["첫 줄을 읽어요.","얼음이 물이 됐어요.","고체에서 액체로예요."],"asset":{"type":"passage","lines":["접시의 얼음이 점점 작아지고 물이 생겼다.","손에 칠한 물이 조금 뒤 보이지 않았다.","물을 둥근 컵에서 네모난 컵으로 옮겨 담았다.","친구 나 — 「옮겨 담았으니 물의 상태가 변했어.」"],"title":"은하반 일지 ② 얼음과 물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#3','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C11',1,'mc','auto','은하반 일지 ③에서 고드름이 녹은 것은 어떤 상태 변화인가요?',ARRAY['SC4-1-u2-X14','SC4-1-u2-X16','SC4-1-u2-X15']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C11","difficulty":1,"kind":"mc","stem":"은하반 일지 ③에서 고드름이 녹은 것은 어떤 상태 변화인가요?","options":[{"t":"고체에서 액체로","correct":true},{"t":"액체에서 고체로","mis":"SC4-1-u2-X14"},{"t":"기체에서 액체로","mis":"SC4-1-u2-X16"},{"t":"액체에서 기체로","mis":"SC4-1-u2-X15"}],"explanation":["첫 줄을 읽어요.","얼음이 물이 됐어요.","고체에서 액체로예요."],"asset":{"type":"passage","lines":["고드름이 녹아 물이 똑똑 떨어졌다.","아침에 풀잎에 이슬이 맺혔다.","젖은 빨래가 오후에 다 말랐다.","친구 다 — 「상태 변화는 실험실에서만 볼 수 있어.」"],"title":"은하반 일지 ③ 생활 속 상태 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#4','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C16',1,'mc','auto','은하반 일지 ④에서 물이 얼었을 때 높이는 어떻게 되었나요?',ARRAY['SC4-1-u2-X20','SC4-1-u2-X26']::text[],false,'{"seq":4,"concept":"SC4-1-u2-C16","difficulty":1,"kind":"mc","stem":"은하반 일지 ④에서 물이 얼었을 때 높이는 어떻게 되었나요?","options":[{"t":"표시보다 높아졌다","correct":true},{"t":"표시보다 낮아졌다","mis":"SC4-1-u2-X20"},{"t":"표시와 같았다","mis":"SC4-1-u2-X20"},{"t":"높이를 견줄 수 없었다","mis":"SC4-1-u2-X26"}],"explanation":["둘째 줄을 읽어요.","높아졌어요.","첫 번째예요."],"asset":{"type":"passage","lines":["시험관 물의 높이를 표시하고 무게를 쟀다.","물이 얼자 높이가 표시보다 높아졌고 무게는 같았다.","얼음이 녹자 높이가 다시 낮아졌고 무게는 같았다.","친구 가 — 「얼음이 되어 높아졌으니 무거워졌어.」"],"title":"은하반 일지 ④ 얼리고 녹이기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#5','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C25',1,'mc','auto','은하반 일지 ⑤의 두 비커에서 물이 줄어든 까닭은 무엇인가요?',ARRAY['SC4-1-u2-X08','SC4-1-u2-X30','SC4-1-u2-X28']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C25","difficulty":1,"kind":"mc","stem":"은하반 일지 ⑤의 두 비커에서 물이 줄어든 까닭은 무엇인가요?","options":[{"t":"물이 수증기로 변해 공기 중으로 날아갔기 때문에","correct":true},{"t":"물이 아주 사라졌기 때문에","mis":"SC4-1-u2-X08"},{"t":"물이 얼음이 되었기 때문에","mis":"SC4-1-u2-X30"},{"t":"비커에서 물이 새었기 때문에","mis":"SC4-1-u2-X28"}],"explanation":["셋째 줄을 읽어요.","둘 다 수증기가 됐어요.","첫 번째예요."],"asset":{"type":"passage","lines":["햇빛에 둔 비커의 물이 며칠 동안 조금씩 줄었다.","가열한 비커에서 기포가 계속 생기며 물이 줄었다.","두 비커 모두 처음 높이보다 낮아졌다.","친구 나 — 「줄어든 물은 아주 사라졌어.」"],"title":"은하반 일지 ⑤ 줄어든 물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#6','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C30',1,'mc','auto','은하반 일지 ⑥에서 컵 바깥에 맺힌 물방울은 어디에서 왔나요?',ARRAY['SC4-1-u2-X34']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C30","difficulty":1,"kind":"mc","stem":"은하반 일지 ⑥에서 컵 바깥에 맺힌 물방울은 어디에서 왔나요?","options":[{"t":"공기 중의 수증기","correct":true},{"t":"컵 속의 포도 주스","mis":"SC4-1-u2-X34"},{"t":"컵 속의 얼음","mis":"SC4-1-u2-X34"},{"t":"물방울을 닦은 휴지","mis":"SC4-1-u2-X34"}],"explanation":["보라색이 없었어요.","공기 중에서 와요.","수증기예요."],"asset":{"type":"passage","lines":["얼음과 포도 주스를 넣은 컵 바깥에 물방울이 맺혔다.","물방울을 닦은 휴지는 젖었지만 보라색이 없었다.","주스만 넣은 컵에는 물방울이 맺히지 않았다.","친구 다 — 「컵 속 주스가 새어 나온 거야.」"],"title":"은하반 일지 ⑥ 컵 바깥 물방울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#7','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C38',1,'mc','auto','은하반 일지 ⑦에서 작은 그릇에 맑은 물이 모인 까닭은 무엇인가요?',ARRAY['SC4-1-u2-X43','SC4-1-u2-X41']::text[],false,'{"seq":7,"concept":"SC4-1-u2-C38","difficulty":1,"kind":"mc","stem":"은하반 일지 ⑦에서 작은 그릇에 맑은 물이 모인 까닭은 무엇인가요?","options":[{"t":"흙은 남고 물만 증발했다가 비닐에서 응결해 떨어졌기 때문에","correct":true},{"t":"흙탕물이 그대로 작은 그릇으로 넘쳤기 때문에","mis":"SC4-1-u2-X43"},{"t":"비닐이 녹아 물이 되었기 때문에","mis":"SC4-1-u2-X41"},{"t":"자갈에서 물이 나왔기 때문에","mis":"SC4-1-u2-X41"}],"explanation":["무엇이 증발하나요?","물만이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["큰 그릇에 흙탕물을 넣고 가운데에 빈 작은 그릇을 두었다.","비닐을 덮고 가운데에 자갈을 올렸다.","3일 뒤 작은 그릇에 맑은 물이 모였다.","친구 가 — 「지구에 물이 많으니 이런 장치는 필요 없어.」"],"title":"은하반 일지 ⑦ 물을 얻는 장치"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#8','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C41',1,'mc','auto','은하반 일지 ⑧에 나온 세계 물의 날은 언제인가요?',ARRAY['SC4-1-u2-X50']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C41","difficulty":1,"kind":"mc","stem":"은하반 일지 ⑧에 나온 세계 물의 날은 언제인가요?","options":[{"t":"3월 22일","correct":true},{"t":"4월 22일","mis":"SC4-1-u2-X50"},{"t":"6월 5일","mis":"SC4-1-u2-X50"},{"t":"9월 7일","mis":"SC4-1-u2-X50"}],"explanation":["첫 줄을 읽어요.","3월이에요.","3월 22일이에요."],"asset":{"type":"passage","lines":["3월 22일 세계 물의 날 포스터를 만들었다.","양치 컵 쓰기, 비누칠할 때 물 잠그기를 적었다.","마실 만큼만 따르기도 적었다.","친구 나 — 「물 아끼기는 어른들이 하면 돼.」"],"title":"은하반 일지 ⑧ 세계 물의 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#9','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C1',2,'mc','auto','고체 상태의 물끼리 묶은 것은 무엇인가요?',ARRAY['SC4-1-u2-X04']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C1","difficulty":2,"kind":"mc","stem":"고체 상태의 물끼리 묶은 것은 무엇인가요?","options":[{"t":"얼음 틀의 얼음, 스케이트장의 얼음","correct":true},{"t":"설거지 물, 얼음 틀의 얼음","mis":"SC4-1-u2-X04"},{"t":"어항 물, 땀","mis":"SC4-1-u2-X04"},{"t":"공기 중의 보이지 않는 물, 얼음 틀의 얼음","mis":"SC4-1-u2-X04"}],"explanation":["단단한 것을 찾아요.","둘 다 얼음이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#10','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C6',2,'mc','auto','얼음의 특징으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X07','SC4-1-u2-X06']::text[],false,'{"seq":10,"concept":"SC4-1-u2-C6","difficulty":2,"kind":"mc","stem":"얼음의 특징으로 알맞은 것은 무엇인가요?","options":[{"t":"차갑고 단단하며 모양이 일정하다","correct":true},{"t":"흘러서 그릇 모양대로 바뀐다","mis":"SC4-1-u2-X07"},{"t":"눈에 보이지 않는다","mis":"SC4-1-u2-X06"},{"t":"손으로 잡을 수 없다","mis":"SC4-1-u2-X07"}],"explanation":["얼음을 만져 봐요.","단단해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
