INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#13','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C27',2,'mc','auto','우리 주변에서 증발을 이용하는 예는 무엇인가요?',ARRAY['SC4-1-u2-X32','SC4-1-u2-X37']::text[],false,'{"seq":13,"concept":"SC4-1-u2-C27","difficulty":2,"kind":"mc","stem":"우리 주변에서 증발을 이용하는 예는 무엇인가요?","options":[{"t":"젖은 머리를 머리 말리개로 말린다","correct":true},{"t":"만두를 찌려고 물을 끓인다","mis":"SC4-1-u2-X32"},{"t":"물을 얼려 얼음을 만든다","mis":"SC4-1-u2-X32"},{"t":"찬 컵에 물방울이 맺힌다","mis":"SC4-1-u2-X37"}],"explanation":["말리는 것을 찾아요.","머리를 말려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#14','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C32',2,'mc','auto','냉동실에서 꺼낸 물병 표면에 물방울이 맺히는 것과 같은 상태 변화는 무엇인가요?',ARRAY['SC4-1-u2-X37']::text[],false,'{"seq":14,"concept":"SC4-1-u2-C32","difficulty":2,"kind":"mc","stem":"냉동실에서 꺼낸 물병 표면에 물방울이 맺히는 것과 같은 상태 변화는 무엇인가요?","options":[{"t":"이른 아침 풀잎에 이슬이 맺힌다","correct":true},{"t":"운동장에 고인 물이 사라진다","mis":"SC4-1-u2-X37"},{"t":"얼음과자가 녹는다","mis":"SC4-1-u2-X37"},{"t":"주전자의 물이 끓는다","mis":"SC4-1-u2-X37"}],"explanation":["응결이에요.","수증기가 물이 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
