INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#17','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C4',3,'mc','auto','남극의 얼음, 바다의 물, 공기 중의 보이지 않는 물을 상태별로 차례대로 말한 것은 무엇인가요?',ARRAY['SC4-1-u2-X05','SC4-1-u2-X04','SC4-1-u2-X03']::text[],false,'{"seq":17,"concept":"SC4-1-u2-C4","difficulty":3,"kind":"mc","stem":"남극의 얼음, 바다의 물, 공기 중의 보이지 않는 물을 상태별로 차례대로 말한 것은 무엇인가요?","options":[{"t":"고체, 액체, 기체","correct":true},{"t":"액체, 고체, 기체","mis":"SC4-1-u2-X05"},{"t":"고체, 기체, 액체","mis":"SC4-1-u2-X04"},{"t":"고체, 액체, 물이 아님","mis":"SC4-1-u2-X03"}],"explanation":["얼음은 고체예요.","보이지 않는 물은 기체예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
