INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#21','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C32',3,'mc','auto','응결과 관계없는 것은 무엇인가요?',ARRAY['SC4-1-u2-X37']::text[],false,'{"seq":21,"concept":"SC4-1-u2-C32","difficulty":3,"kind":"mc","stem":"응결과 관계없는 것은 무엇인가요?","options":[{"t":"어항의 물이 조금씩 줄어든다","correct":true},{"t":"욕실 거울이 뿌옇게 흐려진다","mis":"SC4-1-u2-X37"},{"t":"안경이 뿌옇게 흐려진다","mis":"SC4-1-u2-X37"},{"t":"거미줄에 이슬이 맺힌다","mis":"SC4-1-u2-X37"}],"explanation":["방향을 따져요.","어항은 증발이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#22','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C38',3,'mc','auto','물을 얻는 장치에서 비닐 안쪽에 물방울이 맺히는 것은 어떤 상태 변화인가요?',ARRAY['SC4-1-u2-X36','SC4-1-u2-X41']::text[],false,'{"seq":22,"concept":"SC4-1-u2-C38","difficulty":3,"kind":"mc","stem":"물을 얻는 장치에서 비닐 안쪽에 물방울이 맺히는 것은 어떤 상태 변화인가요?","options":[{"t":"응결","correct":true},{"t":"증발","mis":"SC4-1-u2-X36"},{"t":"녹음","mis":"SC4-1-u2-X41"},{"t":"끓음","mis":"SC4-1-u2-X41"}],"explanation":["수증기가 물이 돼요.","비닐에 맺혀요.","응결이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#23','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C3',4,'mc','auto','친구가 「공기 중에는 물이 없어. 아무것도 안 보이잖아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X03','SC4-1-u2-X04','SC4-1-u2-X02']::text[],false,'{"seq":23,"concept":"SC4-1-u2-C3","difficulty":4,"kind":"mc","stem":"친구가 「공기 중에는 물이 없어. 아무것도 안 보이잖아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「공기 중에는 눈에 보이지 않는 기체 상태의 물, 수증기가 있어.」","correct":true},{"t":"「맞아, 보이지 않으면 없는 거야.」","mis":"SC4-1-u2-X03"},{"t":"「공기 중의 물은 고체야.」","mis":"SC4-1-u2-X04"},{"t":"「물은 액체로만 있어.」","mis":"SC4-1-u2-X02"}],"explanation":["수증기를 떠올려요.","보이지 않아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#24','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C9',4,'mc','auto','친구가 「얼음이 녹는 것과 물이 어는 것은 서로 상관없는 변화야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X11','SC4-1-u2-X14','SC4-1-u2-X10']::text[],false,'{"seq":24,"concept":"SC4-1-u2-C9","difficulty":4,"kind":"mc","stem":"친구가 「얼음이 녹는 것과 물이 어는 것은 서로 상관없는 변화야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「둘은 얼음과 물 사이에서 서로 반대 방향으로 일어나는 상태 변화야.」","correct":true},{"t":"「맞아, 녹은 물은 다시 얼 수 없어.」","mis":"SC4-1-u2-X11"},{"t":"「둘 다 액체와 기체 사이의 변화야.」","mis":"SC4-1-u2-X14"},{"t":"「둘 다 상태 변화가 아니야.」","mis":"SC4-1-u2-X10"}],"explanation":["얼음과 물 사이예요.","반대 방향이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_a#25','sci',4,1,'u2','','g4_1_sci_u2_review_a','unit_review','SC4-1-u2-C13',4,'essay','teacher','은하반 일지 ③을 보고 고드름, 이슬, 빨래에서 일어난 상태 변화를 각각 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-1-u2-C13","difficulty":4,"kind":"essay","stem":"은하반 일지 ③을 보고 고드름, 이슬, 빨래에서 일어난 상태 변화를 각각 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 고드름이 녹은 것은 고체에서 액체로, 이슬이 맺힌 것은 기체인 수증기가 액체인 물로, 빨래가 마른 것은 액체에서 기체로 변한 것이다. 물의 상태 변화는 실험실에서만이 아니라 우리 주변 곳곳에서 볼 수 있다.","scoring_points":["세 가지 상태 변화를 바르게 썼는가","이슬이 공기 중 수증기에서 왔음을 썼는가","친구 다의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","하나씩 따져요.","고쳐 써요."],"asset":{"type":"passage","lines":["고드름이 녹아 물이 똑똑 떨어졌다.","아침에 풀잎에 이슬이 맺혔다.","젖은 빨래가 오후에 다 말랐다.","친구 다 — 「상태 변화는 실험실에서만 볼 수 있어.」"],"title":"은하반 일지 ③ 생활 속 상태 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#1','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C3',1,'ox','auto','은하반 일지 ① 친구 가의 말처럼 냄비 주변에는 물이 없어요.',ARRAY['SC4-1-u2-X03']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C3","difficulty":1,"kind":"ox","stem":"은하반 일지 ① 친구 가의 말처럼 냄비 주변에는 물이 없어요.","answer":"X","reason_options":[{"t":"기체 상태의 물은 눈에 보이지 않을 뿐 주변에 있기 때문에","correct":true},{"t":"눈에 보이지 않는 것은 없는 것이기 때문에","mis":"SC4-1-u2-X03"}],"mis":"SC4-1-u2-X03","explanation":["보이지 않는 물을 떠올려요.","기체 상태예요.","그래서 X예요."],"asset":{"type":"passage","lines":["수족관 물, 얼음 조각, 끓는 냄비 주변을 살펴보았다.","얼음 조각은 단단해서 손으로 잡을 수 있었다.","냄비 주변의 물은 눈에 보이지 않았다.","친구 가 — 「눈에 안 보이니 냄비 주변엔 물이 없어.」"],"title":"은하반 일지 ① 물 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#2','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C9',1,'ox','auto','은하반 일지 ② 친구 나의 말처럼 물을 다른 컵에 옮겨 담으면 상태가 변해요.',ARRAY['SC4-1-u2-X10']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C9","difficulty":1,"kind":"ox","stem":"은하반 일지 ② 친구 나의 말처럼 물을 다른 컵에 옮겨 담으면 상태가 변해요.","answer":"X","reason_options":[{"t":"모양만 바뀌었을 뿐 액체 상태 그대로이기 때문에","correct":true},{"t":"담는 그릇이 바뀌면 상태도 바뀌기 때문에","mis":"SC4-1-u2-X10"}],"mis":"SC4-1-u2-X10","explanation":["셋째 줄을 읽어요.","여전히 물이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["접시의 얼음이 점점 작아지고 물이 생겼다.","손에 칠한 물이 조금 뒤 보이지 않았다.","물을 둥근 컵에서 네모난 컵으로 옮겨 담았다.","친구 나 — 「옮겨 담았으니 물의 상태가 변했어.」"],"title":"은하반 일지 ② 얼음과 물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#3','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C12',1,'ox','auto','은하반 일지 ③ 친구 다의 말처럼 물의 상태 변화는 실험실에서만 볼 수 있어요.',ARRAY['SC4-1-u2-X17']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C12","difficulty":1,"kind":"ox","stem":"은하반 일지 ③ 친구 다의 말처럼 물의 상태 변화는 실험실에서만 볼 수 있어요.","answer":"X","reason_options":[{"t":"고드름·이슬·빨래처럼 우리 주변 곳곳에서 볼 수 있기 때문에","correct":true},{"t":"물의 상태 변화는 실험 기구가 있어야만 일어나기 때문에","mis":"SC4-1-u2-X17"}],"mis":"SC4-1-u2-X17","explanation":["일지를 읽어요.","모두 생활 속이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["고드름이 녹아 물이 똑똑 떨어졌다.","아침에 풀잎에 이슬이 맺혔다.","젖은 빨래가 오후에 다 말랐다.","친구 다 — 「상태 변화는 실험실에서만 볼 수 있어.」"],"title":"은하반 일지 ③ 생활 속 상태 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#4','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C17',1,'ox','auto','은하반 일지 ④ 친구 가의 말처럼 물이 얼어 높아졌으니 무거워졌어요.',ARRAY['SC4-1-u2-X21']::text[],false,'{"seq":4,"concept":"SC4-1-u2-C17","difficulty":1,"kind":"ox","stem":"은하반 일지 ④ 친구 가의 말처럼 물이 얼어 높아졌으니 무거워졌어요.","answer":"X","reason_options":[{"t":"물이 얼어도 무게는 같았기 때문에","correct":true},{"t":"부피가 늘어나면 무게도 늘어나기 때문에","mis":"SC4-1-u2-X21"}],"mis":"SC4-1-u2-X21","explanation":["둘째 줄의 무게를 봐요.","같았어요.","그래서 X예요."],"asset":{"type":"passage","lines":["시험관 물의 높이를 표시하고 무게를 쟀다.","물이 얼자 높이가 표시보다 높아졌고 무게는 같았다.","얼음이 녹자 높이가 다시 낮아졌고 무게는 같았다.","친구 가 — 「얼음이 되어 높아졌으니 무거워졌어.」"],"title":"은하반 일지 ④ 얼리고 녹이기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#5','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C26',1,'ox','auto','은하반 일지 ⑤ 친구 나의 말처럼 줄어든 물은 아주 사라졌어요.',ARRAY['SC4-1-u2-X08']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C26","difficulty":1,"kind":"ox","stem":"은하반 일지 ⑤ 친구 나의 말처럼 줄어든 물은 아주 사라졌어요.","answer":"X","reason_options":[{"t":"수증기가 되어 눈에 보이지 않을 뿐 주위에 있기 때문에","correct":true},{"t":"눈에 보이지 않는 물은 없는 것이기 때문에","mis":"SC4-1-u2-X08"}],"mis":"SC4-1-u2-X08","explanation":["수증기를 떠올려요.","보이지 않을 뿐이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["햇빛에 둔 비커의 물이 며칠 동안 조금씩 줄었다.","가열한 비커에서 기포가 계속 생기며 물이 줄었다.","두 비커 모두 처음 높이보다 낮아졌다.","친구 나 — 「줄어든 물은 아주 사라졌어.」"],"title":"은하반 일지 ⑤ 줄어든 물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#6','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C30',1,'ox','auto','은하반 일지 ⑥ 친구 다의 말처럼 컵 속 주스가 새어 나온 거예요.',ARRAY['SC4-1-u2-X34']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C30","difficulty":1,"kind":"ox","stem":"은하반 일지 ⑥ 친구 다의 말처럼 컵 속 주스가 새어 나온 거예요.","answer":"X","reason_options":[{"t":"물방울을 닦은 휴지에 보라색이 없었기 때문에","correct":true},{"t":"물방울은 컵 속에서만 나올 수 있기 때문에","mis":"SC4-1-u2-X34"}],"mis":"SC4-1-u2-X34","explanation":["둘째 줄을 읽어요.","주스 색이 없어요.","그래서 X예요."],"asset":{"type":"passage","lines":["얼음과 포도 주스를 넣은 컵 바깥에 물방울이 맺혔다.","물방울을 닦은 휴지는 젖었지만 보라색이 없었다.","주스만 넣은 컵에는 물방울이 맺히지 않았다.","친구 다 — 「컵 속 주스가 새어 나온 거야.」"],"title":"은하반 일지 ⑥ 컵 바깥 물방울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#7','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C40',1,'ox','auto','은하반 일지 ⑦ 친구 가의 말처럼 지구에 물이 많으니 물을 얻는 장치는 필요 없어요.',ARRAY['SC4-1-u2-X40']::text[],false,'{"seq":7,"concept":"SC4-1-u2-C40","difficulty":1,"kind":"ox","stem":"은하반 일지 ⑦ 친구 가의 말처럼 지구에 물이 많으니 물을 얻는 장치는 필요 없어요.","answer":"X","reason_options":[{"t":"쓸 수 있는 깨끗한 물은 점점 줄어들고 있기 때문에","correct":true},{"t":"지구에 물이 많으면 모두 쓸 수 있기 때문에","mis":"SC4-1-u2-X40"}],"mis":"SC4-1-u2-X40","explanation":["쓸 수 있는 물을 떠올려요.","점점 줄어요.","그래서 X예요."],"asset":{"type":"passage","lines":["큰 그릇에 흙탕물을 넣고 가운데에 빈 작은 그릇을 두었다.","비닐을 덮고 가운데에 자갈을 올렸다.","3일 뒤 작은 그릇에 맑은 물이 모였다.","친구 가 — 「지구에 물이 많으니 이런 장치는 필요 없어.」"],"title":"은하반 일지 ⑦ 물을 얻는 장치"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#8','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C44',1,'ox','auto','은하반 일지 ⑧ 친구 나의 말처럼 물 아끼기는 어른들이 하면 돼요.',ARRAY['SC4-1-u2-X49']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C44","difficulty":1,"kind":"ox","stem":"은하반 일지 ⑧ 친구 나의 말처럼 물 아끼기는 어른들이 하면 돼요.","answer":"X","reason_options":[{"t":"나를 포함한 모두의 작은 실천이 모여 큰 변화를 만들기 때문에","correct":true},{"t":"어린이가 아끼는 물은 아무 도움이 되지 않기 때문에","mis":"SC4-1-u2-X49"}],"mis":"SC4-1-u2-X49","explanation":["작은 실천을 떠올려요.","나도 해요.","그래서 X예요."],"asset":{"type":"passage","lines":["3월 22일 세계 물의 날 포스터를 만들었다.","양치 컵 쓰기, 비누칠할 때 물 잠그기를 적었다.","마실 만큼만 따르기도 적었다.","친구 나 — 「물 아끼기는 어른들이 하면 돼.」"],"title":"은하반 일지 ⑧ 세계 물의 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#9','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C3',2,'mc','auto','눈에 보이지 않는 물에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X03','SC4-1-u2-X04']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C3","difficulty":2,"kind":"mc","stem":"눈에 보이지 않는 물에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"기체 상태로 공기 중에 있다","correct":true},{"t":"보이지 않으니 물이 아니다","mis":"SC4-1-u2-X03"},{"t":"손으로 잡을 수 있는 고체다","mis":"SC4-1-u2-X04"},{"t":"흘러서 그릇 모양이 된다","mis":"SC4-1-u2-X04"}],"explanation":["기체를 떠올려요.","공기 중에 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#10','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C9',2,'mc','auto','물의 상태 변화를 바르게 설명한 것은 무엇인가요?',ARRAY['SC4-1-u2-X10','SC4-1-u2-X11']::text[],false,'{"seq":10,"concept":"SC4-1-u2-C9","difficulty":2,"kind":"mc","stem":"물의 상태 변화를 바르게 설명한 것은 무엇인가요?","options":[{"t":"물이 얼음, 물, 수증기처럼 서로 다른 상태로 변하는 것","correct":true},{"t":"물을 다른 그릇에 옮겨 담는 것","mis":"SC4-1-u2-X10"},{"t":"물이 한 번 변하면 되돌아갈 수 없는 것","mis":"SC4-1-u2-X11"},{"t":"물의 색깔이 바뀌는 것","mis":"SC4-1-u2-X10"}],"explanation":["상태가 바뀌어요.","얼음·물·수증기예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#11','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C13',2,'mc','auto','기체에서 액체로 변하는 생활 속 예는 무엇인가요?',ARRAY['SC4-1-u2-X15','SC4-1-u2-X14']::text[],false,'{"seq":11,"concept":"SC4-1-u2-C13","difficulty":2,"kind":"mc","stem":"기체에서 액체로 변하는 생활 속 예는 무엇인가요?","options":[{"t":"추운 겨울 유리창 안쪽에 물방울이 맺힌다","correct":true},{"t":"수채 물감 그림이 마른다","mis":"SC4-1-u2-X15"},{"t":"봄에 계곡 얼음이 녹는다","mis":"SC4-1-u2-X14"},{"t":"얼음 틀에 물을 넣어 얼린다","mis":"SC4-1-u2-X14"}],"explanation":["수증기가 물이 돼요.","물방울이 맺혀요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#12','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C21',2,'mc','auto','얼린 요구르트병을 꺼내 두었더니 병이 줄어들었어요. 그 까닭은 무엇인가요?',ARRAY['SC4-1-u2-X22','SC4-1-u2-X23','SC4-1-u2-X25']::text[],false,'{"seq":12,"concept":"SC4-1-u2-C21","difficulty":2,"kind":"mc","stem":"얼린 요구르트병을 꺼내 두었더니 병이 줄어들었어요. 그 까닭은 무엇인가요?","options":[{"t":"얼음이 녹아 물이 되면서 부피가 줄어들었기 때문에","correct":true},{"t":"얼음이 녹으면서 무게가 줄어들었기 때문에","mis":"SC4-1-u2-X22"},{"t":"얼음이 녹으면서 부피가 늘어났기 때문에","mis":"SC4-1-u2-X23"},{"t":"요구르트가 병 밖으로 새어 나갔기 때문에","mis":"SC4-1-u2-X25"}],"explanation":["녹으면 부피가 줄어요.","병도 줄어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#13','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C24',2,'mc','auto','끓음에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X31','SC4-1-u2-X36','SC4-1-u2-X30']::text[],false,'{"seq":13,"concept":"SC4-1-u2-C24","difficulty":2,"kind":"mc","stem":"끓음에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"물의 표면뿐 아니라 물속에서도 물이 수증기로 변하는 현상","correct":true},{"t":"물의 표면에서만 물이 수증기로 변하는 현상","mis":"SC4-1-u2-X31"},{"t":"수증기가 물로 변하는 현상","mis":"SC4-1-u2-X36"},{"t":"물이 얼음으로 변하는 현상","mis":"SC4-1-u2-X30"}],"explanation":["기포를 떠올려요.","물속에서도요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#14','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C31',2,'mc','auto','응결에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X36','SC4-1-u2-X10']::text[],false,'{"seq":14,"concept":"SC4-1-u2-C31","difficulty":2,"kind":"mc","stem":"응결에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"기체인 수증기가 액체인 물로 상태가 변하는 현상","correct":true},{"t":"액체인 물이 기체인 수증기로 변하는 현상","mis":"SC4-1-u2-X36"},{"t":"고체인 얼음이 액체인 물로 변하는 현상","mis":"SC4-1-u2-X36"},{"t":"물이 다른 그릇으로 옮겨지는 현상","mis":"SC4-1-u2-X10"}],"explanation":["수증기가 물이 돼요.","증발과 반대예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#15','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C39',2,'mc','auto','물을 얻는 장치의 설계도로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X45','SC4-1-u2-X42']::text[],false,'{"seq":15,"concept":"SC4-1-u2-C39","difficulty":2,"kind":"mc","stem":"물을 얻는 장치의 설계도로 가장 알맞은 것은 무엇인가요?","options":[{"t":"간단하고 다른 사람이 알아보기 쉽게 그린 설계도","correct":true},{"t":"비싼 재료만 쓴 설계도","mis":"SC4-1-u2-X45"},{"t":"색칠만 화려하고 상태 변화가 없는 설계도","mis":"SC4-1-u2-X45"},{"t":"물의 상태 변화와 상관없는 설계도","mis":"SC4-1-u2-X42"}],"explanation":["누가 봐도 알아야 해요.","간단하게요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#16','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C43',2,'mc','auto','물을 쓴 뒤 해야 할 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X48']::text[],false,'{"seq":16,"concept":"SC4-1-u2-C43","difficulty":2,"kind":"mc","stem":"물을 쓴 뒤 해야 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"수도꼭지를 꼭 잠근다","correct":true},{"t":"수도꼭지를 조금 열어 둔다","mis":"SC4-1-u2-X48"},{"t":"물장난을 한 번 더 한다","mis":"SC4-1-u2-X48"},{"t":"물이 흐르는 채로 자리를 뜬다","mis":"SC4-1-u2-X48"}],"explanation":["물이 새면 안 돼요.","잠가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#17','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C8',3,'mc','auto','더운 날 장갑 낀 손에 칠한 물이 금방 보이지 않게 되었어요. 가장 알맞은 설명은 무엇인가요?',ARRAY['SC4-1-u2-X08','SC4-1-u2-X06']::text[],false,'{"seq":17,"concept":"SC4-1-u2-C8","difficulty":3,"kind":"mc","stem":"더운 날 장갑 낀 손에 칠한 물이 금방 보이지 않게 되었어요. 가장 알맞은 설명은 무엇인가요?","options":[{"t":"물이 수증기로 변해 공기 중으로 갔다","correct":true},{"t":"물이 아주 없어졌다","mis":"SC4-1-u2-X08"},{"t":"물이 얼음이 되었다","mis":"SC4-1-u2-X06"},{"t":"장갑이 물을 만들어 냈다","mis":"SC4-1-u2-X08"}],"explanation":["보이지 않게 됐어요.","수증기예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#18','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C14',3,'mc','auto','봄에 계곡 얼음이 녹고, 그 물이 여름에 줄어드는 동안 일어난 상태 변화를 차례대로 쓴 것은 무엇인가요?',ARRAY['SC4-1-u2-X14','SC4-1-u2-X16']::text[],false,'{"seq":18,"concept":"SC4-1-u2-C14","difficulty":3,"kind":"mc","stem":"봄에 계곡 얼음이 녹고, 그 물이 여름에 줄어드는 동안 일어난 상태 변화를 차례대로 쓴 것은 무엇인가요?","options":[{"t":"고체 → 액체 → 기체","correct":true},{"t":"액체 → 고체 → 기체","mis":"SC4-1-u2-X14"},{"t":"고체 → 기체 → 액체","mis":"SC4-1-u2-X16"},{"t":"기체 → 액체 → 고체","mis":"SC4-1-u2-X16"}],"explanation":["얼음이 녹아요.","물이 줄어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#19','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C18',3,'ox','auto','시험관 속 얼음이 녹아 물이 되면 높이가 얼음일 때보다 낮아져요.',ARRAY['SC4-1-u2-X22']::text[],false,'{"seq":19,"concept":"SC4-1-u2-C18","difficulty":3,"kind":"ox","stem":"시험관 속 얼음이 녹아 물이 되면 높이가 얼음일 때보다 낮아져요.","answer":"O","reason_options":[{"t":"얼음이 녹아 물이 되면 부피가 줄어들기 때문에","correct":true},{"t":"얼음이 녹으면 무게가 줄어들기 때문에","mis":"SC4-1-u2-X22"}],"mis":"SC4-1-u2-X22","explanation":["녹으면 부피가 줄어요.","높이도 낮아져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#20','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C24',3,'ox','auto','물이 끓을 때에는 물 표면에서만 물이 수증기로 변해요.',ARRAY['SC4-1-u2-X29']::text[],false,'{"seq":20,"concept":"SC4-1-u2-C24","difficulty":3,"kind":"ox","stem":"물이 끓을 때에는 물 표면에서만 물이 수증기로 변해요.","answer":"X","reason_options":[{"t":"물속에서도 수증기로 변해 기포가 생기기 때문에","correct":true},{"t":"끓을 때 기포는 생기지 않기 때문에","mis":"SC4-1-u2-X29"}],"mis":"SC4-1-u2-X29","explanation":["기포를 떠올려요.","물속에서도요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#21','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C30',3,'ox','auto','얼음이 든 컵 바깥에 물방울이 맺히면 컵 전체의 무게는 처음보다 늘어나요.',ARRAY['SC4-1-u2-X34']::text[],false,'{"seq":21,"concept":"SC4-1-u2-C30","difficulty":3,"kind":"ox","stem":"얼음이 든 컵 바깥에 물방울이 맺히면 컵 전체의 무게는 처음보다 늘어나요.","answer":"O","reason_options":[{"t":"공기 중의 수증기가 응결한 물방울이 컵에 더해지기 때문에","correct":true},{"t":"컵 속 음료수가 새어 나와 늘어나기 때문에","mis":"SC4-1-u2-X34"}],"mis":"SC4-1-u2-X34","explanation":["밖에서 물이 더해져요.","무게가 늘어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#22','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C42',3,'ox','auto','기후 변화로 가뭄과 폭염이 심해지면 쓸 수 있는 물이 더 부족해져요.',ARRAY['SC4-1-u2-X46']::text[],false,'{"seq":22,"concept":"SC4-1-u2-C42","difficulty":3,"kind":"ox","stem":"기후 변화로 가뭄과 폭염이 심해지면 쓸 수 있는 물이 더 부족해져요.","answer":"O","reason_options":[{"t":"비가 적게 오고 물이 많이 필요해지기 때문에","correct":true},{"t":"기후 변화는 물과 아무 상관이 없기 때문에","mis":"SC4-1-u2-X46"}],"mis":"SC4-1-u2-X46","explanation":["가뭄을 떠올려요.","비가 안 와요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#23','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C19',4,'mc','auto','친구가 「얼음이 물보다 부피가 크니까 얼음 한 조각이 그 얼음이 녹은 물보다 무거워.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X24','SC4-1-u2-X23','SC4-1-u2-X22']::text[],false,'{"seq":23,"concept":"SC4-1-u2-C19","difficulty":4,"kind":"mc","stem":"친구가 「얼음이 물보다 부피가 크니까 얼음 한 조각이 그 얼음이 녹은 물보다 무거워.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「얼음이 녹아도 무게는 같아. 부피가 크다고 더 무거운 건 아니야.」","correct":true},{"t":"「맞아, 부피가 크면 언제나 무거워.」","mis":"SC4-1-u2-X24"},{"t":"「얼음이 녹으면 부피가 늘어나.」","mis":"SC4-1-u2-X23"},{"t":"「얼음이 녹으면 가벼워져.」","mis":"SC4-1-u2-X22"}],"explanation":["무게를 떠올려요.","같았어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#24','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C38',4,'mc','auto','바닷물을 넣은 장치로 얻은 물에 소금이 없다고 짐작할 수 있는 까닭은 무엇인가요?',ARRAY['SC4-1-u2-X43','SC4-1-u2-X41']::text[],false,'{"seq":24,"concept":"SC4-1-u2-C38","difficulty":4,"kind":"mc","stem":"바닷물을 넣은 장치로 얻은 물에 소금이 없다고 짐작할 수 있는 까닭은 무엇인가요?","options":[{"t":"물만 증발해 수증기가 되었다가 응결하고, 소금은 큰 그릇에 남기 때문에","correct":true},{"t":"소금도 함께 증발해 모이기 때문에","mis":"SC4-1-u2-X43"},{"t":"비닐이 소금을 녹여 없애기 때문에","mis":"SC4-1-u2-X41"},{"t":"바닷물에는 원래 소금이 없기 때문에","mis":"SC4-1-u2-X43"}],"explanation":["무엇이 증발하나요?","물만이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_b#25','sci',4,1,'u2','','g4_1_sci_u2_review_b','unit_review','SC4-1-u2-C17',4,'essay','teacher','은하반 일지 ④를 보고 물이 얼 때와 얼음이 녹을 때의 부피와 무게 변화를 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-1-u2-C17","difficulty":4,"kind":"essay","stem":"은하반 일지 ④를 보고 물이 얼 때와 얼음이 녹을 때의 부피와 무게 변화를 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 물이 얼 때 부피는 늘어나고 무게는 변하지 않는다. 얼음이 녹을 때 부피는 줄어들고 무게는 변하지 않는다. 얼음이 되어 높이가 높아졌어도 무게는 같으므로 무거워진 것이 아니다.","scoring_points":["얼 때 부피·무게를 썼는가","녹을 때 부피·무게를 썼는가","친구 가의 말을 무게가 같다는 근거로 고쳤는가"]},"explanation":["일지를 읽어요.","높이와 무게를 봐요.","고쳐 써요."],"asset":{"type":"passage","lines":["시험관 물의 높이를 표시하고 무게를 쟀다.","물이 얼자 높이가 표시보다 높아졌고 무게는 같았다.","얼음이 녹자 높이가 다시 낮아졌고 무게는 같았다.","친구 가 — 「얼음이 되어 높아졌으니 무거워졌어.」"],"title":"은하반 일지 ④ 얼리고 녹이기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#1','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C2',1,'mc','auto','은하반 일지 ①의 수족관 물은 물의 어떤 상태인가요?',ARRAY['SC4-1-u2-X04','SC4-1-u2-X01']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C2","difficulty":1,"kind":"mc","stem":"은하반 일지 ①의 수족관 물은 물의 어떤 상태인가요?","options":[{"t":"액체","correct":true},{"t":"고체","mis":"SC4-1-u2-X04"},{"t":"기체","mis":"SC4-1-u2-X04"},{"t":"물이 아니다","mis":"SC4-1-u2-X01"}],"explanation":["수족관 물은 흘러요.","그릇 모양이 돼요.","액체예요."],"asset":{"type":"passage","lines":["수족관 물, 얼음 조각, 끓는 냄비 주변을 살펴보았다.","얼음 조각은 단단해서 손으로 잡을 수 있었다.","냄비 주변의 물은 눈에 보이지 않았다.","친구 가 — 「눈에 안 보이니 냄비 주변엔 물이 없어.」"],"title":"은하반 일지 ① 물 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#2','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C8',1,'mc','auto','은하반 일지 ②에서 손에 칠한 물은 어떻게 되었나요?',ARRAY['SC4-1-u2-X08','SC4-1-u2-X06']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C8","difficulty":1,"kind":"mc","stem":"은하반 일지 ②에서 손에 칠한 물은 어떻게 되었나요?","options":[{"t":"수증기가 되어 공기 중으로 날아갔다","correct":true},{"t":"아주 사라져 없어졌다","mis":"SC4-1-u2-X08"},{"t":"얼음이 되어 손에 남았다","mis":"SC4-1-u2-X06"},{"t":"손 속으로 스며들어 버렸다","mis":"SC4-1-u2-X08"}],"explanation":["둘째 줄을 읽어요.","보이지 않게 됐어요.","첫 번째예요."],"asset":{"type":"passage","lines":["접시의 얼음이 점점 작아지고 물이 생겼다.","손에 칠한 물이 조금 뒤 보이지 않았다.","물을 둥근 컵에서 네모난 컵으로 옮겨 담았다.","친구 나 — 「옮겨 담았으니 물의 상태가 변했어.」"],"title":"은하반 일지 ② 얼음과 물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#3','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C13',1,'mc','auto','은하반 일지 ③에서 풀잎에 맺힌 이슬은 어떻게 생겼나요?',ARRAY['SC4-1-u2-X16','SC4-1-u2-X15','SC4-1-u2-X14']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C13","difficulty":1,"kind":"mc","stem":"은하반 일지 ③에서 풀잎에 맺힌 이슬은 어떻게 생겼나요?","options":[{"t":"공기 중의 수증기가 물로 변해 생겼다","correct":true},{"t":"풀잎 속의 물이 새어 나왔다","mis":"SC4-1-u2-X16"},{"t":"물이 수증기로 변해 생겼다","mis":"SC4-1-u2-X15"},{"t":"얼음이 녹아 생겼다","mis":"SC4-1-u2-X14"}],"explanation":["둘째 줄을 읽어요.","공기 중에서 와요.","첫 번째예요."],"asset":{"type":"passage","lines":["고드름이 녹아 물이 똑똑 떨어졌다.","아침에 풀잎에 이슬이 맺혔다.","젖은 빨래가 오후에 다 말랐다.","친구 다 — 「상태 변화는 실험실에서만 볼 수 있어.」"],"title":"은하반 일지 ③ 생활 속 상태 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#4','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C18',1,'mc','auto','은하반 일지 ④에서 얼음이 녹았을 때 무게는 어떻게 되었나요?',ARRAY['SC4-1-u2-X22','SC4-1-u2-X21']::text[],false,'{"seq":4,"concept":"SC4-1-u2-C18","difficulty":1,"kind":"mc","stem":"은하반 일지 ④에서 얼음이 녹았을 때 무게는 어떻게 되었나요?","options":[{"t":"같았다","correct":true},{"t":"가벼워졌다","mis":"SC4-1-u2-X22"},{"t":"무거워졌다","mis":"SC4-1-u2-X21"},{"t":"무게가 없어졌다","mis":"SC4-1-u2-X22"}],"explanation":["셋째 줄을 읽어요.","무게는 같았어요.","같았어요."],"asset":{"type":"passage","lines":["시험관 물의 높이를 표시하고 무게를 쟀다.","물이 얼자 높이가 표시보다 높아졌고 무게는 같았다.","얼음이 녹자 높이가 다시 낮아졌고 무게는 같았다.","친구 가 — 「얼음이 되어 높아졌으니 무거워졌어.」"],"title":"은하반 일지 ④ 얼리고 녹이기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#5','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C24',1,'mc','auto','은하반 일지 ⑤에서 기포가 계속 생긴 비커에서 일어난 현상은 무엇인가요?',ARRAY['SC4-1-u2-X31','SC4-1-u2-X36','SC4-1-u2-X30']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C24","difficulty":1,"kind":"mc","stem":"은하반 일지 ⑤에서 기포가 계속 생긴 비커에서 일어난 현상은 무엇인가요?","options":[{"t":"끓음","correct":true},{"t":"증발만","mis":"SC4-1-u2-X31"},{"t":"응결","mis":"SC4-1-u2-X36"},{"t":"얼음이 됨","mis":"SC4-1-u2-X30"}],"explanation":["둘째 줄을 읽어요.","기포가 생겼어요.","끓음이에요."],"asset":{"type":"passage","lines":["햇빛에 둔 비커의 물이 며칠 동안 조금씩 줄었다.","가열한 비커에서 기포가 계속 생기며 물이 줄었다.","두 비커 모두 처음 높이보다 낮아졌다.","친구 나 — 「줄어든 물은 아주 사라졌어.」"],"title":"은하반 일지 ⑤ 줄어든 물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#6','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C29',1,'mc','auto','은하반 일지 ⑥에서 물방울이 맺히지 않은 컵은 어느 것인가요?',ARRAY['SC4-1-u2-X35']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C29","difficulty":1,"kind":"mc","stem":"은하반 일지 ⑥에서 물방울이 맺히지 않은 컵은 어느 것인가요?","options":[{"t":"주스만 넣은 컵","correct":true},{"t":"얼음과 주스를 넣은 컵","mis":"SC4-1-u2-X35"},{"t":"두 컵 모두 맺혔다","mis":"SC4-1-u2-X35"},{"t":"두 컵 모두 맺히지 않았다","mis":"SC4-1-u2-X35"}],"explanation":["셋째 줄을 읽어요.","얼음이 없으면요.","주스만 넣은 컵이에요."],"asset":{"type":"passage","lines":["얼음과 포도 주스를 넣은 컵 바깥에 물방울이 맺혔다.","물방울을 닦은 휴지는 젖었지만 보라색이 없었다.","주스만 넣은 컵에는 물방울이 맺히지 않았다.","친구 다 — 「컵 속 주스가 새어 나온 거야.」"],"title":"은하반 일지 ⑥ 컵 바깥 물방울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#7','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C37',1,'mc','auto','은하반 일지 ⑦에서 비닐 가운데에 자갈을 올린 까닭은 무엇인가요?',ARRAY['SC4-1-u2-X44','SC4-1-u2-X45','SC4-1-u2-X41']::text[],false,'{"seq":7,"concept":"SC4-1-u2-C37","difficulty":1,"kind":"mc","stem":"은하반 일지 ⑦에서 비닐 가운데에 자갈을 올린 까닭은 무엇인가요?","options":[{"t":"비닐 가운데가 움푹해져 물방울이 작은 그릇으로 떨어지게 하려고","correct":true},{"t":"비닐을 팽팽하게 펴려고","mis":"SC4-1-u2-X44"},{"t":"장치를 멋지게 꾸미려고","mis":"SC4-1-u2-X45"},{"t":"자갈을 녹여 물을 얻으려고","mis":"SC4-1-u2-X41"}],"explanation":["둘째 줄을 읽어요.","가운데가 낮아져요.","첫 번째예요."],"asset":{"type":"passage","lines":["큰 그릇에 흙탕물을 넣고 가운데에 빈 작은 그릇을 두었다.","비닐을 덮고 가운데에 자갈을 올렸다.","3일 뒤 작은 그릇에 맑은 물이 모였다.","친구 가 — 「지구에 물이 많으니 이런 장치는 필요 없어.」"],"title":"은하반 일지 ⑦ 물을 얻는 장치"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#8','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C43',1,'mc','auto','은하반 일지 ⑧에 적힌 물 절약 방법이 아닌 것은 무엇인가요?',ARRAY['SC4-1-u2-X48']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C43","difficulty":1,"kind":"mc","stem":"은하반 일지 ⑧에 적힌 물 절약 방법이 아닌 것은 무엇인가요?","options":[{"t":"물을 틀어 둔 채 양치하기","correct":true},{"t":"양치 컵 쓰기","mis":"SC4-1-u2-X48"},{"t":"비누칠할 때 물 잠그기","mis":"SC4-1-u2-X48"},{"t":"마실 만큼만 따르기","mis":"SC4-1-u2-X48"}],"explanation":["일지를 읽어요.","낭비하는 것을 찾아요.","첫 번째예요."],"asset":{"type":"passage","lines":["3월 22일 세계 물의 날 포스터를 만들었다.","양치 컵 쓰기, 비누칠할 때 물 잠그기를 적었다.","마실 만큼만 따르기도 적었다.","친구 나 — 「물 아끼기는 어른들이 하면 돼.」"],"title":"은하반 일지 ⑧ 세계 물의 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#9','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C2',2,'mc','auto','물이 세 가지 상태로 있다는 것을 보여 주는 예로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X02']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C2","difficulty":2,"kind":"mc","stem":"물이 세 가지 상태로 있다는 것을 보여 주는 예로 알맞은 것은 무엇인가요?","options":[{"t":"얼음과자, 어항의 물, 끓는 주전자 주변","correct":true},{"t":"컵의 물, 강물, 바닷물","mis":"SC4-1-u2-X02"},{"t":"얼음, 얼음과자, 얼음 틀의 얼음","mis":"SC4-1-u2-X02"},{"t":"수돗물, 호수, 땀","mis":"SC4-1-u2-X02"}],"explanation":["고체·액체·기체를 하나씩요.","세 가지가 달라야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#10','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C10',2,'ox','auto','물이 액체 상태로만 있다면 얼음과자를 만들 수 없어요.',ARRAY['SC4-1-u2-X02']::text[],false,'{"seq":10,"concept":"SC4-1-u2-C10","difficulty":2,"kind":"ox","stem":"물이 액체 상태로만 있다면 얼음과자를 만들 수 없어요.","answer":"O","reason_options":[{"t":"물이 얼어 고체가 될 수 없기 때문에","correct":true},{"t":"물은 원래 액체로만 있기 때문에","mis":"SC4-1-u2-X02"}],"mis":"SC4-1-u2-X02","explanation":["얼음이 될 수 없어요.","얼음과자도요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#11','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C14',2,'ox','auto','고드름이 녹아 생긴 물도 시간이 지나면 수증기로 변해 공기 중으로 날아가요.',ARRAY['SC4-1-u2-X18']::text[],false,'{"seq":11,"concept":"SC4-1-u2-C14","difficulty":2,"kind":"ox","stem":"고드름이 녹아 생긴 물도 시간이 지나면 수증기로 변해 공기 중으로 날아가요.","answer":"O","reason_options":[{"t":"액체인 물이 기체인 수증기로 변하기 때문에","correct":true},{"t":"녹은 물은 그대로 남아 더는 변하지 않기 때문에","mis":"SC4-1-u2-X18"}],"mis":"SC4-1-u2-X18","explanation":["녹은 물도 말라요.","수증기가 돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#12','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C20',2,'ox','auto','추운 겨울 바위틈의 물이 얼면 바위가 쪼개지기도 해요.',ARRAY['SC4-1-u2-X20']::text[],false,'{"seq":12,"concept":"SC4-1-u2-C20","difficulty":2,"kind":"ox","stem":"추운 겨울 바위틈의 물이 얼면 바위가 쪼개지기도 해요.","answer":"O","reason_options":[{"t":"물이 얼면서 부피가 늘어나 바위틈을 밀어 벌리기 때문에","correct":true},{"t":"물이 얼면서 부피가 줄어들기 때문에","mis":"SC4-1-u2-X20"}],"mis":"SC4-1-u2-X20","explanation":["얼면 부피가 늘어요.","틈을 밀어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#13','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C25',2,'ox','auto','증발과 끓음은 걸리는 시간이 달라도 물의 양이 줄어든다는 점이 같아요.',ARRAY['SC4-1-u2-X28']::text[],false,'{"seq":13,"concept":"SC4-1-u2-C25","difficulty":2,"kind":"ox","stem":"증발과 끓음은 걸리는 시간이 달라도 물의 양이 줄어든다는 점이 같아요.","answer":"O","reason_options":[{"t":"두 경우 모두 물이 수증기가 되어 공기 중으로 날아가기 때문에","correct":true},{"t":"증발할 때는 물의 양이 그대로이기 때문에","mis":"SC4-1-u2-X28"}],"mis":"SC4-1-u2-X28","explanation":["두 비커를 떠올려요.","둘 다 줄었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#14','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C29',2,'ox','auto','얼음이 든 비커와 얼음이 없는 비커를 함께 두면 두 비커 바깥면에 물방울이 똑같이 맺혀요.',ARRAY['SC4-1-u2-X35']::text[],false,'{"seq":14,"concept":"SC4-1-u2-C29","difficulty":2,"kind":"ox","stem":"얼음이 든 비커와 얼음이 없는 비커를 함께 두면 두 비커 바깥면에 물방울이 똑같이 맺혀요.","answer":"X","reason_options":[{"t":"차가운 얼음이 든 비커 바깥면에만 물방울이 맺히기 때문에","correct":true},{"t":"비커 바깥면은 언제나 물방울이 맺히기 때문에","mis":"SC4-1-u2-X35"}],"mis":"SC4-1-u2-X35","explanation":["차가운 쪽을 떠올려요.","얼음이 든 쪽만요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#15','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C34',2,'ox','auto','인구가 늘어나고 산업이 발달하는 것도 물 부족의 원인이에요.',ARRAY['SC4-1-u2-X46']::text[],false,'{"seq":15,"concept":"SC4-1-u2-C34","difficulty":2,"kind":"ox","stem":"인구가 늘어나고 산업이 발달하는 것도 물 부족의 원인이에요.","answer":"O","reason_options":[{"t":"물을 쓰는 사람과 공장이 많아지기 때문에","correct":true},{"t":"물 부족은 얼음이 녹는 것 때문에만 생기기 때문에","mis":"SC4-1-u2-X46"}],"mis":"SC4-1-u2-X46","explanation":["물을 쓰는 곳을 떠올려요.","많아져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#16','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C41',2,'ox','auto','세계 물의 날은 물을 마음껏 쓰자는 뜻으로 정한 날이에요.',ARRAY['SC4-1-u2-X47']::text[],false,'{"seq":16,"concept":"SC4-1-u2-C41","difficulty":2,"kind":"ox","stem":"세계 물의 날은 물을 마음껏 쓰자는 뜻으로 정한 날이에요.","answer":"X","reason_options":[{"t":"물의 소중함을 되새기고 중요성을 알리려고 정한 날이기 때문에","correct":true},{"t":"물이 넉넉하다는 것을 축하하는 날이기 때문에","mis":"SC4-1-u2-X47"}],"mis":"SC4-1-u2-X47","explanation":["물의 날의 뜻을 떠올려요.","소중함이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#17','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C9',3,'ox','auto','얼음과 물, 물과 수증기 사이의 상태 변화는 서로 반대 방향으로도 일어나요.',ARRAY['SC4-1-u2-X11']::text[],false,'{"seq":17,"concept":"SC4-1-u2-C9","difficulty":3,"kind":"ox","stem":"얼음과 물, 물과 수증기 사이의 상태 변화는 서로 반대 방향으로도 일어나요.","answer":"O","reason_options":[{"t":"얼음이 녹아 물이 되고 물이 얼어 얼음이 되듯 되돌아갈 수 있기 때문에","correct":true},{"t":"물의 상태 변화는 한 방향으로만 일어나기 때문에","mis":"SC4-1-u2-X11"}],"mis":"SC4-1-u2-X11","explanation":["네 방향을 떠올려요.","되돌아가요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#18','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C13',3,'ox','auto','겨울 교실 유리창 안쪽에 맺힌 물방울은 유리 속의 물이 스며 나온 거예요.',ARRAY['SC4-1-u2-X16']::text[],false,'{"seq":18,"concept":"SC4-1-u2-C13","difficulty":3,"kind":"ox","stem":"겨울 교실 유리창 안쪽에 맺힌 물방울은 유리 속의 물이 스며 나온 거예요.","answer":"X","reason_options":[{"t":"교실 공기 중의 수증기가 차가운 유리창에 닿아 물로 변했기 때문에","correct":true},{"t":"유리는 물을 품고 있다가 겨울에 내보내기 때문에","mis":"SC4-1-u2-X16"}],"mis":"SC4-1-u2-X16","explanation":["공기 중을 떠올려요.","수증기가 물이 돼요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#19','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C19',3,'mc','auto','부피가 큰 스펀지와 부피가 작은 쇠 덩어리를 견줄 때 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X24','SC4-1-u2-X21']::text[],false,'{"seq":19,"concept":"SC4-1-u2-C19","difficulty":3,"kind":"mc","stem":"부피가 큰 스펀지와 부피가 작은 쇠 덩어리를 견줄 때 알맞은 것은 무엇인가요?","options":[{"t":"쇠 덩어리가 부피는 작아도 더 무겁다","correct":true},{"t":"스펀지가 부피가 크니 더 무겁다","mis":"SC4-1-u2-X24"},{"t":"부피가 작은 쇠 덩어리는 무게가 없다","mis":"SC4-1-u2-X24"},{"t":"부피와 무게는 언제나 같이 늘어난다","mis":"SC4-1-u2-X21"}],"explanation":["들어 보면 알아요.","부피와 무게는 따로예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#20','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C26',3,'mc','auto','끓고 있는 주전자의 물이 줄어들었어요. 줄어든 물은 지금 어디에 있을까요?',ARRAY['SC4-1-u2-X08','SC4-1-u2-X30']::text[],false,'{"seq":20,"concept":"SC4-1-u2-C26","difficulty":3,"kind":"mc","stem":"끓고 있는 주전자의 물이 줄어들었어요. 줄어든 물은 지금 어디에 있을까요?","options":[{"t":"수증기가 되어 주위 공기 중에 있다","correct":true},{"t":"아무 데도 없이 사라졌다","mis":"SC4-1-u2-X08"},{"t":"주전자 바닥에서 얼음이 되었다","mis":"SC4-1-u2-X30"},{"t":"주전자 손잡이 속에 숨었다","mis":"SC4-1-u2-X08"}],"explanation":["수증기가 됐어요.","보이지 않을 뿐이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#21','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C31',3,'mc','auto','따뜻한 차를 마실 때 안경이 뿌옇게 흐려지는 까닭은 무엇인가요?',ARRAY['SC4-1-u2-X34','SC4-1-u2-X36','SC4-1-u2-X39']::text[],false,'{"seq":21,"concept":"SC4-1-u2-C31","difficulty":3,"kind":"mc","stem":"따뜻한 차를 마실 때 안경이 뿌옇게 흐려지는 까닭은 무엇인가요?","options":[{"t":"차에서 올라온 수증기가 차가운 안경알에 닿아 응결했기 때문에","correct":true},{"t":"안경알 속의 물이 새어 나왔기 때문에","mis":"SC4-1-u2-X34"},{"t":"안경알에 묻은 물이 증발했기 때문에","mis":"SC4-1-u2-X36"},{"t":"차가 안경알을 뜨겁게 데웠기 때문에","mis":"SC4-1-u2-X39"}],"explanation":["안경알은 차가워요.","수증기가 닿아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#22','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C35',3,'mc','auto','와카워터를 설치하기 좋은 곳은 어디인가요?',ARRAY['SC4-1-u2-X46','SC4-1-u2-X41','SC4-1-u2-X42']::text[],false,'{"seq":22,"concept":"SC4-1-u2-C35","difficulty":3,"kind":"mc","stem":"와카워터를 설치하기 좋은 곳은 어디인가요?","options":[{"t":"물이 부족하고 낮과 밤의 기온 차가 큰 곳","correct":true},{"t":"물이 넘쳐 흐르는 강 한가운데","mis":"SC4-1-u2-X46"},{"t":"얼음을 녹여 쓰는 곳","mis":"SC4-1-u2-X41"},{"t":"물의 상태 변화가 일어나지 않는 곳","mis":"SC4-1-u2-X42"}],"explanation":["물이 필요한 곳이에요.","밤에 서늘해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#23','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C23',4,'mc','auto','친구가 「그늘에 넌 빨래는 햇빛이 없으니 하나도 마르지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X27','SC4-1-u2-X32','SC4-1-u2-X08']::text[],false,'{"seq":23,"concept":"SC4-1-u2-C23","difficulty":4,"kind":"mc","stem":"친구가 「그늘에 넌 빨래는 햇빛이 없으니 하나도 마르지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「그늘에서도 물은 천천히 증발해. 뜨겁지 않아도 증발은 일어나.」","correct":true},{"t":"「맞아, 물은 뜨거워야만 수증기가 돼.」","mis":"SC4-1-u2-X27"},{"t":"「그늘에서는 물이 끓어서 말라.」","mis":"SC4-1-u2-X32"},{"t":"「빨래의 물은 마르면 아주 사라져.」","mis":"SC4-1-u2-X08"}],"explanation":["증발을 떠올려요.","천천히 일어나요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#24','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C40',4,'mc','auto','친구가 「물은 쓰고 나면 다시 깨끗해지니 아낄 필요가 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X40','SC4-1-u2-X08','SC4-1-u2-X49']::text[],false,'{"seq":24,"concept":"SC4-1-u2-C40","difficulty":4,"kind":"mc","stem":"친구가 「물은 쓰고 나면 다시 깨끗해지니 아낄 필요가 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「쓴 물을 다시 깨끗하게 하려면 오랜 시간과 많은 비용이 들어. 쓸 수 있는 물은 점점 줄고 있어.」","correct":true},{"t":"「맞아, 물은 늘 넉넉해.」","mis":"SC4-1-u2-X40"},{"t":"「쓴 물은 사라져 없어지니 괜찮아.」","mis":"SC4-1-u2-X08"},{"t":"「어른들만 아끼면 돼.」","mis":"SC4-1-u2-X49"}],"explanation":["쓴 물을 떠올려요.","시간과 돈이 들어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_c#25','sci',4,1,'u2','','g4_1_sci_u2_review_c','unit_review','SC4-1-u2-C31',4,'essay','teacher','은하반 일지 ⑥을 보고 컵 바깥에 물방울이 생긴 까닭과 이 현상의 이름을 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-1-u2-C31","difficulty":4,"kind":"essay","stem":"은하반 일지 ⑥을 보고 컵 바깥에 물방울이 생긴 까닭과 이 현상의 이름을 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 공기 중의 수증기가 얼음 때문에 차가워진 컵 바깥에 닿아 물로 변했기 때문이다. 이 현상을 응결이라고 한다. 물방울을 닦은 휴지에 보라색이 없고 주스만 넣은 컵에는 맺히지 않았으므로 주스가 새어 나온 것이 아니다.","scoring_points":["까닭을 공기 중 수증기로 썼는가","응결이라고 썼는가","증거를 들어 친구 다의 말을 고쳤는가"]},"explanation":["일지를 읽어요.","이름을 떠올려요.","고쳐 써요."],"asset":{"type":"passage","lines":["얼음과 포도 주스를 넣은 컵 바깥에 물방울이 맺혔다.","물방울을 닦은 휴지는 젖었지만 보라색이 없었다.","주스만 넣은 컵에는 물방울이 맺히지 않았다.","친구 다 — 「컵 속 주스가 새어 나온 거야.」"],"title":"은하반 일지 ⑥ 컵 바깥 물방울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#1','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C4',1,'mc','auto','높은 산 꼭대기에 쌓인 눈은 물의 어떤 상태인가요?',ARRAY['SC4-1-u2-X05','SC4-1-u2-X01']::text[],false,'{"seq":1,"concept":"SC4-1-u2-C4","difficulty":1,"kind":"mc","stem":"높은 산 꼭대기에 쌓인 눈은 물의 어떤 상태인가요?","options":[{"t":"고체","correct":true},{"t":"액체","mis":"SC4-1-u2-X05"},{"t":"기체","mis":"SC4-1-u2-X05"},{"t":"물이 아니다","mis":"SC4-1-u2-X01"}],"explanation":["아주 추워요.","단단해요.","고체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#2','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C5',1,'mc','auto','물의 고체 상태를 무엇이라고 하나요?',ARRAY['SC4-1-u2-X06','SC4-1-u2-X03']::text[],false,'{"seq":2,"concept":"SC4-1-u2-C5","difficulty":1,"kind":"mc","stem":"물의 고체 상태를 무엇이라고 하나요?","options":[{"t":"얼음","correct":true},{"t":"수증기","mis":"SC4-1-u2-X06"},{"t":"물방울","mis":"SC4-1-u2-X06"},{"t":"공기","mis":"SC4-1-u2-X03"}],"explanation":["단단한 물이에요.","차가워요.","얼음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#3','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C12',1,'mc','auto','은하반 일지 ③에서 젖은 빨래가 마른 것은 어떤 상태 변화인가요?',ARRAY['SC4-1-u2-X15']::text[],false,'{"seq":3,"concept":"SC4-1-u2-C12","difficulty":1,"kind":"mc","stem":"은하반 일지 ③에서 젖은 빨래가 마른 것은 어떤 상태 변화인가요?","options":[{"t":"액체에서 기체로","correct":true},{"t":"기체에서 액체로","mis":"SC4-1-u2-X15"},{"t":"고체에서 액체로","mis":"SC4-1-u2-X15"},{"t":"액체에서 고체로","mis":"SC4-1-u2-X15"}],"explanation":["셋째 줄을 읽어요.","물이 수증기가 됐어요.","액체에서 기체로예요."],"asset":{"type":"passage","lines":["고드름이 녹아 물이 똑똑 떨어졌다.","아침에 풀잎에 이슬이 맺혔다.","젖은 빨래가 오후에 다 말랐다.","친구 다 — 「상태 변화는 실험실에서만 볼 수 있어.」"],"title":"은하반 일지 ③ 생활 속 상태 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#4','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C20',1,'mc','auto','물을 가득 담은 페트병을 얼리면 페트병은 어떻게 되나요?',ARRAY['SC4-1-u2-X20','SC4-1-u2-X21']::text[],false,'{"seq":4,"concept":"SC4-1-u2-C20","difficulty":1,"kind":"mc","stem":"물을 가득 담은 페트병을 얼리면 페트병은 어떻게 되나요?","options":[{"t":"부풀어 오른다","correct":true},{"t":"찌그러들어 작아진다","mis":"SC4-1-u2-X20"},{"t":"아무 변화도 없다","mis":"SC4-1-u2-X20"},{"t":"부피는 그대로이고 더 무거워진다","mis":"SC4-1-u2-X21"}],"explanation":["얼면 부피가 늘어요.","병을 밀어요.","부풀어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#5','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C23',1,'mc','auto','은하반 일지 ⑤에서 햇빛에 둔 비커의 물이 며칠 동안 조금씩 줄어든 현상은 무엇인가요?',ARRAY['SC4-1-u2-X31','SC4-1-u2-X36','SC4-1-u2-X30']::text[],false,'{"seq":5,"concept":"SC4-1-u2-C23","difficulty":1,"kind":"mc","stem":"은하반 일지 ⑤에서 햇빛에 둔 비커의 물이 며칠 동안 조금씩 줄어든 현상은 무엇인가요?","options":[{"t":"증발","correct":true},{"t":"끓음","mis":"SC4-1-u2-X31"},{"t":"응결","mis":"SC4-1-u2-X36"},{"t":"얼음이 녹음","mis":"SC4-1-u2-X30"}],"explanation":["첫 줄을 읽어요.","표면에서 천천히요.","증발이에요."],"asset":{"type":"passage","lines":["햇빛에 둔 비커의 물이 며칠 동안 조금씩 줄었다.","가열한 비커에서 기포가 계속 생기며 물이 줄었다.","두 비커 모두 처음 높이보다 낮아졌다.","친구 나 — 「줄어든 물은 아주 사라졌어.」"],"title":"은하반 일지 ⑤ 줄어든 물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#6','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C31',1,'mc','auto','은하반 일지 ⑥에서 컵 바깥에 물방울이 맺힌 현상을 무엇이라고 하나요?',ARRAY['SC4-1-u2-X36']::text[],false,'{"seq":6,"concept":"SC4-1-u2-C31","difficulty":1,"kind":"mc","stem":"은하반 일지 ⑥에서 컵 바깥에 물방울이 맺힌 현상을 무엇이라고 하나요?","options":[{"t":"응결","correct":true},{"t":"증발","mis":"SC4-1-u2-X36"},{"t":"끓음","mis":"SC4-1-u2-X36"},{"t":"녹음","mis":"SC4-1-u2-X36"}],"explanation":["수증기가 물이 됐어요.","오늘의 낱말이에요.","응결이에요."],"asset":{"type":"passage","lines":["얼음과 포도 주스를 넣은 컵 바깥에 물방울이 맺혔다.","물방울을 닦은 휴지는 젖었지만 보라색이 없었다.","주스만 넣은 컵에는 물방울이 맺히지 않았다.","친구 다 — 「컵 속 주스가 새어 나온 거야.」"],"title":"은하반 일지 ⑥ 컵 바깥 물방울"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#7','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C35',1,'mc','auto','와카워터처럼 공기 중의 수증기를 물로 모으는 장치가 이용한 상태 변화는 무엇인가요?',ARRAY['SC4-1-u2-X41']::text[],false,'{"seq":7,"concept":"SC4-1-u2-C35","difficulty":1,"kind":"mc","stem":"와카워터처럼 공기 중의 수증기를 물로 모으는 장치가 이용한 상태 변화는 무엇인가요?","options":[{"t":"응결","correct":true},{"t":"녹음","mis":"SC4-1-u2-X41"},{"t":"끓음","mis":"SC4-1-u2-X41"},{"t":"얼음이 됨","mis":"SC4-1-u2-X41"}],"explanation":["수증기가 물이 돼요.","그 이름은?","응결이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#8','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C42',1,'mc','auto','우리가 쓸 수 있는 물에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X40']::text[],false,'{"seq":8,"concept":"SC4-1-u2-C42","difficulty":1,"kind":"mc","stem":"우리가 쓸 수 있는 물에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"지구의 물 가운데 아주 적고, 점점 부족해지고 있다","correct":true},{"t":"지구의 물 모두를 쓸 수 있다","mis":"SC4-1-u2-X40"},{"t":"바닷물을 그대로 마실 수 있어 넉넉하다","mis":"SC4-1-u2-X40"},{"t":"물은 쓰면 쓸수록 늘어난다","mis":"SC4-1-u2-X40"}],"explanation":["세계 물의 날을 떠올려요.","적어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#9','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C4',2,'ox','auto','동물과 식물의 몸속에도 액체 상태의 물이 있어요.',ARRAY['SC4-1-u2-X05']::text[],false,'{"seq":9,"concept":"SC4-1-u2-C4","difficulty":2,"kind":"ox","stem":"동물과 식물의 몸속에도 액체 상태의 물이 있어요.","answer":"O","reason_options":[{"t":"생물의 몸속에도 물이 있어 살아가는 데 쓰이기 때문에","correct":true},{"t":"생물의 몸속은 물이 없이 말라 있기 때문에","mis":"SC4-1-u2-X05"}],"mis":"SC4-1-u2-X05","explanation":["몸을 떠올려요.","땀과 피가 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#10','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C5',2,'mc','auto','얼음, 물, 수증기와 그 상태를 바르게 짝 지은 것은 무엇인가요?',ARRAY['SC4-1-u2-X06']::text[],false,'{"seq":10,"concept":"SC4-1-u2-C5","difficulty":2,"kind":"mc","stem":"얼음, 물, 수증기와 그 상태를 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"얼음 — 고체, 물 — 액체, 수증기 — 기체","correct":true},{"t":"얼음 — 액체, 물 — 고체, 수증기 — 기체","mis":"SC4-1-u2-X06"},{"t":"얼음 — 고체, 물 — 기체, 수증기 — 액체","mis":"SC4-1-u2-X06"},{"t":"얼음 — 기체, 물 — 액체, 수증기 — 고체","mis":"SC4-1-u2-X06"}],"explanation":["얼음은 단단해요.","수증기는 보이지 않아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#11','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C15',2,'mc','auto','생활 속 물의 상태 변화를 조사한 결과를 발표할 때 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X19','SC4-1-u2-X17']::text[],false,'{"seq":11,"concept":"SC4-1-u2-C15","difficulty":2,"kind":"mc","stem":"생활 속 물의 상태 변화를 조사한 결과를 발표할 때 가장 알맞은 것은 무엇인가요?","options":[{"t":"어디에서 찾은 정보인지 출처를 함께 밝힌다","correct":true},{"t":"출처는 빼고 재미있는 내용만 말한다","mis":"SC4-1-u2-X19"},{"t":"확인하지 않은 소문도 사실처럼 말한다","mis":"SC4-1-u2-X19"},{"t":"실험실에서 본 것만 말한다","mis":"SC4-1-u2-X17"}],"explanation":["정보를 믿을 수 있나요?","출처를 밝혀요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#12','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C22',2,'mc','auto','시험관 속 물이 얼기 전과 언 뒤의 부피 변화를 견주는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X26','SC4-1-u2-X13']::text[],false,'{"seq":12,"concept":"SC4-1-u2-C22","difficulty":2,"kind":"mc","stem":"시험관 속 물이 얼기 전과 언 뒤의 부피 변화를 견주는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"물의 높이와 얼음의 높이를 색이 다른 유성펜으로 표시해 견준다","correct":true},{"t":"높이를 표시하지 않고 기억해 둔다","mis":"SC4-1-u2-X26"},{"t":"시험관을 흔들어 소리로 견준다","mis":"SC4-1-u2-X26"},{"t":"얼음을 꺼내 맛을 보며 견준다","mis":"SC4-1-u2-X13"}],"explanation":["높이를 표시해요.","색을 달리해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#13','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C28',2,'mc','auto','끓음을 이용하는 예는 무엇인가요?',ARRAY['SC4-1-u2-X32']::text[],false,'{"seq":13,"concept":"SC4-1-u2-C28","difficulty":2,"kind":"mc","stem":"끓음을 이용하는 예는 무엇인가요?","options":[{"t":"따뜻한 차를 마시려고 물을 끓인다","correct":true},{"t":"오징어를 널어 말린다","mis":"SC4-1-u2-X32"},{"t":"염전에서 소금을 얻는다","mis":"SC4-1-u2-X32"},{"t":"젖은 인형을 햇빛에 말린다","mis":"SC4-1-u2-X32"}],"explanation":["끓이는 것을 찾아요.","차를 끓여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#14','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C30',2,'mc','auto','얼음이 든 비커 바깥면의 물방울을 모두 닦은 뒤 무게를 재면 어떻게 될까요?',ARRAY['SC4-1-u2-X34','SC4-1-u2-X38']::text[],false,'{"seq":14,"concept":"SC4-1-u2-C30","difficulty":2,"kind":"mc","stem":"얼음이 든 비커 바깥면의 물방울을 모두 닦은 뒤 무게를 재면 어떻게 될까요?","options":[{"t":"물방울이 맺히기 전 처음 무게와 같다","correct":true},{"t":"처음보다 훨씬 가볍다","mis":"SC4-1-u2-X34"},{"t":"처음보다 무겁다","mis":"SC4-1-u2-X38"},{"t":"물방울이 없어지니 무게도 없어진다","mis":"SC4-1-u2-X38"}],"explanation":["바깥에서 온 물을 닦았어요.","처음으로 돌아가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
