INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#16','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C44',2,'mc','auto','물 아끼기를 언제부터 실천하는 것이 가장 알맞을까요?',ARRAY['SC4-1-u2-X49']::text[],false,'{"seq":16,"concept":"SC4-1-u2-C44","difficulty":2,"kind":"mc","stem":"물 아끼기를 언제부터 실천하는 것이 가장 알맞을까요?","options":[{"t":"지금 바로 나부터","correct":true},{"t":"물이 모두 없어진 뒤부터","mis":"SC4-1-u2-X49"},{"t":"어른이 된 뒤부터","mis":"SC4-1-u2-X49"},{"t":"다른 사람이 먼저 한 뒤부터","mis":"SC4-1-u2-X49"}],"explanation":["미루지 않아요.","나부터요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#17','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C10',3,'mc','auto','물이 액체 상태로만 있다면 겨울 호수는 어떻게 될까요?',ARRAY['SC4-1-u2-X12','SC4-1-u2-X08']::text[],false,'{"seq":17,"concept":"SC4-1-u2-C10","difficulty":3,"kind":"mc","stem":"물이 액체 상태로만 있다면 겨울 호수는 어떻게 될까요?","options":[{"t":"겨울에도 얼지 않고 액체로 남아 있다","correct":true},{"t":"겨울이면 단단한 얼음판이 된다","mis":"SC4-1-u2-X12"},{"t":"호수의 물이 모두 사라진다","mis":"SC4-1-u2-X08"},{"t":"지금과 달라지는 것이 없다","mis":"SC4-1-u2-X12"}],"explanation":["얼음이 될 수 없어요.","계속 물이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#18','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C11',3,'mc','auto','컬링 경기장의 얼음판에서 알 수 있는 상태 변화는 무엇인가요?',ARRAY['SC4-1-u2-X14','SC4-1-u2-X16','SC4-1-u2-X15']::text[],false,'{"seq":18,"concept":"SC4-1-u2-C11","difficulty":3,"kind":"mc","stem":"컬링 경기장의 얼음판에서 알 수 있는 상태 변화는 무엇인가요?","options":[{"t":"액체인 물이 고체인 얼음으로 변했다","correct":true},{"t":"고체인 얼음이 액체인 물로 변했다","mis":"SC4-1-u2-X14"},{"t":"수증기가 물로 변했다","mis":"SC4-1-u2-X16"},{"t":"물이 수증기로 변했다","mis":"SC4-1-u2-X15"}],"explanation":["물을 얼려 만들어요.","물이 얼음이 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#19','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C20',3,'mc','auto','한겨울 밖에 둔, 물이 가득 든 장독이 깨지는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X21','SC4-1-u2-X20','SC4-1-u2-X25']::text[],false,'{"seq":19,"concept":"SC4-1-u2-C20","difficulty":3,"kind":"mc","stem":"한겨울 밖에 둔, 물이 가득 든 장독이 깨지는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"물이 얼어 얼음이 되면서 부피가 늘어났기 때문에","correct":true},{"t":"물이 얼면서 무게가 늘어났기 때문에","mis":"SC4-1-u2-X21"},{"t":"물이 얼면서 부피가 줄어들었기 때문에","mis":"SC4-1-u2-X20"},{"t":"추위에 장독이 저절로 약해졌기 때문에","mis":"SC4-1-u2-X25"}],"explanation":["얼면 부피가 늘어요.","장독을 밀어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#20','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C25',3,'mc','auto','증발과 끓음에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X30','SC4-1-u2-X27','SC4-1-u2-X31']::text[],false,'{"seq":20,"concept":"SC4-1-u2-C25","difficulty":3,"kind":"mc","stem":"증발과 끓음에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"둘 다 액체와 기체 사이의 상태 변화이다","correct":true},{"t":"둘 다 고체와 액체 사이의 상태 변화이다","mis":"SC4-1-u2-X30"},{"t":"증발은 끓을 때에만 일어난다","mis":"SC4-1-u2-X27"},{"t":"끓음은 물 표면에서만 일어난다","mis":"SC4-1-u2-X31"}],"explanation":["물이 수증기가 돼요.","액체와 기체예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#21','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C33',3,'mc','auto','물이 증발할 때와 수증기가 응결할 때를 바르게 견준 것은 무엇인가요?',ARRAY['SC4-1-u2-X36']::text[],false,'{"seq":21,"concept":"SC4-1-u2-C33","difficulty":3,"kind":"mc","stem":"물이 증발할 때와 수증기가 응결할 때를 바르게 견준 것은 무엇인가요?","options":[{"t":"증발하면 물이 수증기가 되고, 응결하면 수증기가 물이 된다","correct":true},{"t":"증발과 응결은 같은 방향의 상태 변화이다","mis":"SC4-1-u2-X36"},{"t":"응결하면 물이 얼음이 된다","mis":"SC4-1-u2-X36"},{"t":"증발하면 수증기가 물이 된다","mis":"SC4-1-u2-X36"}],"explanation":["방향이 반대예요.","이름을 맞춰요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#22','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C43',3,'mc','auto','학교에서 물을 아끼는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u2-X48']::text[],false,'{"seq":22,"concept":"SC4-1-u2-C43","difficulty":3,"kind":"mc","stem":"학교에서 물을 아끼는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"손을 씻을 때 비누칠하는 동안 수도꼭지를 잠근다","correct":true},{"t":"쉬는 시간마다 물장난을 한다","mis":"SC4-1-u2-X48"},{"t":"물을 틀어 둔 채 친구와 이야기한다","mis":"SC4-1-u2-X48"},{"t":"물통의 물을 마시지 않고 버린다","mis":"SC4-1-u2-X48"}],"explanation":["잠그는 것을 찾아요.","비누칠할 때요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#23','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C30',4,'mc','auto','친구가 「얼음이 든 컵 바깥의 물방울은 얼음이 녹아 컵을 뚫고 나온 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X34','SC4-1-u2-X36','SC4-1-u2-X35']::text[],false,'{"seq":23,"concept":"SC4-1-u2-C30","difficulty":4,"kind":"mc","stem":"친구가 「얼음이 든 컵 바깥의 물방울은 얼음이 녹아 컵을 뚫고 나온 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「얼음을 안 넣은 컵엔 안 맺히고 물방울에 음료수 색도 없어. 공기 중 수증기가 응결한 거야.」","correct":true},{"t":"「맞아, 얼음이 녹으면 컵을 뚫고 나와.」","mis":"SC4-1-u2-X34"},{"t":"「컵 바깥의 물이 증발해서 맺힌 거야.」","mis":"SC4-1-u2-X36"},{"t":"「물방울은 아무 컵에나 똑같이 맺혀.」","mis":"SC4-1-u2-X35"}],"explanation":["색을 떠올려요.","차가운 컵에만요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#24','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C36',4,'mc','auto','친구가 「빗물 저금통도 와카워터처럼 수증기가 물로 변하는 것을 이용해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u2-X42','SC4-1-u2-X41']::text[],false,'{"seq":24,"concept":"SC4-1-u2-C36","difficulty":4,"kind":"mc","stem":"친구가 「빗물 저금통도 와카워터처럼 수증기가 물로 변하는 것을 이용해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「빗물 저금통은 내린 빗물을 그대로 모으는 거라 상태 변화를 이용한 장치가 아니야.」","correct":true},{"t":"「맞아, 빗물 저금통은 응결을 이용해.」","mis":"SC4-1-u2-X42"},{"t":"「빗물 저금통은 얼음을 녹여 물을 얻어.」","mis":"SC4-1-u2-X41"},{"t":"「와카워터는 물을 끓여 모아.」","mis":"SC4-1-u2-X41"}],"explanation":["상태가 변하나요?","빗물은 그대로예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u2_review_d#25','sci',4,1,'u2','','g4_1_sci_u2_review_d','unit_review','SC4-1-u2-C38',4,'essay','teacher','은하반 일지 ⑦을 보고 작은 그릇에 맑은 물이 모인 까닭을 증발과 응결을 넣어 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-1-u2-C38","difficulty":4,"kind":"essay","stem":"은하반 일지 ⑦을 보고 작은 그릇에 맑은 물이 모인 까닭을 증발과 응결을 넣어 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 햇빛을 받아 흙탕물의 물만 증발해 수증기가 되고, 수증기가 비닐 안쪽에 닿아 응결해 물방울이 된 뒤 움푹한 가운데로 흘러 작은 그릇에 떨어졌다. 지구에 물이 많아도 쓸 수 있는 깨끗한 물은 점점 줄어들고 있어 이런 장치가 필요하다.","scoring_points":["증발과 응결을 차례대로 썼는가","흙은 남고 물만 모인 까닭을 썼는가","친구 가의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","증발 → 응결이에요.","고쳐 써요."],"asset":{"type":"passage","lines":["큰 그릇에 흙탕물을 넣고 가운데에 빈 작은 그릇을 두었다.","비닐을 덮고 가운데에 자갈을 올렸다.","3일 뒤 작은 그릇에 맑은 물이 모였다.","친구 가 — 「지구에 물이 많으니 이런 장치는 필요 없어.」"],"title":"은하반 일지 ⑦ 물을 얻는 장치"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
